public class Main {
    static class Processor {
        private final Scanner sc;
        private final int[] btcCosts;
        private int even;
        private int odd;
        private int right;

        Processor(Scanner sc) {
            this.sc = sc;
            this.btcCosts = new int[100];
        }

        private int nextLeft() {
            if (right == 0) {
                return sc.nextInt();
            }
            int result = right;
            right = 0;
            return result;
        }

        void process(int n) {
            for (int i = 0; i < n; i++) {
                int left = nextLeft();

                if ((left & 1) == 0) {
                    even++;
                } else {
                    odd++;
                }

                if (even == odd && i != n - 1) {
                    right = sc.nextInt();
                    int btcCost = Math.abs(left - right);
                    btcCosts[btcCost] += 1;
                    even = 0;
                    odd = 0;
                }
            }
        }

        int calculate(int btcAmount) {
            int sawedAmount = 0;
            int currentBTCCost = 0;
            for (int i = 0; i < 100; i++) {
                for (int j = 0; j < btcCosts[i]; j++) {
                    currentBTCCost += i;
                    if (currentBTCCost <= btcAmount) {
                        sawedAmount++;
                    } else {
                        break;
                    }
                }
            }
            return sawedAmount;
        }
    }

