    private static int maxCuts(int[] costs, int b) {
        int cut = 0;
        long sum = 0;
        for (int i = 0; i < costs.length; i++) {
            if (costs[i] != -1 && sum + costs[i] <= b) {
                cut++;
                sum += costs[i];
            }
        }
        return cut;
    }
