import java.util.*;
import java.io.*;

public class CF998B {
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;
        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }
        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    static List<Integer> cuts;
    static int[][] memo;

    static int solve(int idx, int cap) {
        if (idx == 0 || cap == 0) {
            return 0;
        }
        if (memo[idx][cap] != -1) {
            return memo[idx][cap];
        }
        int cost = cuts.get(idx - 1);
        int best;
        if (cost <= cap) {
            best = Math.max(1 + solve(idx - 1, cap - cost), solve(idx - 1, cap));
        } else {
            best = solve(idx - 1, cap);
        }
        memo[idx][cap] = best;
        return best;
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        int n = sc.nextInt();
        int w = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }
        cuts = new ArrayList<Integer>();
        int even = 0;
        int odd = 0;
        for (int i = 0; i < n - 1; i++) {
            if ((a[i] & 1) == 0) {
                even++;
            } else {
                odd++;
            }
            if (even == odd) {
                cuts.add(Math.abs(a[i] - a[i + 1]));
            }
        }
        memo = new int[cuts.size() + 1][w + 1];
        for (int[] row : memo) {
            Arrays.fill(row, -1);
        }
        PrintWriter out = new PrintWriter(System.out);
        out.println(solve(cuts.size(), w));
        out.close();
    }
}

