public class MMain {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int B = sc.nextInt();
        int[] a = new int[n];

        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        if (B < 0) {
            System.out.print(0);
            System.out.flush();
            return;
        }

        TreeMap<Integer, Integer> freq = new TreeMap<>();
        int even = 0;
        int odd = 0;

        for (int i = 0; i < n - 1; i++) {
            if ((a[i] & 1) == 0) {
                even++;
            } else {
                odd++;
            }
            if (even == odd) {
                int diff = Math.abs(a[i] - a[i + 1]);
                freq.put(diff, freq.getOrDefault(diff, 0) + 1);
            }
        }

        int ans = 0;
        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            int gap = entry.getKey();
            int count = entry.getValue();
            if ((long) gap * count <= B) {
                ans += count;
                B -= (int) ((long) gap * count);
            } else {
                if (gap != 0) {
                    ans += B / gap;
                }
                break;
            }
        }

        System.out.print(ans);
        System.out.flush();
    }
}

