public class MMain {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int B = sc.nextInt();
        int[] a = new int[n];

        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        int[] diffs = new int[Math.max(0, n - 1)];
        int cnt = 0;
        int even = 0;
        int odd = 0;

        for (int i = 0; i < n - 1; i++) {
            if ((a[i] & 1) == 0) {
                even++;
            } else {
                odd++;
            }
            if (even == odd) {
                diffs[cnt++] = Math.abs(a[i] - a[i + 1]);
            }
        }

        if (cnt > 1) {
            mergeSort(diffs, 0, cnt - 1);
        }

        int ans = 0;
        for (int i = 0; i < cnt; i++) {
            if (diffs[i] <= B) {
                ans++;
                B -= diffs[i];
            } else {
                break;
            }
        }

        System.out.print(ans);
        System.out.flush();
    }

    static void mergeSort(int[] arr, int l, int r) {
        if (l < r) {
            int m = (l + r) >>> 1;
            mergeSort(arr, l, m);
            mergeSort(arr, m + 1, r);
            merge(arr, l, m, r);
        }
    }

    static void merge(int[] arr, int l, int m, int r) {
        int[] left = Arrays.copyOfRange(arr, l, m + 1);
        int[] right = Arrays.copyOfRange(arr, m + 1, r + 1);
        int i = 0;
        int j = 0;
        int k = l;
        while (i < left.length && j < right.length) {
            if (left[i] <= right[j]) {
                arr[k++] = left[i++];
            } else {
                arr[k++] = right[j++];
            }
        }
        while (i < left.length) {
            arr[k++] = left[i++];
        }
        while (j < right.length) {
            arr[k++] = right[j++];
        }
    }
}

