        for (int i = 0; i < n; i++) {
            prefixEven[i + 1] = prefixEven[i] + (a[i] % 2 == 0 ? 1 : 0);
        }

        List<Integer> costs = IntStream.range(0, n - 1)
                .filter(i -> prefixEven[i + 1] > 0 && prefixEven[i + 1] * 2 == i + 1)
                .map(i -> Math.abs(a[i] - a[i + 1]))
                .boxed()
                .sorted()
                .collect(Collectors.toList());

        int count = 0;
