import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int n = s.nextInt();
        int b = s.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = s.nextInt();
        }
        System.out.println(maxCuttings(arr, b));
    }

    private static int maxCuttings(int[] arr, int b) {
        ArrayList<Integer> costs = new ArrayList<>();
        int numEvens = arr[0] % 2 == 0 ? 1 : 0;
        int numOdds = arr[0] % 2 == 1 ? 1 : 0;
        int numCuttings = 0;
        for (int i = 1; i < arr.length; i++) {
            if (numOdds == numEvens&& Math.abs(arr[i]-arr[i-1])<=b) {
                numEvens = 0;
                numOdds = 0;
                costs.add(Math.abs(arr[i]-arr[i-1]));
            }
            if (arr[i] % 2 == 0) ++numEvens;
            else ++numOdds;
        }
        Collections.sort(costs);
        for(int i=0;i<costs.size();i++){
            if(b<costs.get(i))
                break;
            ++numCuttings;
            b-=costs.get(i);
        }
        return numCuttings;
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int b = in.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = in.nextInt();
        }
        System.out.println(maxCuts(a, b));
    }

    private static int maxCuts(int[] a, int b) {
        int[] costs = new int[a.length];
        int len = 0;
        int evens = a[0] % 2 == 0 ? 1 : 0;
        int odds = a[0] % 2 == 1 ? 1 : 0;
        int cuts = 0;

        for (int i = 1; i < a.length; i++) {
            int cost = Math.abs(a[i] - a[i - 1]);
            if (odds == evens && cost <= b) {
                evens = 0;
                odds = 0;
                costs[len++] = cost;
            }
            if (a[i] % 2 == 0) {
                evens++;
            } else {
                odds++;
            }
        }

        for (int i = 1; i < len; i++) {
            int value = costs[i];
            int j = i - 1;
            while (j >= 0 && costs[j] > value) {
                costs[j + 1] = costs[j];
                j--;
            }
            costs[j + 1] = value;
        }

        for (int i = 0; i < len; i++) {
            if (b < costs[i]) {
                break;
            }
            cuts++;
            b -= costs[i];
        }
        return cuts;
    }
}

import java.util.Scanner;
import java.util.TreeMap;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int budget = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }
        System.out.println(maxCuttings(arr, budget));
    }

    private static int maxCuttings(int[] arr, int budget) {
        TreeMap<Integer, Integer> costs = new TreeMap<>();
        int evens = arr[0] % 2 == 0 ? 1 : 0;
        int odds = arr[0] % 2 == 1 ? 1 : 0;
        int cuts = 0;

        for (int i = 1; i < arr.length; i++) {
            int cost = Math.abs(arr[i] - arr[i - 1]);
            if (odds == evens && cost <= budget) {
                evens = 0;
                odds = 0;
                Integer count = costs.get(cost);
                costs.put(cost, count == null ? 1 : count + 1);
            }
            if (arr[i] % 2 == 0) {
                evens++;
            } else {
                odds++;
            }
        }

        for (java.util.Map.Entry<Integer, Integer> entry : costs.entrySet()) {
            int cost = entry.getKey();
            int times = entry.getValue();
            while (times > 0 && budget >= cost) {
                budget -= cost;
                cuts++;
                times--;
            }
            if (budget < cost) {
                break;
            }
        }
        return cuts;
    }
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner reader = new Scanner(System.in);
        int n = reader.nextInt();
        int b = reader.nextInt();
        int[] x = new int[n];
        for (int i = 0; i < n; i++) {
            x[i] = reader.nextInt();
        }
        System.out.println(solve(x, b));
    }

    private static int solve(int[] x, int b) {
        ArrayList<Integer> costs = new ArrayList<>();
        int evens = x[0] % 2 == 0 ? 1 : 0;
        int odds = x[0] % 2 == 1 ? 1 : 0;
        int cuts = 0;
        int i = 1;

        while (i < x.length) {
            int current = x[i];
            int previous = x[i - 1];
            if (odds == evens && Math.abs(current - previous) <= b) {
                odds = 0;
                evens = 0;
                costs.add(Math.abs(current - previous));
            }
            if (current % 2 == 0) {
                evens++;
            } else {
                odds++;
            }
            i++;
        }

        costs.sort(null);

        int remaining = b;
        for (int cost : costs) {
            if (remaining < cost) {
                break;
            }
            cuts++;
            remaining -= cost;
        }
        return cuts;
    }
}

import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int b = scanner.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = scanner.nextInt();
        }
        System.out.println(answer(arr, b));
    }

    private static int answer(int[] arr, int b) {
        PriorityQueue<Integer> costs = new PriorityQueue<>();
        int numsEven = arr[0] % 2 == 0 ? 1 : 0;
        int numsOdd = arr[0] % 2 == 1 ? 1 : 0;

        for (int i = 1; i < arr.length; i++) {
            int cost = Math.abs(arr[i] - arr[i - 1]);
            if (numsOdd == numsEven && cost <= b) {
                numsOdd = 0;
                numsEven = 0;
                costs.add(cost);
            }
            if (arr[i] % 2 == 0) {
                numsEven++;
            } else {
                numsOdd++;
            }
        }

        int cuts = 0;
        while (!costs.isEmpty() && costs.peek() <= b) {
            b -= costs.poll();
            cuts++;
        }
        return cuts;
    }
}

