            for(int i=1;i<len-1;i++){
                if(valid[i] && !used[i]){
                    int cost = Math.abs(aArr[i]-aArr[i+1]);
                    if(cost < minCost){
                        minCost = cost;
                        minInd = i;
                    }
                }
            }
            if(minInd==-1) break;
            used[minInd]=true;
            nCoins -= minCost;
            nCuts++;
        }
        return nCuts;
    }

