        for (int i = 0; i < n; i++) {
            sum += (arr[i] % 2 == 0) ? -1 : 1;
            prefix[i] = sum;
        }
        ArrayList<Integer> cost = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            if (prefix[i] == 0) {
                cost.add(Math.abs(arr[i + 1] - arr[i]));
            }
        }
        Collections.sort(cost);
        int tcost = 0, maxp = 0;
        for (Integer c : cost) {
            if (tcost + c <= b) {
                tcost += c;
                maxp++;
            }
        }
        System.out.println(maxp);
    }
}

