        static int maxMatching(List<Integer>[] g, int cols) {
            int n = g.length;
            int[] matchL = new int[n];
            int[] matchR = new int[n];
            Arrays.fill(matchL, -1);
            Arrays.fill(matchR, -1);
            int pairs = 0;

            for (int u = 0; u < n; u++) {
                int r = u / cols;
                int c = u % cols;
                if (((r + c) & 1) == 0 && matchL[u] == -1) {
                    if (augment(g, u, matchL, matchR)) {
                        pairs++;
                    }
                }
            }
            return pairs;
        }

        static boolean augment(List<Integer>[] g, int root, int[] matchL, int[] matchR) {
            int n = g.length;
            int[] prevL = new int[n];
            int[] prevR = new int[n];
            Arrays.fill(prevL, -1);
            Arrays.fill(prevR, -1);
            Queue<Integer> q = new ArrayDeque<>();
            q.add(root);

            while (!q.isEmpty()) {
                int u = q.poll();
                for (int v : g[u]) {
                    if (prevR[v] != -1) continue;
                    prevR[v] = u;
                    if (matchR[v] == -1) {
                        int curR = v;
                        while (curR != -1) {
                            int curL = prevR[curR];
                            int nextR = matchL[curL];
                            matchL[curL] = curR;
                            matchR[curR] = curL;
                            curR = nextR;
                        }
                        return true;
                    } else {
                        int nextL = matchR[v];
                        if (prevL[nextL] == -1) {
                            prevL[nextL] = u;
                            q.add(nextL);
                        }
                    }
                }
            }
            return false;
        }
    }

