        DataInputStream in = new DataInputStream(System.in);
        long a = readInt(in);
        long b = readInt(in);
        if (a > b) {
            long t = a;
            a = b;
            b = t;
        }
        long ans;
        if (a == 1) {
            long r = b % 6;
            if (r <= 3) ans = b - r;
            else if (r == 4) ans = b - 2;
            else ans = b - 1;
        } else if (a <= 5 && b <= 30) {
            ans = solveSmall((int) a, (int) b);
        } else {
            ans = a * b - a * b % 2;
        }
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        out.println(ans);
        out.close();
    }

    static int readInt(DataInputStream in) throws IOException {
        int c = in.read();
        while (c <= ' ') c = in.read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = in.read();
        }
        int res = 0;
        while (c > ' ') {
            if (c < '0' || c > '9') throw new IOException();
            res = res * 10 + (c - '0');
            c = in.read();
        }
        return res * sgn;
    }

    static int solveSmall(int n, int m) {
        int states = 1 << (3 * n);
        int[] dp = new int[(m + 1) * (n + 1) * states];
        for (int col = 0; col <= n; col++) {
            for (int mask = 0; mask < states; mask++) {
                dp[idx(m, n, states, m, col, mask)] = mask == 0 ? 0 : Integer.MIN_VALUE;
            }
        }
        for (int row = m - 1; row >= 0; row--) {
            for (int mask = 0; mask < states; mask++) {
                dp[idx(m, n, states, row, n, mask)] = dp[idx(m, n, states, row + 1, 0, mask)];
            }
            for (int col = n - 1; col >= 0; col--) {
                for (int mask = 0; mask < states; mask++) {
                    if ((mask & 1) == 1) {
                        dp[idx(m, n, states, row, col, mask)] = dp[idx(m, n, states, row, col + 1, mask >> 1)];
                        continue;
                    }
                    int val = dp[idx(m, n, states, row, col + 1, mask >> 1)];
                    val = Math.max(val, dp[idx(m, n, states, row, col + 1, (mask >> 1) + (1 << (3 * n - 1)))] + 2);
                    if (col != 0 && ((mask >> (2 * n - 1)) & 1) == 0) {
                        val = Math.max(val, dp[idx(m, n, states, row, col + 1, (mask >> 1) + (1 << (2 * n - 2)))] + 2);
                    }
                    if (col != n - 1 && ((mask >> (2 * n + 1)) & 1) == 0) {
                        val = Math.max(val, dp[idx(m, n, states, row, col + 1, (mask >> 1) + (1 << (2 * n)))] + 2);
                    }
                    if (col >= 2 && ((mask >> (n - 2)) & 1) == 0) {
                        val = Math.max(val, dp[idx(m, n, states, row, col + 1, (mask >> 1) + (1 << (n - 3)))] + 2);
                    }
                    if (col < n - 1 && ((mask >> (n + 2)) & 1) == 0) {
                        val = Math.max(val, dp[idx(m, n, states, row, col + 1, (mask >> 1) + (1 << (n + 1)))] + 2);
                    }
                    dp[idx(m, n, states, row, col, mask)] = val;
                }
            }
        }
        return dp[idx(m, n, states, 0, 0, 0)];
    }

    static int idx(int m, int n, int states, int row, int col, int mask) {
        return ((row * (n + 1) + col) * states + mask);
    }
}

