            }
            boolean neg = (c == '-');
            if (neg) {
                c = read();
            }
            int ret = 0;
            while (c >= '0' && c <= '9') {
                ret = ret * 10 + (c - '0');
                c = read();
            }
            return neg ? -ret : ret;
        }

        private byte read() {
            if (pos >= data.length) return -1;
            return data[pos++];
        }
    }
}

