        int lo = Math.min(n, m);
        int hi = Math.max(n, m);
        solve(lo, hi);
    }

    private static void solve(int n, int m) {
        long answer;
        if (n == 1) {
            int everySix = (m / 6) * 3;
            int remainder = m % 6;
            int extra = Math.max(remainder - 3, 0);
            answer = (everySix + extra) << 1;
        } else if (n == 2) {
            if (m == 2) {
                answer = 0;
            } else if (m == 3) {
                answer = 4;
            } else if (m == 7) {
                answer = 12;
            } else {
                answer = m << 1;
            }
        } else {
            answer = 1L * n * m / 2 * 2;
        }
        System.out.println(answer);
    }
}

