        }
        PrintWriter writer = new PrintWriter(System.out, true);
        writer.println(solve(n, m));
    }

    static long solve(long n, long m) {
        long answer;
        if (m < 3) {
            return 0;
        }
        if (n == 1) {
            answer = m % 6;
            if (answer > 3) {
                answer = 6 - answer;
            }
            return m - answer;
        }
        if (n == 2) {
            answer = m * n;
            if (m == 3) {
                answer = 4;
            } else if (m == 7) {
                answer = 12;
            }
            return answer;
        }
        if (n == 3) {
            answer = m * n;
            if (m % 2 == 1) {
                answer--;
            }
            return answer;
        }
        answer = m * n;
        if (m % 2 == 1 && n % 2 == 1) {
            answer--;
        }
        return answer;
    }
}

