public class CFA4 {

    public static void main(String[] args) throws IOException {
        new CFA4().run();
    }

    void run() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        if (n > m) { int t = n; n = m; m = t; }

        if (n == 1) {
            m--;
            int[] left = {0,0,0,2,4,6};
            out.println(m / 6 * 6L + left[m % 6]);
        } else if (n == 2) {
            out.println(m < 20 ? bruteForce(n, m) : (long)n * m);
        } else if (n == 3) {
            if (m < 20) out.println(bruteForce(n, m));
            else {
                long res = (long)n * m;
                if (res % 2 != 0) res--;
                out.println(res);
            }
        } else {
            long res = (long)n * m;
            if (res < 1000) out.println(bruteForce(n, m));
            else {
                if (res % 2 != 0) res--;
                out.println(res);
            }
        }
        out.close();
    }

    int bruteForce(int n, int m) {
        List<int[]> even = new ArrayList<>();
        List<int[]> odd = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if ((i + j) % 2 == 0) even.add(new int[]{i, j});
                else odd.add(new int[]{i, j});
            }
        }
        int es = even.size(), os = odd.size();
        boolean[][] graph = new boolean[es][os];
        for (int i = 0; i < es; i++) {
            for (int j = 0; j < os; j++) {
                if (calcDist(even.get(i), odd.get(j)) == 3) graph[i][j] = true;
            }
        }
        return 2 * maxMatching(graph);
    }

    int calcDist(int[] a, int[] b) {
        return Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]);
    }

    int maxMatching(boolean[][] g) {
        int n1 = g.length, n2 = n1 == 0 ? 0 : g[0].length;
        int[] matchR = new int[n2];
        Arrays.fill(matchR, -1);
        int result = 0;
        for (int u = 0; u < n1; u++) {
            if (dfs(g, u, new boolean[n1], matchR)) result++;
        }
        return result;
    }

    boolean dfs(boolean[][] g, int u, boolean[] vis, int[] matchR) {
        for (int v = 0; v < matchR.length; v++) {
            if (g[u][v] && !vis[v]) {
                vis[v] = true;
                if (matchR[v] == -1 || dfs(g, matchR[v], vis, matchR)) {
                    matchR[v] = u;
                    return true;
                }
            }
        }
        return false;
    }
}

