import java.io.IOException;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();
        System.out.println(compute(n, m));
    }

    private static long compute(long n, long m) {
        if (n >= 4 && m >= 4) {
            if (n % 2 == 0 || m % 2 == 0) {
                return n * m;
            }
            return n * m - 1;
        }

        long min = Math.min(n, m);
        long max = Math.max(n, m);

        if (min == 1) {
            long rem = max % 6;
            long result = max - rem;
            if (rem == 4) result += 2;
            if (rem == 5) result += 4;
            return result;
        }

        if (min == 2) {
            if (max < 3) return 0;
            if (max == 3) return 4;
            if (max == 7) return 12;
            return 2L * max;
        }

        if (min == 3) {
            if (max < 3) return 0;
            long result = 3L * max;
            if (max % 2 == 1) --result;
            return result;
        }

        return 0;
    }
}

import java.util.*;

public class Main {
    private static final long[] SUB = {0L, 1L, 2L, 3L, 2L, 1L};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();
        long answer = 0L;

        if (n >= 4 && m >= 4) {
            answer = n * m;
            if ((n & 1L) != 0 && (m & 1L) != 0) {
                --answer;
            }
        } else {
            long min = Math.min(n, m);
            long max = Math.max(n, m);

            int kind = (min == 1 || min == 2 || min == 3) ? (int) min : 0;
            switch (kind) {
                case 1:
                    answer = max - SUB[(int) (max % 6)];
                    break;
                case 2:
                    if (max < 3) {
                        answer = 0L;
                    } else if (max == 3) {
                        answer = 4L;
                    } else if (max == 7) {
                        answer = 12L;
                    } else {
                        answer = 2L * max;
                    }
                    break;
                case 3:
                    if (max >= 3) {
                        answer = 3L * max;
                        if ((max & 1L) == 1L) {
                            --answer;
                        }
                    }
                    break;
                default:
                    answer = 0L;
                    break;
            }
        }

        System.out.println(answer);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();

        long min = Math.min(n, m);
        long max = Math.max(n, m);

        long rep = (n >= 4 && m >= 4)
                ? n * m - (((n & 1L) == 1L && (m & 1L) == 1L) ? 1L : 0L)
                : small(min, max);

        System.out.println(rep);
    }

    private static long small(long min, long max) {
        if (min == 1) {
            long[] correction = {0L, 1L, 2L, 3L, 2L, 1L};
            return max - correction[(int) (max % 6)];
        }

        if (min == 2) {
            return max < 3 ? 0L
                 : max == 3 ? 4L
                 : max == 7 ? 12L
                 : 2L * max;
        }

        if (min == 3) {
            return max < 3 ? 0L
                 : 3L * max - (((max & 1L) == 1L) ? 1L : 0L);
        }

        return 0L;
    }
}

