import java.io.*;
import java.util.*;
import static java.lang.Math.*;

public class D {
    public static void main(String[] args)throws Exception {
        FastReader in = new FastReader(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        long n = in.nextLong(), m = in.nextLong();

        pw.println(solve(n, m));

        pw.close();
    }

    static long solve(long n, long m){
        if(n > m){
            long tmp = n; n = m; m = tmp;
        }
        long res = n*m;
        if(n % 2 == 1 && m % 2 == 1) res--;

        if(n == 1){
            long x = ((n*m)/6)*6;
            long y = (n*m) % 6;
            if(y == 4) x += 2;
            if(y == 5) x += 4;
            return x;
        }
        if(n == 2 && m == 2) return 0;
        if(n == 2 && m == 3) return 4;
        if(n == 2 && m == 7) return 12;

        return res;
    }

    static void debug(Object...obj) {
        System.err.println(Arrays.deepToString(obj));
    }

    static class FastReader {
        InputStream is;
        private byte[] inbuf = new byte[1024];
        private int lenbuf = 0, ptrbuf = 0;

        public FastReader(InputStream is) {
            this.is = is;
        }

        public int readByte() {
            if (lenbuf == -1) throw new InputMismatchException();
            if (ptrbuf >= lenbuf) {
                ptrbuf = 0;
                try {
                    lenbuf = is.read(inbuf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (lenbuf <= 0) return -1;
            }
            return inbuf[ptrbuf++];
        }

        public boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }
        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public int skip() {
            int b;
            while ((b = readByte()) != -1 && isSpaceChar(b)) ;
            return b;
        }

        public String next() {
            int b = skip();
            StringBuilder sb = new StringBuilder();
            while (!(isSpaceChar(b))) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }



        public String nextLine() {
            int c = skip();
            StringBuilder sb = new StringBuilder();
            while (!isEndOfLine(c)){
                sb.appendCodePoint(c);
                c = readByte();
            }
            return sb.toString();
        }

        public int nextInt() {
            int num = 0, b;
            boolean minus = false;
            while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-')) ;
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            while (true) {
                if (b >= '0' && b <= '9') {
                    num = (num << 3) + (num << 1) + (b - '0');
                } else {
                    return minus ? -num : num;
                }
                b = readByte();
            }
        }

        public long nextLong() {
            long num = 0;
            int b;
            boolean minus = false;
            while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-')) ;
            if (b == '-') {
                minus = true;
                b = readByte();
            }

            while (true) {
                if (b >= '0' && b <= '9') {
                    num = (num << 3) + (num << 1) + (b - '0');
                } else {
                    return minus ? -num : num;
                }
                b = readByte();
            }
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public char[] next(int n) {
            char[] buf = new char[n];
            int b = skip(), p = 0;
            while (p < n && !(isSpaceChar(b))) {
                buf[p++] = (char) b;
                b = readByte();
            }
            return n == p ? buf : Arrays.copyOf(buf, p);
        }

        public char readChar() {
            return (char) skip();
        }
    }
}

import java.io.*;

public class D1 {
    public static void main(String[] args) throws Exception {
        SimpleReader in = new SimpleReader(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        long n = in.nextLong();
        long m = in.nextLong();
        pw.println(solve(n, m));
        pw.close();
    }

    static long solve(long n, long m) {
        if (n > m) {
            long t = n; n = m; m = t;
        }
        if (n == 1) {
            long base = (m / 6) * 6;
            long rem = m % 6;
            if (rem == 4) base += 2;
            if (rem == 5) base += 4;
            return base;
        }
        if (n == 2) {
            if (m == 2) return 0;
            if (m == 3) return 4;
            if (m == 7) return 12;
        }
        long res = n * m;
        if (n % 2 == 1 && m % 2 == 1) res--;
        return res;
    }

    static class SimpleReader {
        private final Reader reader;

        SimpleReader(InputStream in) {
            reader = new InputStreamReader(in);
        }

        long nextLong() throws IOException {
            int b;
            do {
                b = reader.read();
            } while (b != -1 && !(b >= '0' && b <= '9' || b == '-'));
            if (b == -1) return 0L;
            boolean minus = false;
            if (b == '-') {
                minus = true;
                b = reader.read();
            }
            long num = 0;
            while (b != -1 && b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
                b = reader.read();
            }
            return minus ? -num : num;
        }
    }
}

import java.util.*;

public class D2 {
    private static final Map<Long, Long> EDGE = new HashMap<>();

    static {
        EDGE.put(2L, 0L);
        EDGE.put(3L, 4L);
        EDGE.put(7L, 12L);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = 0, m = 0;
        int cnt = 0;
        while (sc.hasNext() && cnt < 2) {
            String token = sc.next();
            try {
                long val = Long.parseLong(token);
                if (cnt == 0) n = val;
                else m = val;
                cnt++;
            } catch (NumberFormatException ignored) {
            }
        }
        System.out.println(solve(n, m));
        sc.close();
    }

    static long solve(long n, long m) {
        if (n > m) {
            n = n ^ m ^ (m = n);
        }
        if (n == 1) return one(m);
        if (n == 2) {
            Long special = EDGE.get(m);
            if (special != null) return special;
        }
        return n * m - (n % 2 == 1 && m % 2 == 1 ? 1 : 0);
    }

    static long one(long m) {
        long ans = m / 6 * 6;
        if (m % 6 == 4) ans += 2;
        if (m % 6 == 5) ans += 4;
        return ans;
    }
}

