        long a = Math.min(n, m), b = Math.max(n, m);
        return a == 1 ? (b / 6 * 6 + (b % 6 == 4 ? 2 : 0) + (b % 6 == 5 ? 4 : 0))
                : a == 2 && b == 2 ? 0
                : a == 2 && b == 3 ? 4
                : a == 2 && b == 7 ? 12
                : (a * b - (a % 2 == 1 && b % 2 == 1 ? 1 : 0));
    }
}

