    static long solve(long n, long m) {
        long a = Math.min(n, m), b = Math.max(n, m);
        if (a == 1) {
            long base = b / 6 * 6;
            long r = b % 6;
            if (r == 4) base += 2;
            if (r == 5) base += 4;
            return base;
        }
        return Stream.of(
                new long[]{2, 2, 0},
                new long[]{2, 3, 4},
                new long[]{2, 7, 12}
        ).filter(spec -> spec[0] == a && spec[1] == b)
                .findFirst()
                .map(spec -> spec[2])
                .orElseGet(() -> {
                    long res = a * b;
                    if (a % 2 == 1 && b % 2 == 1) res--;
                    return res;
                });
    }
