    static class Solver {
        int n, m;

        void solve(InputReader in, OutputWriter out) {
            n = in.nextInt();
            m = in.nextInt();
            long answer = 0L;

            if (n > 100) {
                int remainder = (n - 100) % 6;
                long fullBlocks = (n - 100) / 6;
                answer += fullBlocks * 6L * m;
                n = 100 + remainder;
            }

            if (m > 100) {
                int remainder = (m - 100) % 6;
                long fullBlocks = (m - 100) / 6;
                answer += fullBlocks * 6L * n;
                m = 100 + remainder;
            }

            int[][] id = new int[n + 1][m + 1];
            int evenId = 1;
            int oddId = 1;

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (((i + j) & 1) == 0) {
                        id[i][j] = evenId++;
                    }
                }
            }

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (((i + j) & 1) != 0) {
                        id[i][j] = oddId++;
                    }
                }
            }

            int L = evenId - 1;
            int R = oddId - 1;

            List<Integer>[] graph = new List[L + 1];
            for (int i = 0; i <= L; i++) {
                graph[i] = new ArrayList<>();
            }

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (((i + j) & 1) == 0) {
                        addEdge(graph, id, i, j, i - 3, j);
                        addEdge(graph, id, i, j, i - 2, j - 1);
                        addEdge(graph, id, i, j, i - 2, j + 1);
                        addEdge(graph, id, i, j, i, j - 3);
                        addEdge(graph, id, i, j, i - 1, j - 2);
                        addEdge(graph, id, i, j, i + 1, j - 2);
                        addEdge(graph, id, i, j, i, j + 3);
                        addEdge(graph, id, i, j, i - 1, j + 2);
                        addEdge(graph, id, i, j, i + 1, j + 2);
                        addEdge(graph, id, i, j, i + 3, j);
                        addEdge(graph, id, i, j, i + 2, j - 1);
                        addEdge(graph, id, i, j, i + 2, j + 1);
                    }
                }
            }

            HopcroftKarp hk = new HopcroftKarp(L, R, graph);
            answer += 2L * hk.maxMatching();
            out.println(answer);
        }

        void addEdge(List<Integer>[] graph, int[][] id, int i, int j, int s, int t) {
            if (s <= 0 || t <= 0 || s > n || t > m) {
                return;
            }
            graph[id[i][j]].add(id[s][t]);
        }
    }

    static class HopcroftKarp {
        static final int INF = 10000000;
        static final int NIL = 0;

        int m;
        int n;
        List<Integer>[] graph;
        int[] pairU;
        int[] pairV;
        int[] dist;

        HopcroftKarp(int m, int n, List<Integer>[] graph) {
            this.m = m;
            this.n = n;
            this.graph = graph;
            pairU = new int[m + 1];
            pairV = new int[n + 1];
            dist = new int[m + 1];
        }

        int maxMatching() {
            Arrays.fill(pairU, NIL);
            Arrays.fill(pairV, NIL);

            int result = 0;
            while (bfs()) {
                for (int i = 1; i <= m; i++) {
                    if (pairU[i] == NIL && dfs(i)) {
                        result++;
                    }
                }
            }
            return result;
        }

        boolean bfs() {
            ArrayDeque<Integer> queue = new ArrayDeque<>();

            for (int i = 1; i <= m; i++) {
                if (pairU[i] == NIL) {
                    queue.add(i);
                    dist[i] = 0;
                } else {
                    dist[i] = INF;
                }
            }

            dist[NIL] = INF;

            while (!queue.isEmpty()) {
                int u = queue.poll();
                if (dist[u] < dist[NIL]) {
                    for (int v : graph[u]) {
                        if (dist[pairV[v]] == INF) {
                            queue.add(pairV[v]);
                            dist[pairV[v]] = dist[u] + 2;
                        }
                    }
                }
            }

            return dist[NIL] < INF;
        }

        boolean dfs(int u) {
            if (u == NIL) {
                return true;
            }

            for (int v : graph[u]) {
                if (dist[pairV[v]] == dist[u] + 2) {
                    if (dfs(pairV[v])) {
                        pairV[v] = u;
                        pairU[u] = v;
                        return true;
                    }
                }
            }

            dist[u] = INF;
            return false;
        }
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
