    static class Solver {
        int n, m;

        void solve(InputReader in, OutputWriter out) {
            n = in.nextInt();
            m = in.nextInt();
            long ans = 0;

            if (n > 100) {
                int rem = (n - 100) % 6;
                long q = (n - 100) / 6;
                ans += q * 6L * m;
                n = 100 + rem;
            }

            if (m > 100) {
                int rem = (m - 100) % 6;
                long q = (m - 100) / 6;
                ans += q * 6L * n;
                m = 100 + rem;
            }

            int[][] id = new int[n + 1][m + 1];
            int even = 1, odd = 1;

            for (int i = 1; i <= n; i++) {
