        int maxMatching() {
            Arrays.fill(matchR, -1);
            int matching = 0;

            for (int u = 1; u <= m; u++) {
                for (int v : graph[u]) {
                    if (matchR[v] == -1) {
                        matchR[v] = u;
                        matching++;
                        break;
                    }
                }
            }

            for (int u = 1; u <= m; u++) {
                boolean alreadyMatched = false;
                for (int v : graph[u]) {
                    if (matchR[v] == u) {
                        alreadyMatched = true;
                        break;
                    }
                }
                if (!alreadyMatched) {
                    Arrays.fill(used, false);
                    if (dfs(u)) matching++;
                }
            }

            return matching;
        }

        boolean dfs(int u) {
            if (used[u]) return false;
            used[u] = true;

            for (int v : graph[u]) {
                if (matchR[v] == -1 || dfs(matchR[v])) {
                    matchR[v] = u;
                    return true;
                }
            }

            return false;
        }
    }

