public class ghh {
    static final long MOD = 1000000007L;
    static int n;
    static long[] occ;
    static long[] nbr;

    static void countVertexes() {
        occ[0]++;
        nbr[0] = 1;
        int half = n / 2;
        for (int step = 1; step <= n; step++) {
            long[] next = new long[half + 1];
            int lim = Math.min(n - step, half);
            for (int state = 0; state <= lim; state++) {
                long val = occ[state];
                if (state + 1 <= lim) {
                    next[state + 1] = (next[state + 1] + val) % MOD;
                }
                if (state - 1 >= 0) {
                    next[state - 1] = (next[state - 1] + val) % MOD;
                }
                next[state] %= MOD;
            }
            if (lim + 1 <= half) {
                next[lim] = (next[lim] + occ[lim + 1]) % MOD;
            }
            long sum = 0;
            for (int state = 0; state <= lim; state++) {
                sum += next[state];
                sum %= MOD;
                occ[state] = next[state];
            }
            nbr[step] = sum;
        }
    }

