        while (c != -1 && c <= ' ') {
            c = System.in.read();
        }
        if (c == -1) {
            throw new IOException("No input");
        }
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = System.in.read();
        } else if (c == '+') {
            c = System.in.read();
        }
        int value = 0;
        while (c != -1 && c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = System.in.read();
        }
        return value * sign;
    }

