import java.util.Scanner;

public class Codeforces {
    final static int P = 1000000007;

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int n = input.nextInt();
        int stride = n + 1;
        int[] table = new int[stride * stride];
        table[0] = 0;

        for (int i = 0; i <= n; i++) {
            for (int j = i; j <= n; j++) {
                int index = i * stride + j;
                if (i == 0 && j == 0) {
                    continue;
                }
                if (i == 0) {
                    table[index] = (table[index - 1] + ((i + j) & 1)) % P;
                } else {
                    table[index] = (table[index - stride] + table[index - 1] + ((i + j) & 1)) % P;
                }
            }
        }

        System.out.println(table[n * stride + n]);
    }
}

import java.io.*;
import java.util.Scanner;

public class Kek {
    static Scanner scan = new Scanner(System.in);

    static int nextInt() {
        return Integer.parseInt(scan.next());
    }

    static String nextString() {
        return scan.next();
    }

    public static void main(String[] args) throws IOException {
        long MOD = 1000000007L;
        int n = nextInt();
        long[][] d = new long[2 * n + 1][n + 2];
        d[0][0] = 1;
        for (int i = 1; i < 2 * n + 1; i++) {
            d[i][0] = (d[i - 1][1] % MOD);
            for (int j = 1; j < n + 1 && j + i <= 2 * n ; j++) {
                d[i][j] = (d[i - 1][j + 1] + d[i - 1][j - 1]) % MOD;
            }
        }
        long s = 0;
        for (int i = 2 * n - 1; i >= 0; i -= 2) {
            for (int j = 0; j < n + 1; j++) {
                s += d[i][j];
                s %= MOD;
            }
        }
        System.out.println(s);
    }
}

