    long gcd(long a,long b) {
        return a==0?b:b>a?gcd(b%a,a):gcd(b,a);
    }
    void work() {
        int n=in.nextInt();
        long[][] dp=new long[2][2*n+1];
        long ret=0;
        dp[0][0]=1;
        for(int p=1;p<=2*n;p++) {
            int cur=p%2;
            int prev=p%2==0?1:0;
            Arrays.fill(dp[cur],0);
            for(int i=0;i<2*n;i++) {
                dp[cur][i+1]=(dp[cur][i+1]+dp[prev][i])%mod;
                if(i-1>=0) {
                    dp[cur][i-1]=(dp[cur][i-1]+dp[prev][i])%mod;
                    if(p%2==0 && (2*n-p)>=i-1) {
                        ret=(ret+dp[prev][i])%mod;
                    }
                }
            }
        }
        out.println(ret);
    }
