                Map<Integer, int[]> next = new HashMap<Integer, int[]>();

                for (int opened = depth & 1; opened <= depth; opened += 2) {
                    next.put(opened, new int[]{0, 0});
                }

                for (Map.Entry<Integer, int[]> entry : current.entrySet()) {
                    int p = entry.getKey();
                    int a = entry.getValue()[0];
                    int b = entry.getValue()[1];

                    if (p + 1 <= 2 * n) {
                        int[] target = next.get(p + 1);
