        for (int i = 1; i <= m; ++i) {
            f[i][0] = f[i - 1][1];
            for (int j = 1; j <= m; ++j) {
                f[i][j] = (f[i - 1][j - 1] + f[i - 1][j + 1]) % MODULO;
            }
