        long total = N * M;
        if (total % 2 == 1) {
            ans = powMod(E + O, total, mod);
        } else {
            ans = (powMod(E + O, total, mod) + powMod(E - O, total, mod)) % mod;
            ans = ans * powMod(2, mod - 2, mod) % mod;
        }
        System.out.println(ans);
        sc.close();
    }

    static long powMod(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}

