        long O = len - E;
        long nm = N * M;
        long ans;

        long inv2 = expMod(2, MOD - 2, MOD);
        long sum = expMod(E + O, nm, MOD);
        long diff = (nm % 2 == 0) ? expMod(E - O, nm, MOD) : 0;
        ans = (sum + diff) % MOD;
        if (nm % 2 == 0) {
            ans = ans * inv2 % MOD;
        }
        System.out.println(ans);
    }

    static long expMod(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1)
                res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
}

