        }
    }

    private static long[] pair(long x, long y, long st) {
        if (st == 1) {
            return new long[]{x, y};
        }
        if ((st & 1) == 1) {
            long[] prev = pair(x, y, st - 1);
            long a = (x * prev[0] + y * prev[1]) % mod;
            long b = (x * prev[1] + y * prev[0]) % mod;
            return new long[]{a, b};
        }
        long[] half = pair(x, y, st / 2);
        long h0 = half[0];
        long h1 = half[1];
        long a = (h0 * h0 + h1 * h1) % mod;
        long b = (2 * h0 * h1) % mod;
        return new long[]{a, b};
    }

    private static long bin(long x, long st) {
        if (st == 0) return 1;
        if (st == 1) return x;
        long m = st / 2;
        long ans = bin(x, m);
        if ((st & 1) == 0) {
            return ans * ans % mod;
        } else {
            return ((ans * ans % mod) * x) % mod;
        }
    }
}

