public class E {
    static final long mod = 998244353L;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long n = in.nextInt();
        long m = in.nextInt();
        long p = in.nextInt();
        long q = in.nextInt();
        long total = q - p + 1;
        long x = total;
        if (p % 2 == 0) {
            x = x - x / 2;
        } else {
            x /= 2;
        }
        long y = total - x;

        if ((n & m) % 2 == 0) {
            System.out.println(matrixPair(x, y, n * m)[0]);
        } else {
            System.out.println(bin(x + y, n * m));
        }
    }

    private static long[] matrixPair(long x, long y, long st) {
        if (st == 0) {
            throw new StackOverflowError();
        }
        if (st == 1) {
            return new long[]{x, y};
        }
        long xm = x % mod;
        long ym = y % mod;
        long f2a = (xm * xm + ym * ym) % mod;
        long f2b = (2 * xm * ym) % mod;
        if (st == 2) {
            return new long[]{f2a, f2b};
        }

        long c = (2 * xm) % mod;
        long d = ((ym * ym - xm * xm) % mod + mod) % mod;
        long[][] trans = {{c, d}, {1, 0}};
        long[][] power = matPow(trans, st - 2);

        long a = (power[0][0] * f2a + power[0][1] * xm) % mod;
        long b = (power[0][0] * f2b + power[0][1] * ym) % mod;
        return new long[]{a, b};
    }

    private static long[][] matPow(long[][] base, long e) {
        long[][] res = {{1, 0}, {0, 1}};
        while (e > 0) {
            if ((e & 1) == 1) {
                res = matMul(res, base);
            }
            base = matMul(base, base);
            e >>= 1;
        }
        return res;
    }

    private static long[][] matMul(long[][] A, long[][] B) {
        long[][] C = new long[2][2];
        for (int i = 0; i < 2; i++) {
            for (int k = 0; k < 2; k++) {
                long aik = A[i][k];
                if (aik == 0) continue;
                for (int j = 0; j < 2; j++) {
                    C[i][j] = (C[i][j] + aik * B[k][j]) % mod;
                }
            }
        }
        return C;
    }

    private static long bin(long x, long st) {
        if (st == 0) return 1;
        if (st == 1) return x;
        long result = 1;
        long cur = x;
        long e = st;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = result * cur % mod;
            }
            cur = cur * cur % mod;
            e >>= 1;
        }
        return result;
    }
}

