			System.out.println(i);
	}
	static class Vector
	{
		int[] arr = new int[5];
		Vector(int[] a, int[] b)
		{
			for (int i = 0; i < 5; i++)
			{
				arr[i] = b[i]-a[i];
			}
		}
		double mag()
		{
			double sum = 0;
			for (int i = 0; i < arr.length; i++)
			{
				sum += arr[i]*arr[i];
			}
			return Math.sqrt(sum);
		}
		int prod(Vector v)
		{
			int sum = 0;
			for (int i = 0; i < arr.length; i++)
			{
				sum += arr[i]*v.arr[i];
			}
			return sum;
		}
	}
