/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author Yuan Lei
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            if (n > 40) {
                out.println(0);
                return;
            } else {
                final ArrayList<TaskC.Point> points = new ArrayList<>();
                for (int i = 0; i < n; ++i) {
                    int a, b, c, d, e;
                    a = in.nextInt();
                    b = in.nextInt();
                    c = in.nextInt();
                    d = in.nextInt();
                    e = in.nextInt();
                    points.add(new TaskC.Point(a, b, c, d, e));
                }
                if (n < 3) {
                    out.println(n);
                    for (int i = 1; i <= n; ++i) {
                        out.println(i);
                    }
                    return;
                }
                ArrayList<Integer> result = new ArrayList<>();
                for (int center = 0; center < n; ++center) {
                    boolean find = false;
                    for (int a = 0; a < n; ++a)
                        if (a != center) {
                            for (int b = 0; b < n; ++b)
                                if (b != center && b != a) {
                                    TaskC.Point A = points.get(a).minus(points.get(center));
                                    TaskC.Point B = points.get(b).minus(points.get(center));
                                    if (A.dot(B)) {
                                        find = true;
                                        break;
                                    }
                                }
                            if (find) break;
                        }
                    if (!find) result.add(center + 1);
                }
                out.println(result.size());
                for (int id : result) {
                    out.println(id);
                }
            }
        }

        static class Point {
            long a;
            long b;
            long c;
            long d;
            long e;

            public Point(long a, long b, long c, long d, long e) {
                this.a = a;
                this.b = b;
                this.c = c;
                this.d = d;
                this.e = e;
            }

            boolean dot(final TaskC.Point rhs) {
                return a * rhs.a + b * rhs.b + c * rhs.c + d * rhs.d + e * rhs.e > 0;
            }

            TaskC.Point minus(final TaskC.Point rhs) {
                return new TaskC.Point(a - rhs.a, b - rhs.b, c - rhs.c, d - rhs.d, e - rhs.e);
            }

        }

    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        InputStream in;
        byte[] buf = new byte[1024];
        int off, len;

        FastScanner(InputStream in) {
            this.in = in;
        }

        int read() throws IOException {
            if (off >= len) {
                len = in.read(buf);
                off = 0;
                if (len <= 0) return -1;
            }
            return buf[off++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return sign * val;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        int n = in.nextInt();
        if (n > 40) {
            out.println(0);
            out.close();
            return;
        }

        long[][] points = new long[n][5];
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < 5; ++j) {
                points[i][j] = in.nextInt();
            }
        }

        if (n < 3) {
            out.println(n);
            for (int i = 1; i <= n; ++i) out.println(i);
            out.close();
            return;
        }

        ArrayList<Integer> result = new ArrayList<>();
        for (int center = 0; center < n; ++center) {
            boolean bad = false;
            search:
            for (int a = 0; a < n; ++a) {
                if (a == center) continue;
                for (int b = 0; b < n; ++b) {
                    if (b == center || b == a) continue;
                    if (positiveScalar(points[a], points[center], points[b])) {
                        bad = true;
                        break search;
                    }
                }
            }
            if (!bad) result.add(center + 1);
        }

        out.println(result.size());
        for (int id : result) out.println(id);
        out.close();
    }

    static boolean positiveScalar(long[] x, long[] c, long[] y) {
        long sum = 0;
        for (int i = 0; i < 5; ++i) {
            sum += (x[i] - c[i]) * (y[i] - c[i]);
        }
        return sum > 0;
    }
}

