public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        if (n > 40) {
            out.println(0);
            out.close();
            return;
        }

        ArrayList<Point> points = new ArrayList<>();
        for (int i = 0; i < n; ++i) {
            points.add(new Point(in.nextInt(), in.nextInt(), in.nextInt(), in.nextInt(), in.nextInt()));
        }

        if (n < 3) {
            out.println(n);
            for (int i = 1; i <= n; ++i) out.println(i);
            out.close();
            return;
        }

        ArrayList<Integer> answer = new ArrayList<>();
        for (int center = 0; center < n; ++center) {
            Point c = points.get(center);
            boolean good = true;

            for (int a = 0; a < n && good; ++a) {
                if (a == center) continue;
                for (int b = a + 1; b < n; ++b) {
                    if (b == center) continue;
                    if (hasAcute(c, points.get(a), points.get(b))) {
                        good = false;
                        break;
                    }
                }
            }

            if (good) answer.add(center + 1);
        }

        out.println(answer.size());
        for (int id : answer) out.println(id);
        out.close();
    }

    static boolean hasAcute(Point c, Point x, Point y) {
        long dx1 = x.a - c.a;
        long dy1 = x.b - c.b;
        long dz1 = x.c - c.c;
        long du1 = x.d - c.d;
        long dv1 = x.e - c.e;

        long dx2 = y.a - c.a;
        long dy2 = y.b - c.b;
        long dz2 = y.c - c.c;
        long du2 = y.d - c.d;
        long dv2 = y.e - c.e;

        return dx1 * dx2 + dy1 * dy2 + dz1 * dz2 + du1 * du2 + dv1 * dv2 > 0;
    }

    static class Point {
        long a, b, c, d, e;

        Point(long a, long b, long c, long d, long e) {
            this.a = a;
            this.b = b;
            this.c = c;
            this.d = d;
            this.e = e;
        }
    }
}

