                points[i][j] = sc.nextLong();
            }
        }

        long[][][] vectors = new long[n][n][5];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int d = 0; d < 5; d++) {
                    vectors[i][j][d] = points[j][d] - points[i][d];
                }
            }
        }

        HashSet<Integer> bad = new HashSet<Integer>();

        outer:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = j + 1; k < n; k++) {
                    if (same(vectors[i][j], vectors[i][k])) {
                        continue;
                    }
                    if (dot(vectors[i][j], vectors[i][k]) > 0) {
                        bad.add(i + 1);
                        continue outer;
                    }
                }
            }
        }

        System.out.println(n - bad.size());
        for (int i = 1; i <= n; i++) {
            if (!bad.contains(i)) {
                System.out.println(i);
            }
        }
    }

    private static boolean same(long[] a, long[] b) {
        for (int d = 0; d < 5; d++) {
            if (a[d] != b[d]) {
                return false;
            }
        }
        return true;
    }

    private static long dot(long[] a, long[] b) {
        long sum = 0;
        for (int d = 0; d < 5; d++) {
            sum += a[d] * b[d];
        }
        return sum;
    }
}

