public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        if (n > 11) {
            System.out.println(0);
            return;
        }

        long[][] points = new long[n][5];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 5; j++) {
                points[i][j] = sc.nextLong();
            }
        }

        boolean[] bad = new boolean[n];

        for (int i = 0; i < n; i++) {
            final int origin = i;
            bad[origin] = IntStream.range(0, n).anyMatch(j -> {
                long[] vj = vector(points, origin, j);
                return IntStream.range(0, n).anyMatch(k -> {
                    long[] vk = vector(points, origin, k);
                    return !same(vj, vk) && dot(vj, vk) > 0;
                });
            });
        }

        int good = 0;
        for (boolean b : bad) {
            if (!b) good++;
        }

        System.out.println(good);
        for (int i = 0; i < n; i++) {
            if (!bad[i]) {
                System.out.println(i + 1);
            }
        }
    }

    private static long[] vector(long[][] points, int from, int to) {
        return new long[]{
            points[to][0] - points[from][0],
            points[to][1] - points[from][1],
            points[to][2] - points[from][2],
            points[to][3] - points[from][3],
            points[to][4] - points[from][4]
        };
    }

    private static boolean same(long[] a, long[] b) {
        for (int i = 0; i < 5; i++) {
            if (a[i] != b[i]) return false;
        }
        return true;
    }

    private static long dot(long[] a, long[] b) {
        long result = 0;
        for (int i = 0; i < 5; i++) {
            result += a[i] * b[i];
        }
        return result;
    }
}

