public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        if (n > 11) {
            System.out.println(0);
            return;
        }

        long[] data = new long[n * 5];
        for (int i = 0; i < n; i++) {
            for (int d = 0; d < 5; d++) {
                data[i * 5 + d] = sc.nextLong();
            }
        }

        long[][][] vectors = new long[n][n][5];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int d = 0; d < 5; d++) {
                    vectors[i][j][d] = data[j * 5 + d] - data[i * 5 + d];
                }
            }
        }

        BitSet bad = new BitSet(n);

        for (int i = 0; i < n; i++) {
            if (bad.get(i)) continue;
            loop:
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    if (!equal(vectors[i][j], vectors[i][k]) && dot(vectors[i][j], vectors[i][k]) > 0) {
                        bad.set(i);
