            System.out.println("0 0");
            return;
        }

        String data = s.substring(0, n);
        StringTokenizer st = new StringTokenizer(data, "()_", true);

        int cur = 0;
        int pending = 0;
        int maxOutside = 0;
        int insideWords = 0;

        while (st.hasMoreTokens()) {
            String token = st.nextToken();
            if (token.length() == 1
                    && (token.charAt(0) == '(' || token.charAt(0) == ')' || token.charAt(0) == '_')) {
                char ch = token.charAt(0);
                if (pending > 0) {
                    if (cur == 1) {
                        insideWords++;
                    } else {
                        maxOutside = Math.max(maxOutside, pending);
                    }
                    pending = 0;
                }
                if (ch == '(') {
                    cur = 1;
                } else if (ch == ')') {
                    cur = 0;
                }
            } else {
                pending = token.length();
            }
        }

        maxOutside = Math.max(maxOutside, pending);
        System.out.println(maxOutside + " " + insideWords);
    }
