class FastScanner {
    private InputStream in = System.in;
    private byte[] buf = new byte[1 << 16];
    private int cur = 0, len = 0;

    private int read() throws IOException {
        if (cur >= len) {
            len = in.read(buf);
            cur = 0;
            if (len <= 0) return -1;
        }
        return buf[cur++] & 0xff;
    }

    public int nextInt() throws IOException {
        int c = read();
        while (c <= ' ') c = read();
        int sgn = 1;
        if (c == '-') { sgn = -1; c = read(); }
        int res = 0;
        while (c > ' ') {
            if (c < '0' || c > '9') throw new InputMismatchException();
            res = res * 10 + (c - '0');
            c = read();
        }
        return res * sgn;
    }

    public String next() throws IOException {
        StringBuilder sb = new StringBuilder();
        int c = read();
        while (c <= ' ') c = read();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }
}

