                    break;
                case ')':
                    inside = false;
                    if (len > 0) {
                        words++;
                    }
                    len = 0;
                    break;
                default:
                    len++;
            }
            i++;
        }

        if (len > best) best = len;
        System.out.println(best + " " + words);
    }
}

