                                maxOutside = outsideLen;
                            }
                            outsideLen = 0;
                        }
                        break;
                    default:
                        if (inside) {
                            insideLen++;
                        } else {
                            outsideLen++;
                        }
                        break;
                }
            }

            if (outsideLen > maxOutside) {
                maxOutside = outsideLen;
            }

            System.out.print(maxOutside + " ");
            System.out.print(verbCount);
        } catch (Exception e) {
            System.out.println(0 + " 0" + 0);
        }
    }
