import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.StringTokenizer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class TextDoc {

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        scan.nextLine();
        String s = scan.nextLine();

        List<String> parts = splitAsJava(s, Pattern.compile("\\(.*?\\)"));
        int max = 0;
        for (String part : parts) {
            StringTokenizer st = new StringTokenizer(part, "_");
            while (st.hasMoreTokens()) {
                String token = st.nextToken();
                if (token.length() > max) {
                    max = token.length();
                }
            }
        }

        List<String> inside = new ArrayList<String>();
        int last = -1;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                last = i;
            }
            if (c == ')' && last != -1) {
                inside.add(s.substring(last + 1, i));
            }
        }

        int count = 0;
        for (String content : inside) {
            String[] words = content.split("_");
            for (String word : words) {
                if (word.length() > 0) {
                    count++;
                }
            }
        }

        System.out.println(max + " " + count);
    }

    static List<String> splitAsJava(String input, Pattern pattern) {
        List<String> result = new ArrayList<String>();
        Matcher matcher = pattern.matcher(input);
        int start = 0;
        while (matcher.find()) {
            result.add(input.substring(start, matcher.start()));
            start = matcher.end();
        }
        if (result.isEmpty()) {
            result.add(input);
            return result;
        }
        result.add(input.substring(start));
        while (result.size() > 0 && result.get(result.size() - 1).length() == 0) {
            result.remove(result.size() - 1);
        }
        return result;
    }
}

