                char c = s.charAt(i);
                if (c == '(') {
                    inside[0] = true;
                    wordStart[0] = true;
                    curOut[0] = 0;
                } else if (c == ')') {
                    inside[0] = false;
                    curOut[0] = 0;
                } else if (!inside[0]) {
                    if (c == '_') {
                        curOut[0] = 0;
                    } else {
                        curOut[0]++;
                        if (curOut[0] > maxOut[0]) {
                            maxOut[0] = curOut[0];
                        }
                    }
                } else {
                    if (c == '_') {
                        wordStart[0] = true;
                    } else if (wordStart[0]) {
                        insideWords[0]++;
                        wordStart[0] = false;
                    }
                }
            });
            out.println(maxOut[0] + " " + insideWords[0]);
        }
        out.flush();
    }

    static class Reader {
        BufferedReader br;
        StringTokenizer st;
        Reader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }
        boolean hasNext() {
            try {
                return br.ready();
            } catch (IOException e) {
                return false;
            }
        }
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String line;
                try {
                    line = br.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

