        while (i < input.length()) {
            if (input.charAt(i) == '(') {
                int j = i + 1;
                while (j < input.length() && isValidWordChar(input.charAt(j))) {
                    j++;
                }
                if (j < input.length() && input.charAt(j) == ')') {
