    public String ak375(int n, String str) {
        Stack<Integer> stack = new Stack<>();
        int res1 = 0;
        int res2 = 0;
        int currentLen = 0;

        for (int i = 0; i < n; i++) {
            char c = str.charAt(i);
            if (c == '(') {
                stack.push(currentLen);
                currentLen = 0;
                res2++;
