    }

    private void solve(char[] a, PrintWriter out) {
        int i = 0;
        int one = 0;
        int two = 0;
        int j = 0;
        boolean inside = false;
        Stage stage = Stage.CHECK;

        loop:
        while (true) {
            switch (stage) {
                case CHECK: {
                    if (i == a.length) {
                        break loop;
                    }
                    char c = a[i];
                    if (c == '(') {
                        inside = true;
                    } else if (c == ')') {
                        inside = false;
                    } else if (Character.isLetter(c)) {
                        i--;
                    }
                    stage = inside ? Stage.INSIDE_SKIP : Stage.OUTSIDE_SKIP;
                    break;
                }
                case INSIDE_SKIP: {
                    while (++i != a.length && a[i] != ')' && !Character.isLetter(a[i])) {
                    }
                    if (i == a.length || !Character.isLetter(a[i])) {
                        stage = Stage.CHECK;
                    } else {
                        stage = Stage.INSIDE_WORD;
                    }
                    break;
                }
                case INSIDE_WORD: {
                    while (Character.isLetter(a[++i])) {
                    }
                    two++;
                    stage = Stage.CHECK;
                    break;
