    static String collectInside(String s) {
        StringBuilder sb = new StringBuilder();
        boolean inside = false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                inside = true;
            } else if (c == ')') {
                sb.append(' ');
                inside = false;
            } else if (inside) {
                sb.append(c);
            }
        }
        return sb.toString();
    }

    static String stripOutside(String s) {
        int i = 0;
        boolean restarted;
        do {
            restarted = false;
            for (; i < s.length(); i++) {
                if (s.charAt(i) == ')') {
                    s = s.substring(0, s.indexOf('(')) + " " + s.substring(i + 1);
                    i = 1;
                    restarted = i < s.length();
                    break;
                }
            }
        } while (restarted);
        return s;
    }
}

