import java.util.Scanner;

public class lilu {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        String str = in.next();
        char[] arr = str.toCharArray();

        int maxSize = 0;
        int wordCount = 0;
        int currentSize = 0;
        boolean inside = false;
        int wordFlag = 0;

        int i = 0;
        while (i < n) {
            char c = arr[i];

            if (c == '(') {
                inside = true;
                if (currentSize != 0) {
                    maxSize = Math.max(maxSize, currentSize);
                    currentSize = 0;
                }
                wordFlag = 0;
            } else if (c == ')') {
                inside = false;
                if (currentSize != 0) {
                    maxSize = Math.max(maxSize, currentSize);
                    currentSize = 0;
                }
            }

            if (inside) {
                if (wordFlag != 1) {
                    if (c != '_' && c != '(' && c != ')') {
                        wordCount++;
                        wordFlag = 1;
                    }
                }
                if (c == '_' || c == '(' || c == ')') {
                    wordFlag = 0;
                }
            } else {
                if (c != '_' && c != ')' && c != '(') {
                    currentSize++;
                    if (i == n - 1) {
                        maxSize = Math.max(maxSize, currentSize);
                    }
                } else {
                    if (currentSize != 0) {
                        maxSize = Math.max(maxSize, currentSize);
                        currentSize = 0;
                    }
                }
            }

            i++;
        }

        System.out.println(maxSize + " " + wordCount);
    }
}

import java.util.Scanner;

public class lilu {
    private static boolean isSeparator(char c) {
        return c == '_' || c == '(' || c == ')';
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        String str = in.next();
        char[] arr = str.toCharArray();

        int maxSize = 0;
        int currentSize = 0;
        int wordCount = 0;
        int wordFlag = 0;
        boolean inside = false;

        for (int i = 0; i < n; i++) {
            char c = arr[i];

            if (c == '(') {
                inside = true;
                if (currentSize != 0) {
                    maxSize = Math.max(maxSize, currentSize);
                    currentSize = 0;
                }
                wordFlag = 0;
            } else if (c == ')') {
                inside = false;
                if (currentSize != 0) {
                    maxSize = Math.max(maxSize, currentSize);
                    currentSize = 0;
                }
            }

            if (inside) {
                if (wordFlag != 1 && !isSeparator(c)) {
                    wordCount++;
                    wordFlag = 1;
                }
                if (isSeparator(c)) {
                    wordFlag = 0;
                }
            } else {
                if (!isSeparator(c)) {
                    currentSize++;
                    if (i == n - 1) {
                        maxSize = Math.max(maxSize, currentSize);
                    }
                } else {
                    if (currentSize != 0) {
                        maxSize = Math.max(maxSize, currentSize);
                        currentSize = 0;
                    }
                }
            }
        }

        System.out.println(maxSize + " " + wordCount);
    }
}

import java.util.Scanner;

public class lilu {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        String str = in.next();
        char[] arr = str.toCharArray();

        int maxSize = computeMaxSize(arr, n);
        int wordCount = computeWordCount(arr, n);

        System.out.println(maxSize + " " + wordCount);
    }

    private static int computeMaxSize(char[] arr, int n) {
        int maxSize = 0;
        int currentSize = 0;
        boolean inside = false;

        for (int i = 0; i < n; i++) {
            char c = arr[i];

            if (c == '(') {
                inside = true;
                if (currentSize != 0) {
                    maxSize = Math.max(maxSize, currentSize);
                    currentSize = 0;
                }
            } else if (c == ')') {
                inside = false;
                if (currentSize != 0) {
                    maxSize = Math.max(maxSize, currentSize);
                    currentSize = 0;
                }
            } else if (!inside) {
                if (c != '_') {
                    currentSize++;
                    if (i == n - 1) {
                        maxSize = Math.max(maxSize, currentSize);
                    }
                } else {
                    if (currentSize != 0) {
                        maxSize = Math.max(maxSize, currentSize);
                        currentSize = 0;
                    }
                }
            }
        }

        return maxSize;
    }

    private static int computeWordCount(char[] arr, int n) {
        int wordCount = 0;
        boolean inside = false;
        int wordFlag = 0;

        for (int i = 0; i < n; i++) {
            char c = arr[i];

            if (c == '(') {
                inside = true;
                wordFlag = 0;
            } else if (c == ')') {
                inside = false;
            }

            if (inside) {
                if (wordFlag != 1) {
                    if (c != '_' && c != '(' && c != ')') {
                        wordCount++;
                        wordFlag = 1;
                    }
                }
                if (c == '_' || c == '(' || c == ')') {
                    wordFlag = 0;
                }
            }
        }

        return wordCount;
    }
}

import java.util.Scanner;

public class lilu {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        String str = in.next();
        char[] arr = str.toCharArray();

        int maxSize = 0;
        int currentSize = 0;
        int wordCount = 0;
        int state = 0; // 0 = outside parentheses, 1 = inside parentheses
        boolean wordStarted = false;

        for (int i = 0; i < n; i++) {
            char c = arr[i];

            if (c == '(') {
                if (currentSize != 0) {
                    maxSize = Math.max(maxSize, currentSize);
                    currentSize = 0;
                }
                state = 1;
                wordStarted = false;
            } else if (c == ')') {
                if (currentSize != 0) {
                    maxSize = Math.max(maxSize, currentSize);
                    currentSize = 0;
                }
                state = 0;
            } else if (state == 1) {
                if (!wordStarted && c != '_') {
                    wordCount++;
                    wordStarted = true;
                }
                if (c == '_') {
                    wordStarted = false;
                }
            } else {
                if (c != '_') {
                    currentSize++;
                    if (i == n - 1) {
                        maxSize = Math.max(maxSize, currentSize);
                    }
                } else {
                    if (currentSize != 0) {
                        maxSize = Math.max(maxSize, currentSize);
                        currentSize = 0;
                    }
                }
            }
        }

        System.out.println(maxSize + " " + wordCount);
    }
}

