public class B {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        int count = in.nextInt();
        in.nextLine();
        String s = in.nextLine();

        int maxOutside = 0;
        int insideWords = 0;
        int currentOutside = 0;
        int flags = 0; // bit 0: inside parentheses, bit 1: current inside word exists

        int i = 0;
        while (i < count) {
            char c = s.charAt(i++);

            if (c == 40) { // '('
                if (currentOutside > maxOutside) maxOutside = currentOutside;
                currentOutside = 0;
                flags |= 1;
            } else if (c == 41) { // ')'
                flags &= ~1;
                if ((flags & 2) != 0) insideWords++;
                flags &= ~2;
            } else if (c == 95) { // '_'
                if (currentOutside > maxOutside) maxOutside = currentOutside;
                currentOutside = 0;
                if ((flags & 2) != 0) insideWords++;
                flags &= ~2;
            } else {
                if ((flags & 1) != 0) flags |= 2;
                else currentOutside++;
            }
        }

        if (currentOutside > maxOutside) maxOutside = currentOutside;
        System.out.println(maxOutside + " " + insideWords);
    }
}

