		int one = 0;
		int start = 0;
		while (m.find()) {
			one = update(one, temp.substring(start, m.start()));
			start = m.end();
		}
		one = update(one, temp.substring(start));

		int two = 0;
		int i = 0;
		while (i < temp.length()) {
