					i++;
			} else {
				i++;
			}
		}
		System.out.println(one + " " + two);
	}

	private static int update(int best, String segment) {
		for (String w : segment.split("_+")) {
			if (w.length() > best)
				best = w.length();
		}
		return best;
	}

	private static boolean isLetter(char c) {
		return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
	}
}

