                if (c == '_') {
                    if (cur > max) max = cur;
                    cur = 0;
                } else if (c != '(' && c != ')') {
                    cur++;
                } else {
                    if (cur > max) max = cur;
                    cur = 0;
                    i++;
                    while (s.charAt(i) != ')') {
                        i++;
                    }
                }
            }
            if (cur > max) max = cur;
            return max;
        }

        int countWordsInParentheses() {
