import java.util.function.BiFunction;
import java.util.function.IntUnaryOperator;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String inp = sc.next();

        IntUnaryOperator findClose = start -> {
            int j = start;
            while (inp.charAt(j) != ')') {
                j++;
            }
            return j;
        };

        BiFunction<Integer, Integer, Integer> countWords = (start, end) -> {
            int words = 0;
            int cur = 0;
            for (int j = start; j < end; j++) {
                if (inp.charAt(j) == '_') {
                    if (cur > 0) {
                        words++;
                    }
                    cur = 0;
                } else {
                    cur++;
                }
            }
            if (cur > 0) {
                words++;
            }
            return words;
        };

        int maxl = -1;
        int cur = 0;
        for (int i = 0; i < n; i++) {
            char c = inp.charAt(i);
            if (c == '_') {
                if (cur > maxl) maxl = cur;
                cur = 0;
            } else if (c != '(' && c != ')') {
                cur++;
            } else {
                if (cur > maxl) maxl = cur;
                cur = 0;
                i = findClose.applyAsInt(i + 1);
            }
        }

        if (cur > maxl) maxl = cur;

        int numwrd = 0;
        for (int i = 0; i < n; i++) {
            while (i < n && inp.charAt(i) != '(') {
                i++;
            }
            if (i == n) {
                break;
            }
            int close = findClose.applyAsInt(i + 1);
            numwrd += countWords.apply(i + 1, close);
            i = close;
        }

        System.out.println(maxl + " " + numwrd);
    }
}

