public class p723b {
    static int nextDelimiter(String s, int from) {
        for (int i = from; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '_' || c == '(' || c == ')') {
                return i;
            }
        }
        return s.length();
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        String s = in.next();
        int prev = -1;
        int maxOutside = 0;
        int insideWords = 0;
        boolean inside = false;
        int i = nextDelimiter(s, 0);
        while (i < s.length()) {
            char c = s.charAt(i);
            int segmentLength = i - prev - 1;
            if (c == '_') {
                if (!inside) {
                    maxOutside = Math.max(maxOutside, segmentLength);
                } else if (segmentLength > 0) {
                    insideWords++;
                }
            } else if (c == '(') {
                inside = true;
                maxOutside = Math.max(maxOutside, segmentLength);
            } else if (c == ')') {
                inside = false;
                if (segmentLength > 0) {
                    insideWords++;
                }
            }
            prev = i;
            i = nextDelimiter(s, i + 1);
        }
        maxOutside = Math.max(maxOutside, s.length() - prev - 1);
        System.out.println(maxOutside + " " + insideWords);
    }
}

