    static class TaskB {
        public void solve(int testNumber, FastReader in, PrintWriter out) {
            int n = in.nextInt();
            String s = (in.nextLine() + "_").substring(0, n + 1);
            boolean inPar = false;
            int wordsInside = 0;
            int maxOutside = 0;
            int pos = 0;

            while (pos < s.length()) {
                int delim = nextDelimiter(s, pos);
                if (delim == s.length()) {
                    break;
                }

                int len = delim - pos;
                if (len > 0) {
                    if (inPar) {
                        wordsInside++;
                    } else if (len > maxOutside) {
                        maxOutside = len;
                    }
                }

                char c = s.charAt(delim);
                if (c == '(') {
                    inPar = true;
                } else if (c == ')') {
                    inPar = false;
                }
                pos = delim + 1;
            }

            out.printf("%d %d", maxOutside, wordsInside);
        }

        private static int nextDelimiter(String s, int from) {
            int best = s.length();
            int idx = s.indexOf('_', from);
            if (idx >= 0) best = Math.min(best, idx);
            idx = s.indexOf('(', from);
            if (idx >= 0) best = Math.min(best, idx);
            idx = s.indexOf(')', from);
            if (idx >= 0) best = Math.min(best, idx);
            return best;
        }
    }

