public class GregAndFriends {
    static final long MOD = 1000000007L;
    static int n, k, cnt50 = 0, cnt100 = 0;
    static long[][] comb = new long[100][100];

    static class Item implements Comparable<Item> {
        int mask;
        int d;
        Item(int m, int d) {
            mask = m;
            d = d;
        }
        public int compareTo(Item o) {
            return Integer.compare(this.d, o.d);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        for (int i = 0; i < n; i++) {
            if (sc.nextInt() == 50) cnt50++;
            else cnt100++;
        }
        sc.close();

        precomputeCombinations();

        int start = 1000000 + 100 * cnt50 + cnt100;
        Map<Integer, Integer> dist = new HashMap<Integer, Integer>();
        Map<Integer, Long> ways = new HashMap<Integer, Long>();
        PriorityQueue<Item> pq = new PriorityQueue<Item>();

        dist.put(start, 0);
        ways.put(start, 1L);
        pq.add(new Item(start, 0));

        while (!pq.isEmpty()) {
            Item cur = pq.poll();
            if (cur.d != dist.get(cur.mask)) continue;
            expand(cur.mask, dist, ways, pq);
        }

        if (dist.containsKey(0)) {
            System.out.println(dist.get(0) + "\n" + ways.get(0));
        } else {
            System.out.println("-1\n0");
        }
    }

    static void expand(int mask, Map<Integer, Integer> dist, Map<Integer, Long> ways, PriorityQueue<Item> pq) {
        int boat = mask / 1000000;
        int left50 = (mask % 1000000) / 100;
        int left100 = mask % 100;

        if (boat > 0) {
            for (int i = left50; i >= 0 && 50 * (left50 - i) <= k; i--) {
                for (int j = left100; j >= 0 && 50 * (left50 - i) + 100 * (left100 - j) <= k; j--) {
                    if (i != left50 || j != left100) {
                        long edge = comb[left50][i] * comb[left100][j] % MOD;
                        relax(mask, i * 100 + j, edge, dist, ways, pq);
                    }
                }
            }
        } else {
            for (int i = left50; i <= cnt50 && 50 * (i - left50) <= k; i++) {
                for (int j = left100; j <= cnt100 && 50 * (i - left50) + 100 * (j - left100) <= k; j++) {
                    if (i != left50 || j != left100) {
                        long edge = comb[cnt50 - left50][i - left50] * comb[cnt100 - left100][j - left100] % MOD;
                        relax(mask, 1000000 + i * 100 + j, edge, dist, ways, pq);
                    }
                }
            }
        }
    }

    static void relax(int fromMask, int toMask, long edge, Map<Integer, Integer> dist, Map<Integer, Long> ways, PriorityQueue<Item> pq) {
        int nd = dist.get(fromMask) + 1;
        Integer old = dist.get(toMask);
        if (old == null || nd < old) {
            dist.put(toMask, nd);
            ways.put(toMask, ways.get(fromMask) * edge % MOD);
            pq.add(new Item(toMask, nd));
        } else if (nd == old) {
            ways.put(toMask, (ways.get(toMask) + ways.get(fromMask) * edge) % MOD);
        }
    }

    static void precomputeCombinations() {
        for (int i = 0; i < 100; i++) {
            comb[i][0] = 1;
        }
        for (int i = 1; i < 100; i++) {
            for (int j = 1; j <= i; j++) {
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
            }
        }
    }
}

