public class Main {
    long mod = 1_000_000_007;
    int colMax;

    long inv(long n) {
        long k = mod - 2;
        long res = 1;
        long a = n;
        while(k > 0) {
            if ((k & 1) > 0) res = (res * a) % mod;
            a = (a * a) % mod;
            k >>= 1;
        }
        return res;
    }

    int idx(int i, int j, int b) {
        return (i * (colMax + 1) + j) * 2 + b;
    }

    public void solve() {
        long[] f = new long[51];
        f[0] = 1;
        for (int i = 1; i < 51; i++) f[i] = (f[i - 1] * i) % mod;
        long[][] c = new long[51][51];
        for (int i = 0; i < 51; i++) c[i][0] = 1;
        for (int i = 1; i < 51; i++) {
            for (int j = 1; j <= i; j++) {
                c[i][j] = (f[i] * inv(((f[j] * f[i - j]) % mod))) % mod;
            }
        }

        int n = ni();
        int k = ni();
        int c50 = 0, c100 = 0;
        for (int i = 0; i < n; i++) {
            if (ni() == 100) c100++;
            else c50++;
        }
        colMax = c100;
        int states = (c50 + 1) * (c100 + 1) * 2;
        ArrayList<Integer>[] adj = new ArrayList[states];
        for (int i = 0; i < states; i++) adj[i] = new ArrayList<>();

        for (int i = 0; i <= c50; i++) {
            for (int j = 0; j <= c100; j++) {
                int from = idx(i, j, 0);
                int p50c = Math.min(k / 50, i);
                int p100c = Math.min(k / 100, j);
                for (int x = p100c; x >= 0; x--) {
                    for (int y = Math.min(p50c, (k - 100 * x) / 50); y >= 0; y--) {
                        if (x == 0 && y == 0) continue;
                        int to = idx(i - y, j - x, 1);
                        adj[from].add(to);
                        adj[to].add(from);
                    }
                }
            }
        }

        int[] dist = new int[states];
        long[] ways = new long[states];
        int start = idx(c50, c100, 0);
        int target = idx(0, 0, 1);
        dist[start] = 1;
        ways[start] = 1;
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(start);
        while (!q.isEmpty()) {
            int u = q.poll();
            int ub = u & 1;
            int tmp = u >> 1;
            int uj = tmp % (colMax + 1);
            int ui = tmp / (colMax + 1);
            for (int v : adj[u]) {
                if (dist[v] == 0 || dist[v] == dist[u] + 1) {
                    int vb = v & 1;
                    int tmp2 = v >> 1;
                    int vj = tmp2 % (colMax + 1);
                    int vi = tmp2 / (colMax + 1);
                    long p1 = c[ub == 0 ? ui : c50 - ui][Math.abs(ui - vi)];
                    long p2 = c[ub == 0 ? uj : c100 - uj][Math.abs(uj - vj)];
                    ways[v] = (ways[v] + (ways[u] * ((p1 * p2) % mod)) % mod) % mod;
                    if (dist[v] == 0) {
                        dist[v] = dist[u] + 1;
                        q.add(v);
                    }
                }
            }
        }
        write((dist[target] - 1) + "\n" + ways[target] + "\n");
    }

    public static void main(String[] args) {
