public class Main {
    long mod = 1_000_000_007;

    long inv(long n) {
        long k = mod - 2;
        long res = 1;
        long a = n;
        while(k > 0) {
            if ((k & 1) > 0) res = (res * a) % mod;
            a = (a * a) % mod;
            k >>= 1;
        }
        return res;
    }

    class Node {
        int c50, c100, b, n;
        long am;
        Node(int x, int y, int z) {
            c50 = x;
            c100 = y;
            b = z;
            n = 0;
            am = 0;
        }
    }

    void relax(Node cur, Node ch, ArrayDeque<Node> q, long[][] c, int c50, int c100) {
        if (ch.n == 0 || ch.n == cur.n + 1) {
            long p1 = c[cur.b == 0 ? cur.c50 : c50 - cur.c50][Math.abs(cur.c50 - ch.c50)];
            long p2 = c[cur.b == 0 ? cur.c100 : c100 - cur.c100][Math.abs(cur.c100 - ch.c100)];
            ch.am = (ch.am + (cur.am * ((p1 * p2) % mod)) % mod) % mod;
            if (ch.n == 0) {
                ch.n = cur.n + 1;
                q.add(ch);
            }
        }
    }

    public void solve() {
        long[] f = new long[51];
        f[0] = 1;
        for (int i = 1; i < 51; i++) f[i] = (f[i - 1] * i) % mod;
        long[][] c = new long[51][51];
        for (int i = 0; i < 51; i++) c[i][0] = 1;
        for (int i = 1; i < 51; i++) {
            for (int j = 1; j <= i; j++) {
                c[i][j] = (f[i] * inv(((f[j] * f[i - j]) % mod))) % mod;
            }
        }

        int n = ni();
        int k = ni();
        int c50 = 0, c100 = 0;
        for (int i = 0; i < n; i++) {
            if (ni() == 100) c100++;
            else c50++;
        }

        Node[][][] ns = new Node[c50 + 1][c100 + 1][2];
        for (int i = 0; i <= c50; i++) {
            for (int j = 0; j <= c100; j++) {
                ns[i][j][0] = new Node(i, j, 0);
                ns[i][j][1] = new Node(i, j, 1);
            }
        }

        ArrayDeque<Node> q = new ArrayDeque<>();
        ns[c50][c100][0].n = 1;
        ns[c50][c100][0].am = 1;
        q.add(ns[c50][c100][0]);

        while (!q.isEmpty()) {
            Node cur = q.poll();
            if (cur.b == 0) {
                int p50c = Math.min(k / 50, cur.c50);
                int p100c = Math.min(k / 100, cur.c100);
                for (int x = p100c; x >= 0; x--) {
                    int ymax = Math.min(p50c, (k - 100 * x) / 50);
                    for (int y = ymax; y >= 0; y--) {
                        if (x == 0 && y == 0) continue;
                        relax(cur, ns[cur.c50 - y][cur.c100 - x][1], q, c, c50, c100);
                    }
                }
            } else {
                int maxX = Math.min(k / 100, c100 - cur.c100);
                for (int x = maxX; x >= 0; x--) {
                    int ymax = Math.min((k - 100 * x) / 50, c50 - cur.c50);
                    for (int y = ymax; y >= 0; y--) {
                        if (x == 0 && y == 0) continue;
                        relax(cur, ns[cur.c50 + y][cur.c100 + x][0], q, c, c50, c100);
                    }
                }
            }
        }

        write((ns[0][0][1].n - 1) + "\n" + ns[0][0][1].am + "\n");
    }

