    long inv(long n) {
        long k = mod - 2;
        long res = 1;
        long a = n;
        while(k > 0) {
            if ((k & 1) > 0) res = (res * a) % mod;
            a = (a * a) % mod;
            k >>= 1;
        }
        return res;
    }

    int enc(int i, int j, int b) {
        return (i * base + j) * 2 + b;
    }

    public void solve() {
        long[] f = new long[51];
        f[0] = 1;
        for (int i = 1; i < 51; i++) f[i] = (f[i - 1] * i) % mod;
        long[][] c = new long[51][51];
        for (int i = 0; i < 51; i++) c[i][0] = 1;
        for (int i = 1; i < 51; i++) {
            for (int j = 1; j <= i; j++) {
                c[i][j] = (f[i] * inv(((f[j] * f[i - j]) % mod))) % mod;
            }
        }

        int n = ni();
        int k = ni();
        int c50 = 0, c100 = 0;
        for (int i = 0; i < n; i++) {
            if (ni() == 100) c100++;
            else c50++;
        }

        base = c100 + 1;
        int[][][] dist = new int[c50 + 1][c100 + 1][2];
        long[][][] ways = new long[c50 + 1][c100 + 1][2];

        int start = enc(c50, c100, 0);
        int target = enc(0, 0, 1);
        dist[c50][c100][0] = 1;
        ways[c50][c100][0] = 1;

        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(start);

        while (!q.isEmpty()) {
            int u = q.poll();
            int ub = u & 1;
            int tmp = u >> 1;
            int uj = tmp % base;
            int ui = tmp / base;
            int udist = dist[ui][uj][ub];

            if (ub == 0) {
                int p50c = Math.min(k / 50, ui);
                int p100c = Math.min(k / 100, uj);
                for (int x = p100c; x >= 0; x--) {
                    int ymax = Math.min(p50c, (k - 100 * x) / 50);
                    for (int y = ymax; y >= 0; y--) {
                        if (x == 0 && y == 0) continue;
                        int vi = ui - y;
                        int vj = uj - x;
                        int vb = 1;
                        if (dist[vi][vj][vb] == 0 || dist[vi][vj][vb] == udist + 1) {
                            long p1 = c[ui][Math.abs(ui - vi)];
                            long p2 = c[uj][Math.abs(uj - vj)];
                            ways[vi][vj][vb] = (ways[vi][vj][vb] + (ways[ui][uj][ub] * ((p1 * p2) % mod)) % mod) % mod;
                            if (dist[vi][vj][vb] == 0) {
                                dist[vi][vj][vb] = udist + 1;
                                q.add(enc(vi, vj, vb));
                            }
                        }
                    }
                }
            } else {
                int maxX = Math.min(k / 100, c100 - uj);
                for (int x = maxX; x >= 0; x--) {
                    int ymax = Math.min((k - 100 * x) / 50, c50 - ui);
                    for (int y = ymax; y >= 0; y--) {
                        if (x == 0 && y == 0) continue;
                        int vi = ui + y;
                        int vj = uj + x;
                        int vb = 0;
                        if (dist[vi][vj][vb] == 0 || dist[vi][vj][vb] == udist + 1) {
                            long p1 = c[c50 - ui][Math.abs(ui - vi)];
                            long p2 = c[c100 - uj][Math.abs(uj - vj)];
                            ways[vi][vj][vb] = (ways[vi][vj][vb] + (ways[ui][uj][ub] * ((p1 * p2) % mod)) % mod) % mod;
                            if (dist[vi][vj][vb] == 0) {
                                dist[vi][vj][vb] = udist + 1;
                                q.add(enc(vi, vj, vb));
                            }
                        }
                    }
                }
            }
        }

        write((dist[0][0][1] - 1) + "\n" + ways[0][0][1] + "\n");
    }

