        BufferedReader br;
        StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    static class Solver {
        final long MOD = 1000000007L;
        final long INF = (long) 1e18 + 1;
        long[][] C = new long[100][100];

        long f(long p, int a, int b, int c, int d) {
            p = p * C[a][b] % MOD;
            p = p * C[c][d] % MOD;
            return p;
        }

        void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int K = in.nextInt();
            for (int i = 0; i < 100; i++) {
                for (int j = 0; j <= i; j++) {
                    if (j == 0 || j == i) C[i][j] = 1;
                    else C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % MOD;
                }
            }
            int cnt1 = 0, cnt2 = 0;
            for (int i = 0; i < n; i++) {
                if (in.nextInt() == 50) cnt1++;
                else cnt2++;
            }
            long[][][] dist = new long[200][200][2];
            long[][][] dp = new long[200][200][2];
            for (int i = 0; i < 200; i++) {
                for (int j = 0; j < 200; j++) {
                    Arrays.fill(dist[i][j], INF);
                }
            }
            dist[0][0][0] = 0;
            dp[0][0][0] = 1;
            ArrayDeque<State> q = new ArrayDeque<>();
            q.add(new State(0, 0, 0));
            while (!q.isEmpty()) {
                State cur = q.poll();
                int x = cur.x;
                int y = cur.y;
                int z = cur.z;
                long d = dist[x][y][z];
                if (z == 0) {
                    int rx = cnt1 - x;
                    int ry = cnt2 - y;
                    for (int a = 0; a <= rx; a++) {
                        for (int b = 0; b <= ry; b++) {
                            if (a + b == 0) continue;
                            if (a * 50 + b * 100 > K) break;
                            int nx = x + a;
                            int ny = y + b;
                            int nz = 1;
                            if (dist[nx][ny][nz] >= d + 1) {
                                long add = f(dp[x][y][z], rx, a, ry, b);
                                if (dist[nx][ny][nz] > d + 1) {
                                    dist[nx][ny][nz] = d + 1;
                                    q.add(new State(nx, ny, nz));
                                }
                                dp[nx][ny][nz] = (dp[nx][ny][nz] + add) % MOD;
                            }
                        }
                    }
                } else {
                    int rx = x;
                    int ry = y;
                    for (int a = 0; a <= rx; a++) {
                        for (int b = 0; b <= ry; b++) {
                            if (a + b == 0) continue;
                            if (a * 50 + b * 100 > K) break;
                            int nx = x - a;
                            int ny = y - b;
                            int nz = 0;
                            if (dist[nx][ny][nz] >= d + 1) {
                                long add = f(dp[x][y][z], rx, a, ry, b);
                                if (dist[nx][ny][nz] > d + 1) {
                                    dist[nx][ny][nz] = d + 1;
                                    q.add(new State(nx, ny, nz));
                                }
                                dp[nx][ny][nz] = (dp[nx][ny][nz] + add) % MOD;
                            }
                        }
                    }
                }
            }
            if (dist[cnt1][cnt2][1] == INF) out.println(-1);
            else out.println(dist[cnt1][cnt2][1]);
            out.println(dp[cnt1][cnt2][1]);
        }

        static class State {
            int x, y, z;

            State(int x, int y, int z) {
                this.x = x;
                this.y = y;
                this.z = z;
            }
        }
    }
}

