public class Main {
    static final int MOD = 1000000007;
    static int cap, totalF, totalS;
    static long[][][][] memo;
    static long[][] C;

    static long solve(int f, int s, int rides, int boat) {
        if (f == 0 && s == 0 && rides == 0) return 1;
        if (rides == 0) return 0;
        if (memo[f][s][rides][boat] != -1) return memo[f][s][rides][boat];
        long ans = 0;
        if (boat == 1) {
            for (int i = 0; i <= f; i++) {
                for (int j = 0; j <= s; j++) {
                    if (i + j > 0 && 2 * i + j <= cap) {
                        long choose = C[f][i] * C[s][j] % MOD;
                        ans = (ans + choose * solve(f - i, s - j, rides - 1, 0)) % MOD;
                    }
                }
            }
        } else {
            for (int i = 0; i <= totalF - f; i++) {
                for (int j = 0; j <= totalS - s; j++) {
                    if (i + j > 0 && 2 * i + j <= cap) {
                        long choose = C[totalF - f][i] * C[totalS - s][j] % MOD;
                        ans = (ans + choose * solve(f + i, s + j, rides - 1, 1)) % MOD;
                    }
                }
            }
        }
        return memo[f][s][rides][boat] = ans;
    }

