            long[][][] next = new long[totalF + 1][totalS + 1][2];
            boolean[][][] seen = new boolean[totalF + 1][totalS + 1][2];
            List<Integer> nextActive = new ArrayList<>();

            for (int code : active) {
                int f = decodeF(code);
                int s = decodeS(code);
                int b = decodeB(code);
