        int ret = 0;
        byte c;
        while ((c = dis.readByte()) <= ' ');
        boolean neg = (c == '-');
        if (neg) c = dis.readByte();
        do {
            ret = ret * 10 + c - '0';
        } while ((c = dis.readByte()) >= '0' && c <= '9');
        if (neg) return -ret;
        return ret;
    }
