        if (pos == n) {
            return Math.abs(sum) == m;
        }
        long rem = suff[pos];
        if (Math.abs(m - sum) > rem && Math.abs(-m - sum) > rem) {
            return false;
        }
        if (dfs(pos + 1, sum - bases[pos])) return true;
        if (dfs(pos + 1, sum)) return true;
        if (dfs(pos + 1, sum + bases[pos])) return true;
        return false;
    }
}

