        boolean negative = false;
        if (c == '-') {
            negative = true;
            c = is.read();
        } else if (c == '+') {
            c = is.read();
        }
        int number = 0;
        while (c > ' ') {
            number = number * 10 + (c - '0');
            c = is.read();
        }
        return negative ? -number : number;
    }

