class TaskC {
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int w = in.nextInt(), m = in.nextInt(), n = 0;
        int[] a = new int[50];
        do {
            a[++n] = m % w;
            m /= w;
        } while (m > 0);

        boolean ok = true;
        for(int i = 1; i <= n;)
            if (a[i] > 1) {
                a[i] += 1;
