public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        int w = in.nextInt();
        int m = in.nextInt();
        int[] a = new int[50];
        int n = 0;
        do {
            a[++n] = m % w;
            m /= w;
        } while (m > 0);
        out.print(possible(w, n, a) ? "YES" : "NO");
        out.close();
    }

    private static boolean possible(int w, int n, int[] a) {
        return step(w, n, a, 1);
    }

    private static boolean step(int w, int n, int[] a, int i) {
        if (i > n) {
            return true;
        }
        if (a[i] <= 1) {
            return step(w, n, a, i + 1);
        }
        a[i] += 1;
        if (a[i] == w) {
            int j = i;
            while (j <= n && a[j] >= w) {
                a[j] = 0;
                j++;
                a[j] += 1;
            }
            if (a[j - 1] > 1) {
                return false;
            }
            return step(w, n, a, j);
        } else {
            i++;
            if (a[i - 1] > 1) {
                return false;
            }
            return step(w, n, a, i);
        }
    }
}

