class BalanceChecker {
    private int w;
    private int n;
    private int[] a;

    BalanceChecker(int w, int n, int[] a) {
        this.w = w;
        this.n = n;
        this.a = a;
    }

    boolean check() {
        for (int i = 1; i <= n; ) {
            if (a[i] <= 1) {
                i++;
                continue;
            }
            a[i] += 1;
            if (a[i] == w) {
                while (i <= n && a[i] >= w) {
                    a[i] = 0;
                    i++;
                    a[i] += 1;
                }
            } else {
                i++;
            }
            if (a[i - 1] > 1) {
                return false;
            }
        }
        return true;
    }
}

