public class CF552C {
    static boolean normalize(int[] a, int i, int w) {
        if (i == a.length) {
            return true;
        }
        if (a[i] == 1 || a[i] == 0 || a[i] == -1) {
            return normalize(a, i + 1, w);
        } else if (a[i] == w - 1) {
            a[i] -= w;
            a[i + 1]++;
            return normalize(a, i + 1, w);
        } else if (a[i] == w) {
            a[i] = 0;
            a[i + 1]++;
            return normalize(a, i + 1, w);
        } else {
            return false;
        }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int w = in.nextInt();
        int m = in.nextInt();
        in.close();

        int[] digits = new int[100];
        int len = 0;
        while (m > 0) {
            digits[len++] = m % w;
            m /= w;
        }

        System.out.println(normalize(digits, 0, w) ? "YES" : "NO");
    }
}

