import java.io.IOException;
import java.io.PrintWriter;
import java.util.Scanner;

public class Main {
    public static void main(String args[]) throws IOException {
        Scanner fi = new Scanner(System.in);
        int w = fi.nextInt();
        int m = fi.nextInt();
        boolean ok = solve(w, m);
        PrintWriter fo = new PrintWriter(System.out);
        fo.print(ok ? "YES" : "NO");
        fi.close();
        fo.close();
    }

    private static boolean solve(int w, int m) {
        if (m == 0) {
            return true;
        }
        int d = m % w;
        if (d == 0 || d == 1) {
            return solve(w, m / w);
        }
        if (d == w - 1) {
            return solve(w, (m + 1) / w);
        }
        return false;
    }
}

