            pw[i] = p;
            p *= w;
            if (p > 1L << 40) {
                mx = i;
                break;
            }
        }

        boolean ok = false;
        Deque<long[]> stack = new ArrayDeque<long[]>();
        stack.push(new long[]{0, m, mx});
        while (!stack.isEmpty() && !ok) {
            long[] state = stack.pop();
            long cur = state[0];
            long target = state[1];
            int pos = (int) state[2];
            if (cur == target) {
                ok = true;
                break;
            }
            long remaining = sum[pos + 1];
            long next = pw[pos];
            if (cur - remaining > target) continue;
            if (cur + remaining < target) continue;
            if (cur + sum[pos] < target) {
                stack.push(new long[]{cur + next, target, pos - 1});
            } else if (cur - sum[pos] > target) {
                stack.push(new long[]{cur - next, target, pos - 1});
            } else {
                stack.push(new long[]{cur, target, pos - 1});
            }
        }

        System.out.println(ok ? "YES" : "NO");
    }
}

