        int n = list.size();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = list.get(i);
        }

        int total = 1 << n;
        long[] added = new long[total];
        for (int mask = 1; mask < total; mask++) {
            int bit = Integer.numberOfTrailingZeros(mask);
            added[mask] = added[mask ^ (1 << bit)] + a[bit];
        }

        boolean ok = false;
        for (int mask = 0; mask < total; mask++) {
            long v = m + added[mask];
            for (int j = n - 1; j >= 0; j--) {
                if ((mask & (1 << j)) == 0 && v - a[j] >= 0) {
                    v -= a[j];
                }
            }
            if (v == 0) {
