public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int w = in.nextInt();
        long m = in.nextInt();
        PrintWriter out = new PrintWriter(System.out);

        if (w <= 3) {
            out.print("YES\n");
            out.flush();
            return;
        }

        long base = w;
        long cur = m;
        boolean ok = true;

        while (cur != 0) {
            long r = Math.floorMod(cur, base);
            long digit;
            if (r == 0) {
                digit = 0;
            } else if (r == 1) {
                digit = 1;
            } else if (r == base - 1) {
                digit = -1;
            } else {
                ok = false;
                break;
            }
            cur = Math.floorDiv(cur - digit, base);
        }

        out.print(ok ? "YES\n" : "NO\n");
        out.flush();
    }
}

import java.io.PrintWriter;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int w = in.nextInt();
        long m = in.nextInt();
        PrintWriter out = new PrintWriter(System.out);

        if (w <= 3) {
            out.print("YES\n");
            out.flush();
            return;
        }

        out.print(can(m, w) ? "YES\n" : "NO\n");
        out.flush();
    }

    static boolean can(long n, long base) {
        if (n == 0) {
            return true;
        }
        long r = Math.floorMod(n, base);
        if (r == 0) {
            return can(Math.floorDiv(n, base), base);
        }
        if (r == 1) {
            return can(Math.floorDiv(n - 1, base), base);
        }
        if (r == base - 1) {
            return can(Math.floorDiv(n + 1, base), base);
        }
        return false;
    }
}

