public class vanyaandscale {
    public static void main(String[] arg) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long w = Long.parseLong(st.nextToken());
        long m = Long.parseLong(st.nextToken());

        if (w <= 3) {
            System.out.println("YES");
            return;
        }

        long limit = 100000000000L;
        long[] a = new long[40];
        a[0] = 1L;
        long temp = 1L;
        int n = 1;

        while (n < 16) {
            temp *= w;
            a[n] = temp;
            if (temp > limit) break;
            n++;
        }

        boolean ok = false;
        Stack<long[]> stack = new Stack<>();
        stack.push(new long[]{0L, 0L, m, 0L});

        while (!stack.isEmpty() && !ok) {
            long[] cur = stack.pop();
            int idx = (int) cur[0];
            long left = cur[1];
            long right = cur[2];
            int choice = (int) cur[3];

            if (idx == n) {
                if (left == right) ok = true;
                continue;
            }

            if (choice == 0) {
                cur[3] = 1L;
                stack.push(cur);
                stack.push(new long[]{idx + 1L, left, right, 0L});
            } else if (choice == 1) {
                cur[3] = 2L;
                stack.push(cur);
                stack.push(new long[]{idx + 1L, left + a[idx], right, 0L});
            } else {
                stack.push(new long[]{idx + 1L, left, right + a[idx], 0L});
            }
        }

        System.out.println(ok ? "YES" : "NO");
    }
}

