public class vanyaandscale {
    static long[] a;

    public static void main(String[] arg) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long w = Long.parseLong(st.nextToken());
        long m = Long.parseLong(st.nextToken());

        if (w <= 3) {
            System.out.println("YES");
            return;
        }

        long limit = 100000000000L;
        a = new long[40];
        a[0] = 1L;
        long temp = 1L;
        int n = 1;

        while (n < 16) {
            temp *= w;
            a[n] = temp;
            if (temp > limit) break;
            n++;
        }

        int mid = n / 2;
        List<Long> leftSums = new ArrayList<>();
        List<Long> rightSums = new ArrayList<>();
        generate(0, mid, 0L, leftSums);
        generate(mid, n, 0L, rightSums);
        Collections.sort(rightSums);

        boolean ok = false;
        for (long value : leftSums) {
            if (Collections.binarySearch(rightSums, m - value) >= 0) {
                ok = true;
                break;
            }
        }

        System.out.println(ok ? "YES" : "NO");
    }

    static void generate(int pos, int end, long sum, List<Long> out) {
        if (pos == end) {
            out.add(sum);
            return;
        }
        generate(pos + 1, end, sum, out);
        generate(pos + 1, end, sum + a[pos], out);
        generate(pos + 1, end, sum - a[pos], out);
    }
}

