        while (m != 0) {
            all.add(m % w);
            m /= w;
        }

        for (int i = 0; i < all.size(); ++i) {
            if (all.get(i) == 0 || all.get(i) == 1)
                continue;
            if (all.get(i) == w - 1) {
                int j = i + 1;
                while (j < all.size()) {
                    if (all.get(j) == w - 1) {
