        for (int i = 0; i < size; i++) {
            digit[i] = x % w;
            x /= w;
        }

        boolean ok = true;
        for (int i = 0; i < size && ok; i++) {
            int d = digit[i];
            if (d == 0 || d == 1) {
                continue;
            }
            if (d == w - 1) {
                int j = i + 1;
                while (j < size) {
                    if (digit[j] == w - 1) {
                        digit[j] = 0;
                    } else {
                        digit[j]++;
                        break;
                    }
                    j++;
                }
                continue;
            }
            ok = false;
        }

        System.out.println(ok ? "YES" : "NO");
    }
