    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        solve(1, in, out);
        out.close();
    }

    static void solve(int testNumber, InputReader in, PrintWriter out) {
        int n = in.nextInt();
        long k = in.nextLong();
        if (k == 0) {
            long[] factArr = precomputeFactorials(n);
            out.println(factArr[n]);
            return;
        }

        if (k > n - 1) {
            out.println(0);
            return;
        }

        int c = (int) (n - k);

        long[] factArr = precomputeFactorials(n);
        long[] invFactArr = precomputeInvFactorials(n, factArr);

        long answer = 0;
        for (int i = 1; i <= c; i++) {
            long term = paritySign(c - i);
            term = term * ncr(c, i, factArr, invFactArr) % MOD;
            term = term * pow(i, n) % MOD;
            answer = add(answer, term);
        }

        answer = answer * 2 % MOD;
        answer = answer * ncr(n, c, factArr, invFactArr) % MOD;
        out.println(answer);
    }

    static long[] precomputeFactorials(int n) {
        long[] fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        return fact;
    }

    static long[] precomputeInvFactorials(int n, long[] fact) {
        long[] invFact = new long[n + 1];
        invFact[n] = pow(fact[n], -1);
        for (int i = n - 1; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        }
        return invFact;
    }

    static long paritySign(long k) {
        return (k & 1) == 0 ? 1 : MOD - 1;
    }

    static long ncr(int n, int r, long[] fact, long[] invFact) {
        if (r < 0 || n < r) return 0;
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }

    static long add(long a, long b) {
        long v = a + b;
        return v < MOD ? v : v - MOD;
    }

    static long pow(long x, int e) {
        if (e < 0) {
            x = inv(x);
            e = -e;
        }
        long res = 1;
        while (e > 0) {
            if ((e & 1) != 0) res = res * x % MOD;
            x = x * x % MOD;
            e >>= 1;
        }
        return res;
    }

    static long inv(long value) {
        long g = MOD, x = 0, y = 1;
        for (long r = value; r != 0; ) {
            long q = g / r;
            g %= r;
            long temp = g; g = r; r = temp;
            x -= q * y;
            temp = x; x = y; y = temp;
        }
        x %= MOD;
        if (x < 0) x += MOD;
        return x;
    }

