class Modulo {

    private final long mod;

    public Modulo(long mod) {
        this.mod = mod;
    }

    public long add(long a, long b) {
        long c = a + b;
        if (c >= mod) c -= mod;
        return c;
    }

    public long subtract(long a, long b) {
        long c = a - b;
        if (c < 0) c += mod;
        return c;
    }

    public long multiply(long a, long b) {
        return (a * b) % mod;
    }

    public long divide(long a, long b) {
        return multiply(a, pow(b, mod - 2));
    }

    public long pow(long a, long b) {
        long res = 1;
        while (b > 0) {
            if ((b & 1) == 1) res = (res * a) % mod;
            a = (a * a) % mod;
            b >>= 1;
        }
        return res;
    }

    public long combination(int n, int k, long[] facts) {
        if (k < 0 || k > n) return 0;
        return divide(facts[n], multiply(facts[k], facts[n - k]));
    }

    public long[] factorials(int n) {
        long[] f = new long[n + 1];
        f[0] = 1;
        for (int i = 1; i <= n; i++) f[i] = (f[i - 1] * i) % mod;
        return f;
    }

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.stream.*;


public class E {

    private static final FastReader IN = new FastReader();
    private static final FastWriter OUT = new FastWriter();

    public static void main(String[] args) {
        new E().run();
    }

    private void run() {
        int tests = 1;
        while (tests-- > 0) {
            solve();
        }
        OUT.flush();
    }

    private void solve() {
        int n = IN.nextInt();
        long kt = IN.nextLong();

        if (kt >= n) {
            OUT.println(0);
            return;
        }

        int k = (int) kt;
        int mod = 998244353;
        long[] facts = factorials(n, mod);

        long ans = 0;
        int c = n - k;
        for (int i = 0; i <= c; i++) {
            long term = multiply(comb(c, i, facts, mod), powMod(c - i, n, mod), mod);
            if ((i & 1) == 0) {
                ans = add(ans, term, mod);
            } else {
                ans = subtract(ans, term, mod);
            }
        }
        ans = multiply(ans, comb(n, n - k, facts, mod), mod);
        if (k > 0) ans = multiply(ans, 2, mod);
        OUT.println(ans);
    }

    private static long add(long a, long b, int mod) {
        long c = a + b;
        return c >= mod ? c - mod : c;
    }

    private static long subtract(long a, long b, int mod) {
        long c = a - b;
        return c < 0 ? c + mod : c;
    }

