public class Perturbed5 {
    static final int MOD = 998244353;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long k = sc.nextLong();
        if (k >= n) {
            System.out.println(0);
            return;
        }
        long[] fact = new long[n + 1];
        fact[0] = 1;
        int i = 1;
        while (i <= n) {
            fact[i] = fact[i - 1] * i % MOD;
            i++;
        }
        if (k == 0) {
            System.out.println(fact[n]);
            return;
        }
        int c = n - (int) k;
        long ans = fact[n] * modInv(fact[c]) % MOD;
        ans = ans * modInv(fact[n - c]) % MOD;
        long sum = 0;
        for (int j = 0; j <= c; j++) {
            long comb = fact[c] * modInv(fact[j]) % MOD * modInv(fact[c - j]) % MOD;
            long term = comb * modPow(c - j, n) % MOD;
            if ((j & 1) == 0) {
                sum = (sum + term) % MOD;
            } else {
                sum = (sum - term + MOD) % MOD;
            }
        }
        ans = ans * sum % MOD * 2 % MOD;
        System.out.println(ans);
    }

    static long modInv(long a) {
        // Extended Euclidean algorithm
        long t = 0, newt = 1;
        long r = MOD, newr = a;
        while (newr != 0) {
            long q = r / newr;
            long temp = t - q * newt;
            t = newt;
            newt = temp;
            temp = r - q * newr;
            r = newr;
            newr = temp;
        }
        if (r > 1) throw new ArithmeticException("Not invertible");
        if (t < 0) t += MOD;
        return t;
    }

    static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }
}

