import java.util.*;
import java.io.*;
public class EdE {

    public static void main(String[] args) throws Exception{
        int mod = 998244353;

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        long n = Long.parseLong(st.nextToken());
        long k = Long.parseLong(st.nextToken());

        long[] fact = new long[200001];
        fact[0] = 1;
        long prod = 1;
        int i = 1;
        while (i <= 200000) {
            prod = (prod * i) % mod;
            fact[i] = prod;
            i++;
        }

        long sum = 0;
        int limit = (int)(n - k);
        int idx = 0;
        while (idx < limit) {
            long comb = fact[limit];
            comb = comb * modPow(fact[idx], mod - 2, mod) % mod;
            comb = comb * modPow(fact[limit - idx], mod - 2, mod) % mod;
            long term = comb * modPow(limit - idx, n, mod) % mod;
            if (idx % 2 == 0) {
                sum += term;
            } else {
                sum -= term;
            }
            sum %= mod;
            idx++;
        }

        if (k >= n) {
            pw.println(0);
        } else {
            if (k != 0) {
                sum = sum * 2 % mod;
            }
            sum = sum * fact[(int)n] % mod;
            sum = sum * modPow(fact[(int)k], mod - 2, mod) % mod;
            sum = sum * modPow(fact[(int)(n - k)], mod - 2, mod) % mod;
            while (sum < 0) {
                sum += mod;
            }
            pw.println(sum);
        }
        pw.close();
    }

    public static long modPow(long x, long y, long mod) {
        long res = 1;
        while (y > 0) {
            if ((y & 1) == 1) {
                res = (res * x) % mod;
            }
            x = (x * x) % mod;
            y >>= 1;
        }
        return res;
    }
}

