            .mapToLong(i -> {
                long comb = fact[limit];
                comb = comb * modPow(fact[i], mod - 2, mod) % mod;
                comb = comb * modPow(fact[limit - i], mod - 2, mod) % mod;
                long term = comb * modPow(limit - i, n, mod) % mod;
                return (i % 2 == 0) ? term : -term;
            })
            .reduce(0, (a, b) -> (a + b) % mod);

        if (k >= n) {
            pw.println(0);
        } else {
            if (k != 0) {
                sum = sum * 2 % mod;
            }
            sum = sum * fact[(int)n] % mod;
            sum = sum * modPow(fact[(int)k], mod - 2, mod) % mod;
            sum = sum * modPow(fact[(int)(n - k)], mod - 2, mod) % mod;
            while (sum < 0) {
                sum += mod;
            }
            pw.println(sum);
        }
        pw.close();
    }

    public static long modPow(long x, long y, long mod) {
        long res = 1;
        while (y > 0) {
            if ((y & 1) == 1) {
                res = (res * x) % mod;
            }
            x = (x * x) % mod;
            y >>= 1;
        }
        return res;
    }
}

