	static void solve() {
		int n = ni();
		long tmp = nl();
		if(n <= tmp) {
			out.println(0);
			return;
		}
		int k = (int)tmp;
		preFact(400000);
		long ans = 0;
		int sign = 1;
		int limit = n - k;
		int i = 1;
		while(i <= limit) {
			ans += sign * cmb(limit, i) * pow(i, n);
			ans %= mod;
			if(ans < 0) ans += mod;
			sign = -sign;
			i++;
		}
		long t = cmb(n, n-k);
		ans = (ans * t) % mod;
		if(k != 0) ans = (ans * 2) % mod;
		if(ans < 0) ans += mod;
		out.println(ans);
	}

