		int k = (int)tmp;
		preFact(400000);
		int limit = n - k;
		long ans = IntStream.rangeClosed(1, limit)
			.mapToLong(i -> ((i % 2 == 0) ? -1 : 1) * cmb(limit, i) * pow(i, n))
			.reduce(0, (a, b) -> (a + b) % mod);
		if (ans < 0) ans += mod;
		long t = cmb(n, n-k);
		ans = (ans * t) % mod;
		if(k != 0) ans = (ans * 2) % mod;
		if(ans < 0) ans += mod;
		out.println(ans);
	}

