	static long sum(int i, int limit, int n, int sign) {
		if (i > limit) return 0;
		long term = sign * cmb(limit, i) * pow(i, n);
		term %= mod;
		if (term < 0) term += mod;
		return (term + sum(i + 1, limit, n, -sign)) % mod;
	}

	//Fast Fermat Combination
	static long fact[];
	static long revFact[];

	static void preFact(int n) {
		fact = new long[n + 1];
		revFact = new long[n + 1];
		fact[0] = 1;
		for (int i = 0; i < n; i++) {
			fact[i + 1] = mul(i + 1, fact[i]);
		}
		revFact[n] = div(1, fact[n]);
		for (int i = n - 1; i >= 0; i--) {
			revFact[i] = mul(revFact[i + 1], i + 1);
		}
	}

	static long cmb(int a, int b) {
		if (a<b)return 0;
		if (fact.length == 0)
			System.err.println("error : factorials has not been culculated!! do [pre_factorial] method");
		long af = fact[a];
		long bf = revFact[b];
		long abf = revFact[a - b];
		long res = mul(mul(af, bf), abf);
		return res;
	}

