	static void solve() {
		int n = ni();
		long tmp = nl();
		if(n <= tmp) {
			out.println(0);
			return;
		}
		int k = (int)tmp;
		preFact(400000);
		long ans = 0;
		int limit = n - k;
		long t = cmb(n, limit);
		boolean positive = true;
		int i = 1;
		while(i <= limit) {
			long term = (positive ? 1 : -1) * cmb(limit, i) * powIter(i, n);
			term %= mod;
			if(term < 0) term += mod;
			ans = (ans + term) % mod;
			positive = !positive;
			i++;
		}
		if (ans < 0) ans += mod;
		ans = (ans * t) % mod;
		if(k != 0) ans = (ans * 2) % mod;
		if(ans < 0) ans += mod;
		out.println(ans);
	}

	static long powIter(long x, long y) {
		if (y < 0) return 0;
		long res = 1;
		long base = x % mod;
		while (y > 0) {
			if ((y & 1) == 1) {
				res = (res * base) % mod;
			}
			base = (base * base) % mod;
			y >>= 1;
		}
		return res;
	}

