        fact = new long[N + 1];
        invFact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) {
            fact[i] = (i * fact[i - 1]) % MOD;
        }
        invFact[N] = pow(fact[N], MOD - 2);
        for (int i = N - 1; i >= 0; i--) {
            invFact[i] = (invFact[i + 1] * (i + 1)) % MOD;
        }

        long ans = 0;
        int sign = 1;
        int c = N - k;
        for (int i = c; i >= 0; i--) {
            long term = (choose(c, i) * pow(i, N)) % MOD;
            term = sign * term;
            ans = (ans + term + MOD) % MOD;
            sign = -sign;
        }
        ans = (ans * choose(N, c)) % MOD;
        if (k > 0) {
            ans = (2 * ans) % MOD;
        }
        out.println(ans);
        out.close();
    }

    static long choose(int a, int b) {
        if (b < 0 || b > a) return 0;
        return fact[a] * invFact[b] % MOD * invFact[a - b] % MOD;
    }

