public class x1342E {
    static long MOD = 998244353L;
    static long[] fac;
    static long[] invfac;

    public static void main(String omkar[]) throws Exception {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        long lmao = sc.nextLong();
        if (lmao >= N) {
            System.out.println(0);
        } else {
            int K = (int) lmao;
            int C = N - K;
            fac = new long[200001];
            invfac = new long[200001];
            fac[0] = 1L;
            invfac[0] = 1L;
            for (int i = 1; i <= 200000; i++) {
                fac[i] = (fac[i - 1] * i) % MOD;
            }
            // compute invfac using backward method
            invfac[200000] = power(fac[200000], MOD - 2, MOD);
            for (int i = 200000; i >= 1; i--) {
                invfac[i - 1] = (invfac[i] * i) % MOD;
            }
            long res = power(C, N, MOD);
            int e = 1;
            while (e < C) {
                long temp = power(C - e, N, MOD);
                temp = (temp * nCr(e, C)) % MOD;
                if (e % 2 == 1)
                    res = (res - temp + MOD) % MOD;
                else
                    res = (res + temp) % MOD;
                e++;
            }
            res = (res * nCr(C, N)) % MOD;
            if (K > 0)
                res = (2 * res) % MOD;
            System.out.println(res);
        }
        sc.close();
    }

    public static long nCr(int a, int b) {
        long res = fac[b];
        res = (res * invfac[a]) % MOD;
        return (res * invfac[b - a]) % MOD;
    }

    public static long power(long x, long y, long p) {
        long res = 1L;
        x = x % p;
        while (y > 0) {
            if ((y & 1) == 1)
                res = (res * x) % p;
            y = y >> 1;
            x = (x * x) % p;
        }
        return res;
    }
