public class x1342E {
    static long MOD = 998244353L;
    static long[] fac;
    static long[] inv; // modular inverses of 1..200000

    public static void main(String omkar[]) throws Exception {
        BufferedReader infile = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(infile.readLine());
        int N = Integer.parseInt(st.nextToken());
        long lmao = Long.parseLong(st.nextToken());
        if (lmao >= N) {
            System.out.println(0);
        } else {
            int K = (int) lmao;
            int C = N - K;
            fac = new long[200001];
            inv = new long[200001];
            fac[0] = 1L;
            inv[1] = 1L;
            for (int i = 1; i <= 200000; i++) {
                fac[i] = (fac[i - 1] * i) % MOD;
                if (i > 1) {
                    inv[i] = MOD - (MOD / i) * inv[(int) (MOD % i)] % MOD;
                }
            }
            // compute nCr using multiplicative formula with precomputed inverses
            long res = power(C, N, MOD);
            // use IntStream for the sum
            res = IntStream.range(1, C)
                .mapToLong(e -> {
                    long temp = power(C - e, N, MOD);
                    temp = (temp * nCr(e, C)) % MOD;
                    return (e % 2 == 1) ? (MOD - temp) % MOD : temp;
                })
                .reduce(res, (a, b) -> (a + b) % MOD);
            res = (res * nCr(C, N)) % MOD;
            if (K > 0)
                res = (2 * res) % MOD;
            System.out.println(res);
        }
    }

    public static long nCr(int a, int b) {
        // compute C(b, a) = product_{i=1}^{a} (b - a + i) / i
        long res = 1L;
        for (int i = 1; i <= a; i++) {
            res = (res * (b - a + i)) % MOD;
            res = (res * inv[i]) % MOD;
        }
        return res;
    }

    public static long power(long x, long y, long p) {
        long res = 1L;
        x = x % p;
        while (y > 0) {
            if ((y & 1) == 1)
                res = (res * x) % p;
            y = y >> 1;
            x = (x * x) % p;
        }
        return res;
    }
