      long num = 1, den = 1;
      for(int i=(int)(n-k+1); i<=n; i++) num = (num * i) % mod;
      for(int i=1; i<=k; i++) den = (den * i) % mod;
      den = modInverse(den, mod);
      return (num * den) % mod;
   }
   public static long modInverse(long a, long m) {
      long m0 = m, y = 0, x = 1;
      if (m == 1) return 0;
      while (a > 1) {
         long q = a / m;
         long t = m;
         m = a % m;
         a = t;
         t = y;
         y = x - q * y;
         x = t;
      }
      if (x < 0) x += m0;
      return x;
   }
   public static long power(long x, long y) {
      long res = 1;
      x %= mod;
      while (y > 0) {
         if ((y & 1) == 1) { res = (res * x) % mod; }
         y >>= 1;
         x = (x * x) % mod;
      }
      return res;
   }
}

