            rChoose[i] = rChoose[i-1] * (r - i + 1) % mod * inv % mod;
         }
         long ans = IntStream.rangeClosed(0, r)
            .mapToLong(i -> {
               long term = power((long)(r-i), (long)n) * (i%2==0 ? 1 : -1) % mod * rChoose[i] % mod;
               return term;
            })
            .reduce(0L, (a,b) -> (a+b) % mod);
         ans = ans * choose((long)n, (long)k) % mod;
         if(k > 0) ans = (ans * 2) % mod;
         if(ans < 0) ans += mod;
         System.out.println(""+ans);
      }
   }
   public static long choose(long n, long k) {
      long num = LongStream.rangeClosed(n-k+1, n)
         .reduce(1L, (a,b) -> (a * b) % mod);
      long den = LongStream.rangeClosed(1, k)
         .reduce(1L, (a,b) -> (a * b) % mod);
      den = power(den, mod-2);
      return (num * den) % mod;
   }
   public static long power(long x, long y) {
      long res = 1;
      x %= mod;
      while (y > 0) {
         if ((y & 1) == 1) { res = (res * x) % mod; }
         y >>= 1;
         x = (x * x) % mod;
      }
      return res;
   }
}

