class TaskC {
    private int n, m;
    private int[] dx = new int[] {-1, 0, 1, 0, 0};
    private int[] dy = new int[] {0, 1, 0, -1, 0};
    private int step;
    private int numFree;
    private int cur;
    private int res;
    private int[] grid; // single-dimensional array

    public void solve(int n, int m, PrintWriter out) {
        this.n = n;
        this.m = m;
        if (n > m) {
            int t = this.m;
            this.m = this.n;
            this.n = t;
        }
        grid = new int[this.n * this.m];
        res = Integer.MAX_VALUE;
        cur = 0;
        step = 1;
        numFree = this.n * this.m;
        rec(0);
        out.println(this.n * this.m - res);
    }

    private int idx(int x, int y) {
        return x * m + y;
    }

    private void rec(int pos) {
        if (numFree == 0) {
            res = Math.min(res, cur);
            return;
        }
        int x = pos / m;
        int y = pos % m;
        if (x >= n) return;
        if (y >= m) {
            rec(pos + (m - y)); // move to next row
            return;
        }
        if (grid[idx(x, y)] != 0) {
            rec(pos + 1);
            return;
        }

        put(x, y);
        rec(pos + 1);
        remove(x, y);

        if (isValid(x + 1, y)) {
            put(x + 1, y);
            rec(pos + 1);
            remove(x + 1, y);
        }

        if (isValid(x, y + 1)) {
            put(x, y + 1);
            rec(pos + 1);
            remove(x, y + 1);
        }
    }

    private void put(int x, int y) {
        for (int i = 0; i < 5; ++i) {
            int nx = x + dx[i];
            int ny = y + dy[i];
            if (isValid(nx, ny)) {
                if (grid[idx(nx, ny)] == 0) {
                    --numFree;
                    grid[idx(nx, ny)] = step;
                }
            }
        }
        ++step;
        ++cur;
    }

    private void remove(int x, int y) {
        --step;
        for (int i = 0; i < 5; ++i) {
            int nx = x + dx[i];
            int ny = y + dy[i];
            if (isValid(nx, ny)) {
                if (grid[idx(nx, ny)] == step) {
                    ++numFree;
                    grid[idx(nx, ny)] = 0;
                }
            }
        }
        --cur;
    }

    private boolean isValid(int x, int y) {
        return x >= 0 && y >= 0 && x < n && y < m;
    }
}

