import java.util.*;
import java.io.*;

public class x111C {
    static int R, C, full, INF = 69;
    static int[][][] memo;
    static int[] bitCount;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        R = Integer.parseInt(st.nextToken());
        C = Integer.parseInt(st.nextToken());
        if (R > C) { int t = R; R = C; C = t; }
        full = (1 << R) - 1;
        int size = 1 << R;
        bitCount = new int[size];
        for (int i = 0; i < size; i++) bitCount[i] = Integer.bitCount(i);
        memo = new int[C+1][size][size];
        for (int i = 0; i <= C; i++) for (int j = 0; j < size; j++) Arrays.fill(memo[i][j], -1);
        int res = 0;
        for (int mask = 0; mask < size; mask++) {
            int val = dp(C, mask, 0);
            if (val == INF) continue;
            res = Math.max(res, R * C - (val + bitCount[mask]));
        }
        System.out.println(res);
    }

    static int dp(int c, int mask2, int mask3) {
        if (c == 0) {
            // dp[0][mask1][mask2] only valid when mask1==0
            return (mask2 == 0 ? 0 : INF);
        }
        if (memo[c][mask2][mask3] != -1) return memo[c][mask2][mask3];
        int best = INF;
        for (int mask1 = 0; mask1 <= full; mask1++) {
            int prev = dp(c-1, mask1, mask2);
            if (prev == INF) continue;
            // check validity
            int cover = ((mask2 << 1) & full) | (mask2 >> 1) | mask1 | mask3;
            int zeros = (~mask2) & full;
            if ((zeros & ~cover) == 0) {
                best = Math.min(best, prev + bitCount[mask1]);
            }
        }
        memo[c][mask2][mask3] = best;
        return best;
    }
}

