        if (R > C) { int t = R; R = C; C = t; }
        int full = (1 << R) - 1;
        int size = 1 << R;
        int INF = 69;
        int[][] prev = new int[size][size];
        int[][] cur = new int[size][size];
        for (int i = 0; i < size; i++) {
            Arrays.fill(prev[i], INF);
            Arrays.fill(cur[i], INF);
        }
        for (int mask = 0; mask < size; mask++) prev[0][mask] = 0;
        for (int c = 1; c <= C; c++) {
            for (int i = 0; i < size; i++) Arrays.fill(cur[i], INF);
            for (int mask2 = 0; mask2 < size; mask2++) {
                final int m2 = mask2;
                for (int mask3 = 0; mask3 < size; mask3++) {
                    final int m3 = mask3;
                    int best = IntStream.range(0, size)
                        .filter(m1 -> prev[m1][m2] != INF)
                        .filter(m1 -> {
