                        .map(m1 -> prev[m1][m2] + Integer.bitCount(m1))
                        .min()
                        .orElse(INF);
                    cur[m2][m3] = best;
                }
            }
            int[][] temp = prev; prev = cur; cur = temp;
        }
        int res = 0;
