            int t = R; R = C; C = t;
        }
        int size = 1 << R;
        int[] bitCount = new int[size];
        for (int i = 0; i < size; i++) bitCount[i] = Integer.bitCount(i);
        int INF = 69;
        int[][][] dp = new int[C+1][size][size];
        for (int i = 0; i <= C; i++)
            for (int mask = 0; mask < size; mask++)
                Arrays.fill(dp[i][mask], INF);
        for (int mask = 0; mask < size; mask++)
            dp[0][0][mask] = 0;
        for (int c = 1; c <= C; c++) {
            for (int mask1 = 0; mask1 < size; mask1++) {
                for (int mask2 = 0; mask2 < size; mask2++) {
                    for (int mask3 = 0; mask3 < size; mask3++) {
                        boolean works = true;
                        for (int b = 0; b < R; b++) {
                            if ((mask2 & (1 << b)) == 0) {
                                boolean covered = false;
                                if (b > 0 && (mask2 & (1 << (b-1))) != 0) covered = true;
                                else if (b + 1 < R && (mask2 & (1 << (b+1))) != 0) covered = true;
                                else if ((mask1 & (1 << b)) != 0) covered = true;
                                else if ((mask3 & (1 << b)) != 0) covered = true;
                                if (!covered) { works = false; break; }
                            }
                        }
                        if (works) {
                            int val = dp[c-1][mask1][mask2] + bitCount[mask1];
                            if (val < dp[c][mask2][mask3]) dp[c][mask2][mask3] = val;
                        }
                    }
                }
            }
        }
        int res = 0;
        for (int mask = 0; mask < size; mask++) {
            int val = dp[C][mask][0] + bitCount[mask];
            if (dp[C][mask][0] == INF) continue;
            res = Math.max(res, R * C - val);
        }
