public class x111C {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int r = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        if (r > c) { int t = r; r = c; c = t; }
        int sz = 1 << r;
        int INF = 69;
        int[] bc = new int[sz];
        for (int i = 0; i < sz; i++) bc[i] = Integer.bitCount(i);
        // 3D dp but using array of arrays
        int[][][] dp = new int[c+1][sz][sz];
        for (int i = 0; i <= c; i++)
            for (int j = 0; j < sz; j++)
                Arrays.fill(dp[i][j], INF);
        for (int mask = 0; mask < sz; mask++)
            dp[0][0][mask] = 0;
        // loop over columns
        for (int col = 1; col <= c; col++) {
            // iterate mask3 outer, then mask2, then mask1
            for (int m3 = 0; m3 < sz; m3++) {
                for (int m2 = 0; m2 < sz; m2++) {
                    for (int m1 = 0; m1 < sz; m1++) {
                        if (dp[col-1][m1][m2] == INF) continue;
                        boolean ok = true;
                        for (int bit = 0; bit < r; bit++) {
                            if ((m2 & (1 << bit)) == 0) {
                                boolean cov = false;
                                if (bit > 0 && (m2 & (1 << (bit-1))) != 0) cov = true;
                                else if (bit + 1 < r && (m2 & (1 << (bit+1))) != 0) cov = true;
                                else if ((m1 & (1 << bit)) != 0) cov = true;
                                else if ((m3 & (1 << bit)) != 0) cov = true;
                                if (!cov) { ok = false; break; }
                            }
                        }
                        if (ok) {
                            int val = dp[col-1][m1][m2] + bc[m1];
                            if (val < dp[col][m2][m3]) dp[col][m2][m3] = val;
                        }
                    }
                }
            }
        }
        int ans = 0;
        for (int mask = 0; mask < sz; mask++) {
            int val = dp[c][mask][0];
            if (val == INF) continue;
            ans = Math.max(ans, r * c - (val + bc[mask]));
        }
        System.out.println(ans);
    }
}

