                    continue;
                }
                int cnt = 0;
                for (int j = 0; j < m; j++)
                    if (bb[j] == 1) {
                        bb[j] = 2; cnt++;
                    }
                for (int j = 0; j < m; j++)
                    if (bb[j] == 0 && (aa[j] == 2 || j > 0 && bb[j-1] == 2 || j+1 < m && bb[j+1] == 2))
                        bb[j] = 1;
                nextState[a][b] = encode(bb, m);
                gain[a][b] = m - cnt;
            }
        }
        int[] dp = new int[p];
        int[] dq = new int[p];
        for (int j = 0; j < m; j++) aa[j] = 1;
        Arrays.fill(dp, -1);
        dp[encode(aa, m)] = 0;
        while (n-- > 0) {
            Arrays.fill(dq, -1);
            for (int a = 0; a < p; a++) {
                if (dp[a] < 0) continue;
                for (int b = 0; b < 1 << m; b++) {
                    int a_ = nextState[a][b];
                    if (a_ < 0) continue;
                    dq[a_] = Math.max(dq[a_], dp[a] + gain[a][b]);
                }
            }
            int[] tmp = dp; dp = dq; dq = tmp;
        }
        int ans = 0;
        for (int a = 0; a < p; a++) {
            if (dp[a] <= ans) continue;
            decode(aa, m, a);
            boolean bad = false;
            for (int j = 0; j < m; j++)
                if (aa[j] == 0) {
                    bad = true; break;
                }
            if (!bad) ans = dp[a];
        }
        println(ans);
    }
}

