        int BAD = 11111;
        int[][][] dp = new int[rows + 1][1 << cols][1 << cols];
        for (int i = 0; i <= rows; i++)
            for (int a = 0; a < (1 << cols); a++)
                Arrays.fill(dp[i][a], -1);
        int res = dfs(0, 0, 0, rows, cols, dp, BAD);
        System.out.println(cols * rows - res);
    }

    static int dfs(int row, int remabove, int squareabove, int rows, int cols, int[][][] dp, int BAD) {
        if (row == rows) return remabove == 0 ? 0 : BAD;
        if (dp[row][remabove][squareabove] != -1) return dp[row][remabove][squareabove];
        int best = BAD;
        for (int mask = 0; mask < (1 << cols); mask++) {
            boolean ok = true;
            for (int c = 0; c < cols; c++)
                if (((remabove >> c) & 1) == 1 && ((mask >> c) & 1) == 0) {
                    ok = false;
                    break;
                }
            if (ok) {
                int nextRem = 0;
                for (int c = 0; c < cols; c++) {
                    if (!contains(mask, c - 1) && !contains(mask, c) && !contains(mask, c + 1) && !contains(squareabove, c))
                        nextRem = add(nextRem, c);
                }
                best = Math.min(best, Integer.bitCount(mask) + dfs(row + 1, nextRem, mask, rows, cols, dp, BAD));
            }
        }
        dp[row][remabove][squareabove] = best;
        return best;
