        DataInputStream dis = new DataInputStream(System.in);
        int n = readInt(dis);
        int m = readInt(dis);
        int cols = Math.min(n, m);
        int rows = Math.max(n, m);
        int BAD = 11111;
        int[] dp = new int[1 << cols];
        java.util.Arrays.fill(dp, -1);
        int res = compute(0, 0, 0, rows, cols, dp, BAD);
        System.out.println(cols * rows - res);
    }

    static int readInt(DataInputStream dis) throws IOException {
        int c = dis.read();
        while (c <= ' ') c = dis.read();
        int sgn = 1;
        if (c == '-') { sgn = -1; c = dis.read(); }
        int res = 0;
        while (c > ' ') {
            res = res * 10 + (c - '0');
            c = dis.read();
        }
        return res * sgn;
    }

    static int compute(int row, int remabove, int squareabove, int rows, int cols, int[] dp, int BAD) {
        if (row == rows) return remabove == 0 ? 0 : BAD;
        if (dp[remabove] != -1) return dp[remabove];
        int best = BAD;
        for (int mask = 0; mask < (1 << cols); mask++) {
            boolean ok = true;
            for (int c = 0; c < cols; c++)
                if (((remabove >> c) & 1) == 1 && ((mask >> c) & 1) == 0) {
                    ok = false;
                    break;
                }
            if (ok) {
                int nextRem = 0;
                for (int c = 0; c < cols; c++) {
                    if (!contains(mask, c - 1) && !contains(mask, c) && !contains(mask, c + 1) && !contains(squareabove, c))
                        nextRem = add(nextRem, c);
                }
                best = Math.min(best, Integer.bitCount(mask) + compute(row + 1, nextRem, mask, rows, cols, dp, BAD));
            }
        }
        dp[remabove] = best;
        return best;
    }

    static boolean contains(int mem, int index) {
        if (index < 0) return false;
        return ((mem >> index) & 1) == 1;
    }

    static int add(int mem, int index) {
        if (((mem >> index) & 1) == 0) mem += (1 << index);
        return mem;
    }
}

