        int n = Integer.parseInt(st.nextToken());
        int mod = Integer.parseInt(st.nextToken());
        long[][] dp = new long[n][n * n + 5];
        dp[0][0] = 1;
        for (int i = 1; i < n; ++i) {
            for (int j = 0; j < dp[0].length; ++j) {
                long sum = 0;
                for (int cnt = 0; cnt <= i; ++cnt) {
                    if (j - cnt >= 0) {
                        sum += dp[i - 1][j - cnt];
                    }
                }
                dp[i][j] = (sum % mod + mod) % mod;
            }
        }
        long[][] sums = new long[dp.length][dp[0].length];
        for (int i = 0; i < dp.length; ++i) {
            long acc = 0;
            for (int j = 0; j < dp[0].length; ++j) {
                acc = (acc + dp[i][j]) % mod;
                sums[i][j] = (acc + mod) % mod;
            }
        }
        long[][] ncr = new long[501][501];
        ncr[0][0] = 1;
        for (int i = 1; i < ncr.length; ++i) {
            ncr[i][0] = 1;
            for (int j = 1; j < ncr[0].length; ++j) {
                ncr[i][j] = (ncr[i - 1][j] + ncr[i - 1][j - 1]) % mod;
                ncr[i][j] = (ncr[i][j] + mod) % mod;
            }
        }
        long res = 0;
        for (int i = n - 2; i >= 0; --i) {
            int cnt = n - i;
            int pre = n - cnt;
            long com = (ncr[n][pre] * factorial(pre, mod)) % mod;
            com = (com + mod) % mod;
            long sum = 0;
            for (int dif = 1; dif < cnt; ++dif) {
                for (int inv = dif; inv < dp[0].length; ++inv) {
                    if (dp[cnt - 1][inv] == 0) break;
                    if (inv - dif - 1 < 0) continue;
                    long x = dp[cnt - 2][inv];
                    long y = sums[cnt - 2][inv - dif - 1];
                    x = (x * y) % mod;
                    x = (x + mod) % mod;
                    sum = (sum + x * (cnt - dif)) % mod;
                }
            }
            res = (res + sum * com) % mod;
            res = (res + mod) % mod;
        }
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        out.println(res % mod);
        out.flush();
    }
    static long factorial(int n, int mod) {
        long f = 1;
        for (int i = 2; i <= n; ++i) f = (f * i) % mod;
        return f;
    }
}

