                if (ncr[i][j]==0) ncr[i][j] += mod;
            }
        }

        long res = 0;
        for (int i = 0; i <= n-2; i++) {
            int cnt = n - i;
            int pre = n - cnt;
            long com = (ncr[n][pre] * fact[pre]) % mod;
            if (com==0) com += mod;

            long[] last = dp[cnt-2];
            long[] sarr = sums[cnt-2];
            long sum = 0, total = 0, ssum = 0;
            for (int j = 2; j < dp[0].length; j++) {
                total = (total + sarr[j-2] * (cnt-1)) % mod;
                if (total==0) total += mod;
                sum = (sum + last[j] * total) % mod;
                if (sum==0) sum += mod;
                ssum = (ssum + sarr[j-2] - (j-cnt-1>=0? sarr[j-cnt-1] : 0) + mod) % mod;
                if (ssum==0) ssum += mod;
                total = (total - ssum + mod) % mod;
                if (total==0) total += mod;
            }
            res = (res + sum * com) % mod;
            if (res==0) res += mod;
        }
        out.println(res % mod);
        out.flush();
    }
}

