public class Main {
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;
        public FastReader() { br = new BufferedReader(new InputStreamReader(System.in)); }
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try { st = new StringTokenizer(br.readLine()); } catch (IOException e) {}
            }
            return st.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
    }

    static long modAdd(long a, long b, int mod) {
        long r = a + b;
        if (r >= mod) r -= mod;
        return r == 0 ? mod : r;
    }
    static long modSub(long a, long b, int mod) {
        long r = a - b;
        if (r < 0) r += mod;
        return r == 0 ? mod : r;
    }
    static long modMul(long a, long b, int mod) {
        long r = (a * b) % mod;
        return r == 0 ? mod : r;
    }

    public static void main(String[] args) {
        FastReader fr = new FastReader();
        PrintWriter out = new PrintWriter(System.out);
        int n = fr.nextInt();
        int mod = fr.nextInt();

        long[][] dp = new long[n][n*n+5];
        dp[0][0] = 1;
        for (int i = 1; i < n; i++) {
            long[] prev = dp[i-1];
            long[] cur = dp[i];
            for (int j = 0; j < cur.length; j++) {
                long s = 0;
                int max = Math.min(i, j);
                for (int c = 0; c <= max; c++) s += prev[j-c];
                cur[j] = s % mod;
                if (cur[j] == 0) cur[j] += mod;
            }
        }

        long[][] psum = new long[dp.length][dp[0].length];
        for (int i = 0; i < dp.length; i++) {
            long acc = 0;
            for (int j = 0; j < dp[0].length; j++) {
                acc = (acc + dp[i][j]) % mod;
                if (acc == 0) acc += mod;
                psum[i][j] = acc;
            }
        }

        long[] fact = new long[501*501];
        fact[0] = 1;
        for (int i = 1; i < fact.length; i++) fact[i] = fact[i-1] * i % mod;
        long[][] ncr = new long[501][501];
        ncr[0][0] = 1;
        for (int i = 1; i < 501; i++) {
            ncr[i][0] = 1;
            for (int j = 1; j < 501; j++) {
                ncr[i][j] = (ncr[i-1][j] + ncr[i-1][j-1]) % mod;
                if (ncr[i][j] == 0) ncr[i][j] += mod;
            }
        }

        long res = 0;
        for (int i = 0; i <= n-2; i++) {
            int cnt = n - i;
            int pre = n - cnt;
            long com = modMul(ncr[n][pre], fact[pre], mod);
            long[] last = dp[cnt-2];
            long[] ps = psum[cnt-2];
            long sum = 0, total = 0, sliding = 0;
            for (int j = 2; j < dp[0].length; j++) {
                total = modAdd(total, modMul(ps[j-2], cnt-1, mod), mod);
                sum = modAdd(sum, modMul(last[j], total, mod), mod);
                sliding = modAdd(sliding, ps[j-2], mod);
                if (j - cnt - 1 >= 0) sliding = modSub(sliding, ps[j-cnt-1], mod);
                total = modSub(total, sliding, mod);
            }
            res = modAdd(res, modMul(sum, com, mod), mod);
        }
        out.println(res % mod);
        out.flush();
    }
}

