    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        int n = fs.nextInt();
        int mod = fs.nextInt();

        int maxJ = n * n + 5;
        long[][] dp = new long[n][maxJ];
        dp[0][0] = 1;

        for (int i = 1; i < n; i++) {
            long[] prev = dp[i-1];
            long[] cur = dp[i];
            for (int j = 0; j < maxJ; j++) {
                long add = 0;
                for (int c = 0; c <= i && c <= j; c++) {
                    add += prev[j-c];
                }
                cur[j] = add % mod;
                if (cur[j] == 0) cur[j] += mod;
            }
        }

        long[][] prefix = new long[n][maxJ];
        for (int i = 0; i < n; i++) {
            long sum = 0;
            for (int j = 0; j < maxJ; j++) {
                sum = (sum + dp[i][j]) % mod;
                if (sum == 0) sum += mod;
                prefix[i][j] = sum;
            }
        }

        long[] fact = new long[501*501];
        fact[0] = 1;
        for (int i = 1; i < fact.length; i++) fact[i] = fact[i-1] * i % mod;
        long[][] comb = new long[501][501];
        comb[0][0] = 1;
        for (int i = 1; i < 501; i++) {
            comb[i][0] = 1;
            for (int j = 1; j < 501; j++) {
                comb[i][j] = (comb[i-1][j] + comb[i-1][j-1]) % mod;
                if (comb[i][j] == 0) comb[i][j] += mod;
            }
        }

        long ans = 0;
        for (int i = 0; i <= n-2; i++) {
            int k = n - i;          // cnt
            int p = n - k;          // pre
            long mult = (comb[n][p] * fact[p]) % mod;
            if (mult == 0) mult += mod;

            long[] last = dp[k-2];
            long[] pref = prefix[k-2];
            long cursum = 0, curtotal = 0, curSliding = 0;

            for (int j = 2; j < maxJ; j++) {
                curtotal = (curtotal + pref[j-2] * (k-1)) % mod;
                if (curtotal == 0) curtotal += mod;
                cursum = (cursum + last[j] * curtotal) % mod;
                if (cursum == 0) cursum += mod;

                curSliding = (curSliding + dp[k-2][j-2]) % mod;
                if (j - k - 1 >= 0) {
                    curSliding = (curSliding - dp[k-2][j-k-1] + mod) % mod;
                }
                if (curSliding == 0) curSliding += mod;

                curtotal = (curtotal - curSliding + mod) % mod;
                if (curtotal == 0) curtotal += mod;
            }
            ans = (ans + cursum * mult) % mod;
            if (ans == 0) ans += mod;
        }
        out.println(ans % mod);
        out.flush();
    }
}

