import java.util.ArrayList;
import java.util.Scanner;

public class e1542easy {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int mod = scanner.nextInt();
        solve(n, mod);
    }

    public static void solve(int n, int mod) {
        ArrayList<long[]> invList = new ArrayList<>();
        invList.add(new long[]{1});

        for (int i = 1; i < n; i++) {
            long[] prev = invList.get(i - 1);
            int size = i * (i + 1) / 2 + 1;
            long[] curr = new long[size];

            for (int j = 0; j < size; j++) {
                long sum = 0;
                int start = Math.min(j, i);
                for (int k = start; k >= 0; k--) {
                    int idx = j - k;
                    if (idx < prev.length) {
                        sum += prev[idx];
                        if (sum >= mod) sum -= mod;
                    }
                }
                curr[j] = sum;
            }
            invList.add(curr);
        }

        long[] perms = new long[n];
        perms[0] = 0;

        for (int i = 1; i < n; i++) {
            long c = (perms[i - 1] * (i + 1)) % mod;
            long[] inv = invList.get(i - 1);

            for (int j = 0; j < inv.length; j++) {
                for (int k = j + 2; k < inv.length; k++) {
                    long m = Math.min(k - j, i + 1);
                    long term = (inv[j] * inv[k]) % mod;
                    long factor = (m - 1) * (2 * i - (m - 2)) / 2;
                    c = (c + term * factor) % mod;
                }
            }
            perms[i] = c;
        }

        System.out.println(perms[n - 1]);
    }
}

