        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        int m = Integer.parseInt(parts[1]);
        int MOD = m;
        int[] fact = new int[n + 1];
        fact[0] = n;
        for (int i = 1; i < n; i++) fact[i] = (int)((fact[i - 1] * 1L * (n - i)) % MOD);
        int size = n * (n - 1) + 1;
        int[] dp = new int[size];
        int mid = (n * (n - 1)) / 2;
        dp[mid] = 1;
        int ans = 0;
        for (int i = n - 1; i >= 0; i--) {
            int c = n - 1 - i;
            int[] tmp = dp.clone();
            Arrays.fill(dp, 0);
            int lim = (c * (c - 1)) / 2;
            int cnt = 0;
            for (int cur = -c; cur < 0; cur++) {
                int pairs = c + cur + 1;
                for (int j = mid - cur + 1; j <= mid + lim; j++) {
                    cnt = (cnt + (int)((tmp[j] * 1L * pairs) % MOD)) % MOD;
                }
            }
            ans = (ans + (int)((cnt * 1L * (i == 0 ? 1 : fact[i - 1])) % MOD)) % MOD;
            for (int j = mid - lim; j <= mid + lim; j++) {
                for (int cur = -c; cur <= c; cur++) {
                    int pairs = c - Math.abs(cur) + 1;
                    int add = (int)((pairs * 1L * tmp[j]) % MOD);
                    dp[j + cur] = (dp[j + cur] + add) % MOD;
                }
            }
        }
