            int v = adj.size();
            int e = 0;
            for (int i = 0; i < v; i++) {
                e += adj.get(i).size();
            }
            e /= 2;

            // Iterative DFS using Stack
            int comps = 0;
            boolean[] was = new boolean[v];
            for (int i = 0; i < v; i++) {
                if (!was[i]) {
                    ++comps;
                    Stack<Integer> stack = new Stack<>();
                    stack.push(i);
                    was[i] = true;
                    while (!stack.isEmpty()) {
                        int cur = stack.pop();
                        for (int j : adj.get(cur)) {
                            if (!was[j]) {
                                was[j] = true;
                                stack.push(j);
                            }
                        }
                    }
                }
            }

            out.println(1 + comps + e - v);
        }

        private void getId(Point p, Map<Point, Integer> pointId, List<Set<Integer>> adj) {
            if (!pointId.containsKey(p)) {
                int sz = pointId.size();
                pointId.put(p, sz);
                adj.add(new HashSet<>());
