                circles[i].r = r;
            }

            // Use streams to collect intersection points
            Set<Point> all = IntStream.range(0, n).boxed()
                .flatMap(i -> IntStream.range(i + 1, n)
                    .mapToObj(j -> intersect(circles[i], circles[j]))
                    .filter(inter -> inter != null)
                    .flatMap(List::stream))
                .collect(Collectors.toCollection(TreeSet::new));

            Map<Point, Integer> pointId = new TreeMap<>();
