                    .mapToObj(j -> Math.PI * 2 * j / K)
                    .collect(Collectors.toCollection(TreeSet::new));
                all.stream()
                    .filter(p -> circles[I].contains(p))
                    .map(p -> {
                        double dx = p.x - circles[I].o.x;
                        double dy = p.y - circles[I].o.y;
                        double alpha = Math.atan2(dy, dx);
                        return alpha < 0 ? alpha + 2 * Math.PI : alpha;
                    })
                    .forEach(angleSet::add);
                Double[] as = angleSet.toArray(new Double[0]);
                Point dir = new Point(1, 0).scale(circles[I].r);
                // assign IDs using stream
                for (double angle : as) {
