            int v = adj.size();
            int e = adj.stream().mapToInt(Set::size).sum() / 2;

            boolean[] was = new boolean[v];
            int[] comps = {0};
            for (int i = 0; i < v; i++) {
                if (!was[i]) {
                    comps[0]++;
                    dfs(i, was, adj);
                }
            }

            out.println(1 + comps[0] + e - v);
        }

        private void dfs(int i, boolean[] was, List<Set<Integer>> adj) {
            was[i] = true;
            for (int j : adj.get(i)) {
                if (!was[j]) {
                    dfs(j, was, adj);
                }
            }
        }

        private List<Point> intersect(Circle c1, Circle c2) {
