    static class TaskC {
        final double eps = 1e-8;

        static class Point implements Comparable<Point> {
            double x, y;
            Point(double x, double y) { this.x = x; this.y = y; }
            Point add(Point o) { return new Point(x + o.x, y + o.y); }
            Point sub(Point o) { return new Point(x - o.x, y - o.y); }
            Point rotate(double alpha) {
                double c = Math.cos(alpha), s = Math.sin(alpha);
                return new Point(x * c - y * s, x * s + y * c);
            }
            Point norm() { double len = length(); return scale(1.0 / len); }
            Point scale(double f) { return new Point(f * x, f * y); }
            double length() { return Math.sqrt(x * x + y * y); }
            public String toString() { return String.format("%.6f %.6f", x, y); }
            public boolean equals(Object obj) {
                Point o = (Point) obj;
                return Math.abs(x - o.x) < eps && Math.abs(y - o.y) < eps;
            }
            public int compareTo(Point o) {
                if (Math.abs(x - o.x) > eps) return x < o.x ? -1 : 1;
                if (Math.abs(y - o.y) > eps) return y < o.y ? -1 : 1;
                return 0;
            }
        }

        static class Circle {
            Point o; double r;
            boolean contains(Point p) {
                double dist = p.sub(o).length();
                return Math.abs(dist - r) < eps;
            }
        }

        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            Circle[] circles = new Circle[n];
            for (int i = 0; i < n; i++) {
                int x = in.nextInt(), y = in.nextInt(), r = in.nextInt();
                circles[i] = new Circle();
                circles[i].o = new Point(x, y);
                circles[i].r = r;
            }

            Set<Point> all = new TreeSet<>();
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    List<Point> inter = intersect(circles[i], circles[j]);
                    if (inter == null) continue;
                    all.addAll(inter);
                }
            }

            Map<Point, Integer> pointId = new TreeMap<>();
            List<Set<Integer>> adj = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                // Compute angles: K equally spaced + intersection points
                double step = 2 * Math.PI / 100;
                TreeSet<Double> angleSet = new TreeSet<>();
                for (int k = 0; k < 100; k++) {
                    angleSet.add(k * step);
                }
                for (Point p : all) {
                    if (circles[i].contains(p)) {
                        double alpha = Math.atan2(p.y - circles[i].o.y, p.x - circles[i].o.x);
                        if (alpha < 0) alpha += 2 * Math.PI;
                        angleSet.add(alpha);
                    }
                }
                Double[] as = angleSet.toArray(new Double[0]);
                Point dir = new Point(circles[i].r, 0);  // equivalent to (1,0).scale(r)
                // combine ID assignment and edge addition in one loop, but need both passes separately
                for (double angle : as) {
                    Point p = circles[i].o.add(dir.rotate(angle));
                    if (!pointId.containsKey(p)) {
                        int sz = pointId.size();
                        pointId.put(p, sz);
                        adj.add(new HashSet<>());
                    }
                }
                for (int j = 0; j < as.length; j++) {
                    Point p = circles[i].o.add(dir.rotate(as[j]));
                    Point q = circles[i].o.add(dir.rotate(as[(j + 1) % as.length]));
