                    if (u != v) {
                        adj.get(u).add(v);
                        adj.get(v).add(u);
                    }
                }
            }

            int v = adj.size();
            int e = 0;
            for (Set<Integer> s : adj) e += s.size();
            e /= 2;

            // DFS using Deque (Stack)
            int comps = 0;
            boolean[] was = new boolean[v];
            Deque<Integer> stack = new ArrayDeque<>();
            for (int i = 0; i < v; i++) {
                if (!was[i]) {
                    comps++;
                    stack.push(i);
                    was[i] = true;
                    while (!stack.isEmpty()) {
                        int cur = stack.pop();
                        for (int nb : adj.get(cur)) {
                            if (!was[nb]) {
                                was[nb] = true;
                                stack.push(nb);
                            }
                        }
                    }
                }
            }

            out.println(1 + comps + e - v);
        }

        private List<Point> intersect(Circle c1, Circle c2) {
            double dx = c1.o.x - c2.o.x;
            double dy = c1.o.y - c2.o.y;
            double d = Math.sqrt(dx * dx + dy * dy);
            double cos = (c1.r * c1.r + d * d - c2.r * c2.r) / (2 * c1.r * d);
            if (cos < -1 - eps) return null;
            if (cos < -1) cos = -1;
            if (cos > 1 + eps) return null;
            if (cos > 1) cos = 1;
            List<Point> res = new ArrayList<>();
            double alpha = Math.acos(cos);
            Point dir = c2.o.sub(c1.o).norm();
            res.add(c1.o.add(dir.scale(c1.r).rotate(+alpha)));
            res.add(c1.o.add(dir.scale(c1.r).rotate(-alpha)));
