            for (int i0 = 0; i0 <= cnt[0]; i0++) {
                for (int i1 = 0; i1 <= cnt[1]; i1++) {
                    for (int i2 = 0; i2 <= cnt[2]; i2++) {
                        for (int last = 0; last < 2; last++) {
                            int cur = dp[last][i0][i1][i2];
                            if (i0 < cnt[0] && last == 0) {
                                int swaps = 0;
                                int p0 = pos[0][i0];
                                for (int i = i1; i < cnt[1] && pos[1][i] < p0; i++) swaps++;
                                for (int i = i2; i < cnt[2] && pos[2][i] < p0; i++) swaps++;
                                dp[0][i0 + 1][i1][i2] = Math.min(dp[0][i0 + 1][i1][i2], cur + swaps);
                            }
                            if (i1 < cnt[1]) {
                                int swaps = 0;
                                int p1 = pos[1][i1];
                                for (int i = i0; i < cnt[0] && pos[0][i] < p1; i++) swaps++;
                                for (int i = i2; i < cnt[2] && pos[2][i] < p1; i++) swaps++;
                                dp[1][i0][i1 + 1][i2] = Math.min(dp[1][i0][i1 + 1][i2], cur + swaps);
                            }
                            if (i2 < cnt[2]) {
                                int swaps = 0;
                                int p2 = pos[2][i2];
                                for (int i = i0; i < cnt[0] && pos[0][i] < p2; i++) swaps++;
                                for (int i = i1; i < cnt[1] && pos[1][i] < p2; i++) swaps++;
                                dp[0][i0][i1][i2 + 1] = Math.min(dp[0][i0][i1][i2 + 1], cur + swaps);
                            }
                        }
                    }
