    static long power(long x, long y, long m) {
        if (y == 0) return 1;
        long p = power(x, y / 2, m) % m;
        p = (p * p) % m;
        if (y % 2 == 0) return p;
        else return (x * p) % m;
    }

    static class Combinations {
        private long[] z;
        private long[] z1;
        private long[] z2;
        private long mod;
        public Combinations(long N, long mod) {
            this.mod = mod;
            z = new long[(int)N+1];
            z1 = new long[(int)N+1];
            z[0] = 1;
            for(int i = 1; i <= N; i++) z[i] = (z[i-1]*i)%mod;
            z2 = new long[(int)N+1];
            z2[0] = z2[1] = 1;
            for (int i = 2; i <= N; i++)
                z2[i] = z2[(int)(mod % i)] * (mod - mod / i) % mod;
            z1[0] = z1[1] = 1;
            for (int i = 2; i <= N; i++)
                z1[i] = (z2[i] * z1[i - 1]) % mod;
        }
        long fac(long n) { return z[(int)n]; }
        long invrsNum(long n) { return z2[(int)n]; }
        long invrsFac(long n) { return invrsFac((int)n); }
        long ncr(long N, long R) {
            if(R<0 || R>N) return 0;
            long ans = ((z[(int)N] * z1[(int)R]) % mod * z1[(int)(N - R)]) % mod;
            return ans;
        }
    }

    static class DisjointUnionSets {
        int[] rank, parent;
        int n;
        public DisjointUnionSets(int n) {
            rank = new int[n];
            parent = new int[n];
            this.n = n;
            makeSet();
        }
        void makeSet() { for (int i = 0; i < n; i++) parent[i] = i; }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        void union(int x, int y) {
            int xRoot = find(x), yRoot = find(y);
            if (xRoot == yRoot) return;
            if (rank[xRoot] < rank[yRoot]) parent[xRoot] = yRoot;
            else if (rank[yRoot] < rank[xRoot]) parent[yRoot] = xRoot;
            else { parent[yRoot] = xRoot; rank[xRoot] = rank[xRoot] + 1; }
        }
    }

