            else sb.append("0\n");
        } else if (arr[0] == '0') {
            sb.append("0\n");
        } else {
            boolean hasX = false;
            for (char c : arr) if (c == 'X') { hasX = true; break; }
            long total = 0;
            boolean[] flag = new boolean[1];
            if (hasX) {
                for (int x = 0; x < 10; x++) {
                    char[] tmp = arr.clone();
                    if (tmp[0] == 'X' && x == 0) continue;
                    for (int i = 0; i < n; i++) if (tmp[i] == 'X') tmp[i] = (char)(x + '0');
                    flag[0] = false;
                    long back = back(tmp, flag);
                    long pre = 1;
                    for (int j = 0; j < n - 2; j++) {
                        if (tmp[j] == '_') pre *= (j == 0 ? 9 : 10);
                    }
                    total += pre * back;
                    if (pre == 1 && flag[0]) total--;
                }
            } else {
                flag[0] = false;
                long back = back(arr, flag);
                long pre = 1;
                for (int j = 0; j < n - 2; j++) {
                    if (arr[j] == '_') pre *= (j == 0 ? 9 : 10);
                }
                total += pre * back;
                if (pre == 1 && flag[0]) total--;
            }
            sb.append(total).append('\n');
        }
        System.out.print(sb);
    }

    static long back(char[] arr, boolean[] flag) {
        int n = arr.length;
        boolean lastKnown = arr[n-1] != '_';
        boolean secondLastKnown = arr[n-2] != '_';
        if (lastKnown && secondLastKnown) {
            long num = Long.parseLong("" + arr[n-2] + arr[n-1]);
            if (num % 25 == 0) {
                if (num == 0) flag[0] = true;
                return 1;
            } else return 0;
        } else if (!lastKnown && !secondLastKnown) {
            flag[0] = true;
            return 4;
        } else if (!lastKnown) {
            char c = arr[n-2];
            if (c == '2' || c == '0' || c == '7' || c == '5') {
                if (c == '0') flag[0] = true;
                return 1;
            } else return 0;
        } else {
            char c = arr[n-1];
            if (c == '0' || c == '5') {
                if (c == '0') flag[0] = true;
                return 2;
            } else return 0;
        }
    }

