import java.io.*;
import java.util.*;

public class Main {
    private static Scanner sc = new Scanner(System.in);
    private static StringBuilder out = new StringBuilder();

    public static void main(String[] args) {
        int tc = 1;
        while (tc-- > 0) solve();
        System.out.print(out);
    }

    static void solve() {
        String s = sc.next();
        char[] a = s.toCharArray();
        int n = a.length;
        if (n == 1) {
            out.append((a[0] == '0' || a[0] == '_' || a[0] == 'X') ? "1\n" : "0\n");
            return;
        }
        if (a[0] == '0') { out.append("0\n"); return; }
        boolean hasX = false;
        for (char c : a) if (c == 'X') { hasX = true; break; }
        long ans = 0;
        java.util.function.LongUnaryOperator calc = (rpl) -> {
            char[] arr = a.clone();
            for (int i = 0; i < n; i++) if (arr[i] == 'X') arr[i] = (char)('0' + rpl);
            return count(arr);
        };
        if (hasX) {
            for (int x = 0; x < 10; x++) {
                if (a[0] == 'X' && x == 0) continue;
                ans += calc.applyAsLong(x);
            }
        } else {
            ans = calc.applyAsLong(0);
        }
        out.append(ans).append('\n');
    }

    static long count(char[] arr) {
        int n = arr.length;
        long pre = 1;
        for (int j = 0; j < n - 2; j++) {
            if (arr[j] == '_') pre *= (j == 0 ? 9 : 10);
        }
        long back = back(arr);
        long res = pre * back;
        if (pre == 1 && flag) res--;
        flag = false;
        return res;
    }

    static boolean flag = false;

    static long back(char[] arr) {
        int n = arr.length;
        boolean a = arr[n-2] != '_';
        boolean b = arr[n-1] != '_';
        if (a && b) {
