            if (num % 25 == 0) {
                if (num == 0) flag = true;
                return 1;
            } else return 0;
        } else if (!a && !b) {
            flag = true;
            return 4;
        } else if (!b) {
            char c = arr[n-2];
            if (c == '2' || c == '0' || c == '7' || c == '5') {
                if (c == '0') flag = true;
                return 1;
            } else return 0;
        } else {
            char c = arr[n-1];
            if (c == '0' || c == '5') {
                if (c == '0') flag = true;
                return 2;
            } else return 0;
        }
    }
}

