public class Main {
    private static final int BUF = 2048;
    private static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    private static StringBuilder sb = new StringBuilder();

    public static void main(String[] args) throws IOException {
        char[] arr = nextToken().toCharArray();
        int n = arr.length;
        if (n == 1) {
            char c = arr[0];
            sb.append(c == '0' || c == '_' || c == 'X' ? "1\n" : "0\n");
        } else if (arr[0] == '0') {
            sb.append("0\n");
        } else {
            boolean hasX = false;
            for (char c : arr) if (c == 'X') hasX = true;
            long total = 0;
            if (hasX) {
                for (int x = 0; x < 10; x++) {
                    if (arr[0] == 'X' && x == 0) continue;
                    char[] tmp = new char[n];
                    for (int i = 0; i < n; i++) tmp[i] = arr[i];
                    for (int i = 0; i < n; i++) if (tmp[i] == 'X') tmp[i] = (char)('0' + x);
                    total += compute(tmp);
                }
            } else {
                total = compute(arr);
            }
            sb.append(total).append('\n');
        }
        System.out.print(sb);
    }

    static long compute(char[] arr) {
        int n = arr.length;
        boolean[] flag = new boolean[1];
        long back = back(arr, flag);
        long pre = 1;
        for (int i = 0; i < n - 2; i++) {
            if (arr[i] == '_') pre *= (i == 0 ? 9 : 10);
        }
        long res = pre * back;
        if (pre == 1 && flag[0]) res--;
        return res;
    }

    static long back(char[] arr, boolean[] flag) {
        int n = arr.length;
        char a = arr[n-2], b = arr[n-1];
        boolean knownA = a != '_', knownB = b != '_';
        if (knownA && knownB) {
            long num = (a - '0') * 10L + (b - '0');
            if (num % 25 == 0) {
                if (num == 0) flag[0] = true;
                return 1;
            } else return 0;
        }
        if (!knownA && !knownB) { flag[0] = true; return 4; }
        if (!knownA) {
            if (b == '0' || b == '5') {
                if (b == '0') flag[0] = true;
                return 2;
            } else return 0;
        } else {
            if (a == '2' || a == '0' || a == '7' || a == '5') {
                if (a == '0') flag[0] = true;
                return 1;
            } else return 0;
        }
    }

    static char[] nextToken() throws IOException {
        int c;
        while ((c = br.read()) != -1 && (c == '\n' || c == ' ' || c == '\r'));
        if (c == -1) return null;
        StringBuilder sb = new StringBuilder();
        sb.append((char) c);
        while ((c = br.read()) != -1 && !(c == '\n' || c == ' ' || c == '\r')) sb.append((char) c);
        return sb.toString().toCharArray();
    }
}

