    public static void main(String[] args) throws IOException {
        new Main().solve();
        out.flush();
    }

    void solve() throws IOException {
        char[] arr = in.readLine().toCharArray();
        int n = arr.length;
        if (n == 1) {
            out.println((arr[0] == '0' || arr[0] == '_' || arr[0] == 'X') ? 1 : 0);
            return;
        }
        if (arr[0] == '0') {
            out.println(0);
            return;
        }
        boolean hasX = false;
        for (char c : arr) if (c == 'X') { hasX = true; break; }
        long result = 0;
        if (hasX) {
            for (int x = 0; x < 10; x++) {
                if (arr[0] == 'X' && x == 0) continue;
                char[] clone = arr.clone();
                for (int i = 0; i < n; i++) if (clone[i] == 'X') clone[i] = (char)('0' + x);
                result += count(clone);
            }
        } else {
            result = count(arr);
        }
        out.println(result);
    }

    long count(char[] a) {
        int n = a.length;
        long prefix = 1;
        for (int i = 0; i < n - 2; i++) {
            if (a[i] == '_') prefix *= (i == 0 ? 9 : 10);
        }
        long suffix = countSuffix(a);
        long total = prefix * suffix;
        if (prefix == 1 && sufFlag) total--;
        return total;
    }

    boolean sufFlag = false;

    long countSuffix(char[] a) {
        int n = a.length;
        boolean last = a[n-1] != '_';
        boolean secondLast = a[n-2] != '_';
        if (last && secondLast) {
            long v = (a[n-2] - '0') * 10L + (a[n-1] - '0');
            if (v % 25 == 0) {
                if (v == 0) sufFlag = true;
                return 1;
            }
            return 0;
        }
        if (!last && !secondLast) {
            sufFlag = true;
            return 4;
        }
        if (!last) {
            char c = a[n-2];
            if (c == '2' || c == '0' || c == '7' || c == '5') {
                if (c == '0') sufFlag = true;
                return 1;
            }
            return 0;
        } else {
            char c = a[n-1];
            if (c == '0' || c == '5') {
                if (c == '0') sufFlag = true;
                return 2;
            }
            return 0;
        }
    }
}

