public class div25 {
    public static char[] str;
    public static int S;

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        str = in.readLine().toCharArray();
        S = str.length;
        int ans = 0;
        if (S == 1) {
            if (str[0] == 'X' || str[0] == '_' || Integer.parseInt(String.valueOf(str[0])) == 0) ans = 1;
        } else {
            ans = countAll();
        }
        System.out.println(ans);
    }

    static int countAll() {
        int total = 0;
        int[][] ends = {{2,5},{5,0},{7,5},{0,0}};
        for (int[] end : ends) {
            if (S == 2 && end[0] == 0) continue;
            int ways = countEnding(end[0], end[1]);
            total += ways;
        }
        return total;
    }

    static int countEnding(int end1, int end2) {
        int X_val = -1;
        if (str[S-2] == 'X') X_val = end1;
        else if (str[S-2] != '_' && digitAt(S-2) != end1) return 0;
        if (str[S-1] == 'X') {
            if (X_val != -1 && end2 != X_val) return 0;
            X_val = end2;
        } else if (str[S-1] != '_' && digitAt(S-1) != end2) return 0;
        int ways = 1;
        for (int i = 0; i < S-2; i++) {
            if (i == 0) {
                if (str[i] == 'X' && X_val == 0) return 0;
                if (digitAt(0) == 0) return 0;
            }
            if (str[i] == '_') {
                ways *= (i == 0 ? 9 : 10);
            }
            if (str[i] == 'X') {
                if (X_val == -1) {
                    X_val = 10;
                    ways *= (i == 0 ? 9 : 10);
                } // else already fixed, no multiplication
            }
        }
        return ways;
    }

    static int digitAt(int pos) {
        char c = str[pos];
        if (c == '_' || c == 'X') return -1;
        return c - '0';
    }
}

