    static int processSuffix(String suffix, char[] sOG, int n) {
        char[] s = sOG.clone();
        char last = suffix.charAt(1);
        char secondLast = suffix.charAt(0);
        boolean shit = (s[n - 1] != '_' && s[n - 1] != 'X' && s[n - 1] != last);
        shit |= (s[n - 2] != '_' && s[n - 2] != 'X' && s[n - 2] != secondLast);
        if (suffix.equals("00")) {
            // no extra condition
        } else {
            shit |= (s[n - 1] == 'X' && s[n - 2] == 'X');
        }

        if (shit) return 0;

        if (s[n - 1] == 'X') {
            for (int i = 0; i < n; i++)
                if (s[i] == 'X')
                    s[i] = last;
        } else if (s[n - 2] == 'X') {
            for (int i = 0; i < n; i++)
                if (s[i] == 'X')
                    s[i] = secondLast;
        }

        s[n - 1] = last;
        s[n - 2] = secondLast;

        int count = check(suffix.toCharArray(), s);
        for (int num = 0; num < 1e6; num++) {
            char[] tgt = (Integer.toString(num) + suffix).toCharArray();
            count += check(tgt, s);
        }
        return count;
    }

    static int check(char[] tgt, char[] src) {
        int n = tgt.length;
        if (src.length != n) return 0;

        char xDig = 0;
        for (int i = 0; i < n; i++)
            if (src[i] == 'X') {
                if (xDig == 0) {
                    xDig = tgt[i];
                } else {
                    if (tgt[i] != xDig) return 0;
                }
            }

        if (tgt[0] == '0') return 0;

        for (int i = 0; i < n; i++)
            if (src[i] != '_' && src[i] != 'X' && tgt[i] != src[i]) return 0;

        return 1;
    }

