public class P1575D {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);
        String s = sc.next();
        StringBuilder sb = new StringBuilder(s);
        int ans = 0;
        int n = sb.length();
        if (n == 1) {
            char c = sb.charAt(0);
            if (c == '0' || c == '_' || c == 'X') ans = 1;
        } else {
            if (!(sb.charAt(n-1) == 'X' && sb.charAt(n-2) == 'X')) {
                if (canPut(sb, n-1, '5') && canPut(sb, n-2, '2')) {
                    StringBuilder copy = new StringBuilder(sb);
                    put(copy, n-1, '5');
                    put(copy, n-2, '2');
                    ans += possible(copy);
                }
                if (canPut(sb, n-1, '0') && canPut(sb, n-2, '5')) {
                    StringBuilder copy = new StringBuilder(sb);
                    put(copy, n-1, '0');
                    put(copy, n-2, '5');
                    ans += possible(copy);
                }
                if (canPut(sb, n-1, '5') && canPut(sb, n-2, '7')) {
                    StringBuilder copy = new StringBuilder(sb);
                    put(copy, n-1, '5');
                    put(copy, n-2, '7');
                    ans += possible(copy);
                }
            }
            if (sb.charAt(n-1) == 'X' && sb.charAt(n-2) == 'X') {
                StringBuilder copy = new StringBuilder(sb);
                put(copy, n-1, '0');
                ans += possible(copy);
            } else if (canPut(sb, n-1, '0') && canPut(sb, n-2, '0')) {
                StringBuilder copy = new StringBuilder(sb);
                put(copy, n-1, '0');
                put(copy, n-2, '0');
                ans += possible(copy);
            }
        }
        writer.println(ans);
        writer.flush();
    }

    static boolean canPut(StringBuilder sb, int p, char d) {
        char c = sb.charAt(p);
        return c == 'X' || c == '_' || c == d;
    }

    static void put(StringBuilder sb, int p, char d) {
        if (sb.charAt(p) == 'X') {
            replace(sb, d);
        } else {
            sb.setCharAt(p, d);
        }
    }

    static void replace(StringBuilder sb, char d) {
        for (int i = 0; i < sb.length(); i++) {
            if (sb.charAt(i) == 'X') {
                sb.setCharAt(i, d);
            }
        }
    }

    static int possible(StringBuilder sb) {
        int p = 1;
        if (sb.charAt(0) == '0') return 0;
        if (sb.charAt(0) == '_') p *= 9;
        else if (sb.charAt(0) == 'X') {
            p *= 9;
            replace(sb, '1');
        }
        for (int i = 1; i < sb.length(); i++) {
            char c = sb.charAt(i);
            if (c == '_') p *= 10;
            else if (c == 'X') {
                p *= 10;
                replace(sb, '1');
            }
        }
        return p;
    }
}

