            if (c == '_') {
                if (i == 0) res *= 9;
                else res *= 10;
            } else if (c == 'X') {
                if (i == firstX) {
                    if (i == 0) res *= 9;
                    else res *= 10;
                }
            } else {
                if (i == 0 && c == '0') return 0;
            }
        }
        return res;
    }

    private static class MyScanner {
        private BufferedReader reader;
        private StringTokenizer st;

        public MyScanner(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        private String nextToken() throws IOException {
            while(st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(reader.readLine());
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }
    }
}

import java.util.Scanner;
import java.io.PrintWriter;

public class P1575D {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);
        String s = sc.next();
        int n = s.length();
        int ans = 0;
        if (n == 1) {
            char c = s.charAt(0);
            if (c == '0' || c == '_' || c == 'X') ans = 1;
        } else {
            char[] arr = s.toCharArray();
            if (!(arr[n-1] == 'X' && arr[n-2] == 'X')) {
                if (canPut(arr, n-1, '5') && canPut(arr, n-2, '2')) {
                    char[] copy = arr.clone();
                    put(copy, n-1, '5');
                    put(copy, n-2, '2');
                    ans += countRec(copy);
                }
                if (canPut(arr, n-1, '0') && canPut(arr, n-2, '5')) {
                    char[] copy = arr.clone();
                    put(copy, n-1, '0');
                    put(copy, n-2, '5');
                    ans += countRec(copy);
                }
                if (canPut(arr, n-1, '5') && canPut(arr, n-2, '7')) {
                    char[] copy = arr.clone();
                    put(copy, n-1, '5');
                    put(copy, n-2, '7');
                    ans += countRec(copy);
                }
            }
            if (arr[n-1] == 'X' && arr[n-2] == 'X') {
                char[] copy = arr.clone();
                put(copy, n-1, '0');
                ans += countRec(copy);
            } else if (canPut(arr, n-1, '0') && canPut(arr, n-2, '0')) {
                char[] copy = arr.clone();
                put(copy, n-1, '0');
                put(copy, n-2, '0');
                ans += countRec(copy);
            }
        }
        writer.println(ans);
        writer.flush();
    }

    static boolean canPut(char[] s, int p, char d) {
        char c = s[p];
        return c == 'X' || c == '_' || c == d;
    }

    static void put(char[] s, int p, char d) {
        if (s[p] == 'X') {
            replace(s, d);
        } else {
            s[p] = d;
        }
    }

    static void replace(char[] s, char d) {
        for (int i = 0; i < s.length; i++) {
            if (s[i] == 'X') s[i] = d;
        }
    }

    static int countRec(char[] s) {
        return countRecHelper(s, 0, -1);
    }

    static int countRecHelper(char[] s, int idx, int xDigit) {
        if (idx == s.length) {
            int n = s.length;
            char last1 = s[n-1];
            char last2 = s[n-2];
            if (last2 == '0' && last1 == '0') return 1;
            if (last2 == '2' && last1 == '5') return 1;
            if (last2 == '5' && last1 == '0') return 1;
            if (last2 == '7' && last1 == '5') return 1;
            return 0;
        }
        char c = s[idx];
        if (c != '_' && c != 'X') {
            if (idx == 0 && c == '0') return 0;
            return countRecHelper(s, idx+1, xDigit);
        }
        int total = 0;
        if (c == '_') {
            int start = (idx == 0) ? 1 : 0;
            for (int d = start; d <= 9; d++) {
                s[idx] = (char)('0' + d);
                total += countRecHelper(s, idx+1, xDigit);
            }
            s[idx] = '_';
        } else {
            if (xDigit != -1) {
                s[idx] = (char)('0' + xDigit);
                total += countRecHelper(s, idx+1, xDigit);
                s[idx] = 'X';
            } else {
                int start = (idx == 0) ? 1 : 0;
                for (int d = start; d <= 9; d++) {
                    s[idx] = (char)('0' + d);
                    total += countRecHelper(s, idx+1, d);
                }
                s[idx] = 'X';
            }
        }
        return total;
    }
}

