        while (T-- > 0) {
            if (s.length() == 1) {
                char c = s.charAt(0);
                out.println(c == '0' || c == '_' || c == 'X' ? 1 : 0);
                s = br.readLine(); // read next if multiple lines? But original reads one token.
                // Actually original only reads one token because T=1. So we can break.
                break;
            } else {
                boolean hasX = s.chars().anyMatch(ch -> ch == 'X');
                if (!hasX) {
                    out.println(count(s));
                } else {
                    int sum = IntStream.range(0, 10)
                            .map(d -> count(s.replace('X', (char) ('0' + d))))
                            .sum();
                    out.println(sum);
                }
                s = br.readLine(); // not needed as T=1
            }
        }
        out.close();
    }

    static int count(String s) {
        int n = s.length();
        int p = s.charAt(0) == '0' ? 0 : 1;
        for (int i = 0; i < n - 2; i++) {
            if (s.charAt(i) == '_') {
                p *= (i == 0 ? 9 : 10);
            }
        }
        String suffix = s.substring(n - 2);
        int p1;
        if (suffix.equals("__")) {
            p1 = n == 2 ? 3 : 4;
        } else if (suffix.charAt(1) == '_') {
            char c = suffix.charAt(0);
            p1 = (c == '0' || c == '2' || c == '5' || c == '7') ? 1 : 0;
        } else if (suffix.charAt(0) == '_') {
            char last = suffix.charAt(1);
            if (last == '0') {
                p1 = n == 2 ? 1 : 2;
            } else if (last == '5') {
                p1 = 2;
            } else {
                p1 = 0;
            }
        } else {
            int val = Integer.parseInt(suffix);
            p1 = val % 25 == 0 ? 1 : 0;
        }
        return p * p1;
    }
}

