public class Main {
    public static void main(String[] args) {
        FastReader input = new FastReader();
        PrintWriter out = new PrintWriter(System.out);
        int T = 1;
        while (T-- > 0) {
            String s = input.next();
            out.println(compute(s));
        }
        out.close();
    }

    static int compute(String s) {
        int n = s.length();
        if (n == 1) {
            char c = s.charAt(0);
            return (c == '0' || c == '_' || c == 'X') ? 1 : 0;
        }
        boolean hasX = false;
        for (int i = 0; i < n; i++) if (s.charAt(i) == 'X') { hasX = true; break; }
        if (!hasX) {
            return ways(s);
        } else {
            int total = 0;
            for (int digit = 0; digit <= 9; digit++) {
                char[] arr = s.toCharArray();
                for (int i = 0; i < n; i++) if (arr[i] == 'X') arr[i] = (char)('0' + digit);
                total += ways(new String(arr));
            }
            return total;
        }
    }

    static int ways(String s) {
        int n = s.length();
        int lead = s.charAt(0) == '0' ? 0 : 1;
        for (int i = 0; i < n - 2; i++) {
            if (s.charAt(i) == '_') {
                lead *= (i == 0) ? 9 : 10;
            }
        }
        int tail = 0;
        char c1 = s.charAt(n - 2);
        char c2 = s.charAt(n - 1);
        if (c1 == '_' && c2 == '_') {
            tail = (n == 2) ? 3 : 4;
        } else if (c2 == '_') {
            if (c1 == '0' || c1 == '2' || c1 == '5' || c1 == '7') tail = 1;
        } else if (c1 == '_') {
            if (c2 == '0') {
                tail = (n == 2) ? 1 : 2;
            } else if (c2 == '5') {
                tail = 2;
            }
        } else {
            int val = Integer.parseInt(s.substring(n - 2));
            if (val % 25 == 0) tail = 1;
        }
        return lead * tail;
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;
        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }
    }
}

