public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        PrintWriter pw = new PrintWriter(System.out);
        int T = 1;
        while (T-- > 0) {
            pw.println(process(s));
        }
        pw.close();
    }

    static int process(String s) {
        int n = s.length();
        if (n == 1) {
            char c = s.charAt(0);
            return (c == '0' || c == '_' || c == 'X') ? 1 : 0;
        }
        boolean hasX = s.indexOf('X') >= 0;
        if (!hasX) {
            return ways(s);
        } else {
            int total = 0;
            StringBuilder sb = new StringBuilder(s);
            for (int d = 0; d < 10; d++) {
                for (int i = 0; i < n; i++) {
                    if (sb.charAt(i) == 'X') sb.setCharAt(i, (char) ('0' + d));
                }
                total += ways(sb.toString());
                // restore X for next iteration
                for (int i = 0; i < n; i++) {
                    if (s.charAt(i) == 'X') sb.setCharAt(i, 'X');
                }
            }
            return total;
        }
    }

    static int ways(String s) {
        int n = s.length();
        int p = s.charAt(0) == '0' ? 0 : 1;
        for (int i = 0; i < n - 2; i++) {
            if (s.charAt(i) == '_') {
                p *= (i == 0 ? 9 : 10);
            }
        }
        int p1;
        char last = s.charAt(n - 1);
        char seclast = s.charAt(n - 2);
        if (last == '_' && seclast == '_') p1 = n == 2 ? 3 : 4;
        else if (last == '_') p1 = "0257".indexOf(seclast) >= 0 ? 1 : 0;
        else if (seclast == '_') {
            if (last == '0') p1 = n == 2 ? 1 : 2;
            else if (last == '5') p1 = 2;
            else p1 = 0;
        } else {
            p1 = Integer.parseInt(s.substring(n - 2)) % 25 == 0 ? 1 : 0;
        }
        return p * p1;
    }
}

