        }
        char c0 = v.charAt(0);
        char c1 = v.charAt(1);
        if (c0 != 'X' && c1 != 'X') {
            if (ok) {
                if (s.charAt(0) == 'X') {
                    toti *= 9L;
                } else {
                    toti *= 10L;
                }
            }
        }
        toti *= (long) ways;
        return toti;
    }
}

import java.io.*;

public final class Solution {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));

    public static void main(String[] args) throws IOException {
        String s = br.readLine();
        int n = s.length();
        if ((s.charAt(0) == '0' || s.charAt(0) == '_' || s.charAt(0) == 'X') && n == 1) {
            bw.write("1\n");
            bw.flush();
        } else if (n == 1 || s.charAt(0) == '0') {
            bw.write("0\n");
            bw.flush();
        } else {
            String[] digits = {"25", "50", "75", "00"};
            String[] arr1 = {"__", "_X", "X_", "XX"};
            int[] way = {4, 4, 4, 1};
            if (s.charAt(0) == 'X') { way[1] = 2; way[2] = 3; }
            if (n == 2) { way[0] = 3; way[1] = 3; }
            int ways = 0;
            String v = s.substring(n - 2, n);
            char c0 = v.charAt(0);
            char c1 = v.charAt(1);
            ways = evaluateWays(v, c0, c1, digits, arr1, way, s);
            if (ways == 0) {
                bw.write("0\n");
                bw.flush();
                return;
            }
            boolean ok = false;
            long toti = 1L;
            for (int i = 0; i < n - 2; i++) {
                char ch = s.charAt(i);
                if (ch == 'X') ok = true;
                if (ch == '_') toti *= (i == 0) ? 9L : 10L;
            }
            if (c0 != 'X' && c1 != 'X' && ok) {
                toti *= (s.charAt(0) == 'X') ? 9L : 10L;
            }
            toti *= ways;
            bw.write(Long.toString(toti) + "\n");
            bw.flush();
        }
    }

    static int evaluateWays(String v, char c0, char c1, String[] digits, String[] arr1, int[] way, String s) {
        int ways = 0;
        for (int i = 0; i < 4; i++) {
            if (v.equals(digits[i])) { ways = 1; }
        }
        if (c0 == '_' || c0 == 'X') {
            ways = 2;
            if (c1 == '0' && s.charAt(0) == 'X') ways = 1;
        } else if (c1 == '_' || c1 == 'X') {
            ways = 1;
        }
        for (int i = 0; i < 4; i++) {
            if (v.equals(arr1[i])) { ways = way[i]; }
        }
        if (v.equals("XX") && s.charAt(0) == 'X') ways = 0;
        if (c0 != '2' && c0 != '5' && c0 != '7' && c0 != '0' && c0 != 'X' && c0 != '_') ways = 0;
        if (c1 != '0' && c1 != '5' && c1 != 'X' && c1 != '_') ways = 0;
        return ways;
    }
}

