public class E {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        sc.close();
        int l = s.length();
        if (l < 2) {
            System.out.println(handleLengthOne(s));
            System.exit(0);
        } else if (l == 2) {
            System.out.println(handleLengthTwo(s));
            System.exit(0);
        } else {
            System.out.println(handleLonger(s, l));
        }
    }

    private static int handleLengthOne(String s) {
        return (s.equals("0") || s.equals("_") || s.equals("X")) ? 1 : 0;
    }

    private static int handleLengthTwo(String s) {
        int count = 0;
        for (int i = 10; i <= 95; i += 5) {
            if (i % 25 != 0) continue;
            String str = Integer.toString(i);
            char c0 = s.charAt(0), c1 = s.charAt(1);
            boolean firstDigit = c0 >= '0' && c0 <= '9';
            boolean secondDigit = c1 >= '0' && c1 <= '9';
            if (firstDigit && secondDigit) {
                if (s.equals(str)) count++;
            } else if (firstDigit) {
                if (c0 == str.charAt(0)) count++;
            } else if (c0 == '_') {
                if (secondDigit) {
                    if (c1 == str.charAt(1)) count++;
                } else {
                    count++;
                }
            } else {
                if (secondDigit) {
                    if (c1 == str.charAt(1)) count++;
                } else if (c1 == '_') {
                    count++;
                }
            }
        }
        return count;
    }

    private static int handleLonger(String s, int l) {
        int start = (int) Math.pow(10, l - 1);
        int end = (int) Math.pow(10, l);
        int count = 0;
        for (int i = start; i < end; i += 25) {
            String str = Integer.toString(i);
            Set<Character> set = new HashSet<>();
            boolean flag = true;
            for (int j = 0; j < l; j++) {
                char ch = s.charAt(j);
                if (ch == '_') continue;
                if (ch == 'X') {
                    set.add(str.charAt(j));
                } else if (ch != str.charAt(j)) {
                    flag = false;
                    break;
                }
            }
            if (flag && set.size() < 2) count++;
        }
        return count;
    }
}

