            char pc = s.charAt(i);
            char nc = numStr.charAt(i);
            int digit = nc - '0';
            if (pc == 'X') {
                if (x >= 0 && x != digit) return false;
                x = digit;
            } else if (pc != '_') {
                if (pc - '0' != digit) return false;
            }
        }
        return true;
    }
