    }

    static class TaskG {
        static final int MOD = 998244353;
        static final int G = 3; // primitive root

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();
            int[] v = new int[10];
            for (int i = 0; i < k; i++) {
                int x = in.nextInt();
                v[x] = 1;
            }
            int[] ans = {1};
            int p = n / 2;
            while (true) {
                if (p % 2 != 0) {
                    ans = multiplyMod(ans, v, MOD);
                }
                p /= 2;
                if (p == 0) break;
                v = multiplyMod(v, v, MOD);
            }
            int res = 0;
            for (int x : ans) {
                res = (int) ((res + (long) x * x) % MOD);
            }
            out.println(res);
        }

        static int[] multiplyMod(int[] a, int[] b, int mod) {
            int need = a.length + b.length - 1;
            int n = 1;
            while (n < need) n <<= 1;
            int[] fa = new int[n];
            int[] fb = new int[n];
            System.arraycopy(a, 0, fa, 0, a.length);
            System.arraycopy(b, 0, fb, 0, b.length);

            ntt(fa, false);
            ntt(fb, false);
            for (int i = 0; i < n; i++) {
                fa[i] = (int) ((long) fa[i] * fb[i] % mod);
            }
            ntt(fa, true);
            int[] res = new int[need];
            System.arraycopy(fa, 0, res, 0, need);
            return res;
        }

        static void ntt(int[] a, boolean invert) {
            int n = a.length;
            int shift = 32 - Integer.numberOfTrailingZeros(n);
            for (int i = 1; i < n; i++) {
                int j = Integer.reverse(i << shift);
                if (i < j) {
                    int temp = a[i];
                    a[i] = a[j];
                    a[j] = temp;
                }
            }
            for (int len = 2; len <= n; len <<= 1) {
                int wlen = powMod(G, (MOD - 1) / len, MOD);
                if (invert) wlen = powMod(wlen, MOD - 2, MOD);
                for (int i = 0; i < n; i += len) {
                    int w = 1;
                    for (int j = 0; j < len / 2; j++) {
                        int u = a[i + j];
                        int v = (int) ((long) a[i + j + len / 2] * w % MOD);
                        a[i + j] = (u + v) % MOD;
                        a[i + j + len / 2] = (u - v + MOD) % MOD;
                        w = (int) ((long) w * wlen % MOD);
                    }
                }
            }
            if (invert) {
                int invN = powMod(n, MOD - 2, MOD);
                for (int i = 0; i < n; i++) {
                    a[i] = (int) ((long) a[i] * invN % MOD);
                }
            }
        }

        static int powMod(int a, int e, int mod) {
            int res = 1;
            while (e > 0) {
                if ((e & 1) == 1) res = (int) ((long) res * a % mod);
                a = (int) ((long) a * a % mod);
                e >>= 1;
            }
            return res;
        }
    }

