            int k = len / 2;
            while (j >= k) { j -= k; k /= 2; }
            if (j < k) j += k;
        }
    }

    // Recursive NTT
    static void NTT(long[] y, int len, int on) {
        if (len == 1) return;
        long[] even = new long[len / 2];
        long[] odd = new long[len / 2];
        for (int i = 0; i < len / 2; i++) {
            even[i] = y[2 * i];
            odd[i] = y[2 * i + 1];
        }
        NTT(even, len / 2, on);
        NTT(odd, len / 2, on);
        long wn = qpow(g, (mod - 1) / len);
