            y[i] = (even[i] + t) % mod;
            y[i + len / 2] = (even[i] - t + mod) % mod;
            w = w * wn % mod;
        }
        if (on == -1) {
            long inv = qpow(len, mod - 2);
            for (int i = 0; i < len; i++)
