    static class TaskG {
        static final int MOD = 998244353;
        static final int ROOT = 3;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();
            int[] v = new int[10];
            for (int i = 0; i < k; i++) {
                int x = in.nextInt();
                v[x] = 1;
            }
            int[] ans = {1};
            int p = n / 2;
            while (true) {
                if (p % 2 != 0) {
                    ans = multiplyMod(ans, v);
                }
                p /= 2;
                if (p == 0) break;
                v = multiplyMod(v, v);
            }
            int res = 0;
            for (int x : ans) {
                res = (int) ((res + (long) x * x) % MOD);
            }
            out.println(res);
        }

        static int modPow(int a, int e) {
            int res = 1;
            while (e > 0) {
                if ((e & 1) == 1) res = (int) ((long) res * a % MOD);
                a = (int) ((long) a * a % MOD);
                e >>= 1;
            }
            return res;
        }

        static void ntt(int[] a, boolean invert) {
            int n = a.length;
            int shift = 32 - Integer.numberOfTrailingZeros(n);
            for (int i = 1; i < n; i++) {
                int j = Integer.reverse(i << shift);
                if (i < j) {
                    int temp = a[i];
                    a[i] = a[j];
                    a[j] = temp;
                }
            }
            for (int len = 2; len <= n; len <<= 1) {
                int wlen = modPow(ROOT, (MOD - 1) / len);
                if (invert) wlen = modPow(wlen, MOD - 2);
                for (int i = 0; i < n; i += len) {
                    int w = 1;
                    for (int j = 0; j < len / 2; j++) {
                        int u = a[i + j];
                        int v = (int) ((long) a[i + j + len / 2] * w % MOD);
                        a[i + j] = (u + v) % MOD;
                        a[i + j + len / 2] = (u - v + MOD) % MOD;
                        w = (int) ((long) w * wlen % MOD);
                    }
                }
            }
            if (invert) {
                int invN = modPow(n, MOD - 2);
                for (int i = 0; i < n; i++) {
                    a[i] = (int) ((long) a[i] * invN % MOD);
                }
            }
        }

        static int[] multiplyMod(int[] a, int[] b) {
            int need = a.length + b.length - 1;
            int n = Math.max(2, Integer.highestOneBit(need - 1) << 1);
            int[] aLow = new int[n];
            int[] aHigh = new int[n];
            int[] bLow = new int[n];
            int[] bHigh = new int[n];
            for (int i = 0; i < a.length; i++) {
                int x = (a[i] % MOD + MOD) % MOD;
                aLow[i] = x & ((1 << 15) - 1);
                aHigh[i] = x >> 15;
            }
            for (int i = 0; i < b.length; i++) {
                int x = (b[i] % MOD + MOD) % MOD;
                bLow[i] = x & ((1 << 15) - 1);
                bHigh[i] = x >> 15;
            }
            ntt(aLow, false);
            ntt(aHigh, false);
            ntt(bLow, false);
            ntt(bHigh, false);
            int[] c00 = new int[n];
            int[] c01 = new int[n];
            int[] c10 = new int[n];
            int[] c11 = new int[n];
            for (int i = 0; i < n; i++) {
                c00[i] = (int) ((long) aLow[i] * bLow[i] % MOD);
                c01[i] = (int) ((long) aLow[i] * bHigh[i] % MOD);
                c10[i] = (int) ((long) aHigh[i] * bLow[i] % MOD);
                c11[i] = (int) ((long) aHigh[i] * bHigh[i] % MOD);
            }
            ntt(c00, true);
            ntt(c01, true);
            ntt(c10, true);
            ntt(c11, true);
            int[] res = new int[need];
            for (int i = 0; i < need; i++) {
                long low = c00[i];
                long mid = (c01[i] + c10[i]) % MOD;
                long high = c11[i];
                res[i] = (int) ((low + (mid << 15) + (high << 30)) % MOD);
            }
            return res;
        }
    }

