                    a[i] = a[j];
                    a[j] = temp;
                    temp = b[i];
                    b[i] = b[j];
                    b[j] = temp;
                }
            }
            // Precompute all twiddle factors for each level
            double[][] cosTable = new double[Integer.numberOfTrailingZeros(n)][];
            double[][] sinTable = new double[Integer.numberOfTrailingZeros(n)][];
            int level = 0;
            for (int len = 2; len <= n; len <<= 1) {
