                    sn[i] = Math.sin(2 * Math.PI * i / len * (inverse ? -1 : 1));
                }
                cosTable[level] = cs;
                sinTable[level] = sn;
                level++;
            }
            level = 0;
            for (int len = 2; len <= n; len <<= 1) {
                int halfLen = len >> 1;
                double[] cs = cosTable[level];
                double[] sn = sinTable[level];
