        long root = modPow(ROOT, modPow(2, twoPow - k));
        if (inverse) root = modInv(root);
        long[] roots = new long[k];
        if (k > 0) roots[k - 1] = root;
        for (int i = k - 1; i > 0; i--) {
            roots[i - 1] = (roots[i] * roots[i]) % MOD;
        }
        return roots;
    }

    // recursive NTT
    private static long[] nttRecursive(long[] a, int k, boolean inverse, long[] roots) {
        if (k == 0) return a;
        int n = 1 << k;
        long[] even = new long[n / 2];
        long[] odd = new long[n / 2];
        for (int i = 0; i < n / 2; i++) {
            even[i] = a[2 * i];
            odd[i] = a[2 * i + 1];
        }
        long[] rootsEven = new long[k - 1];
        long[] rootsOdd = new long[k - 1];
        for (int i = 0; i < k - 1; i++) {
            rootsEven[i] = roots[i];
            rootsOdd[i] = roots[i];
        }
        even = nttRecursive(even, k - 1, inverse, rootsEven);
        odd = nttRecursive(odd, k - 1, inverse, rootsOdd);
        long[] res = new long[n];
        long w = 1;
        long root = roots[k - 1];
        for (int i = 0; i < n / 2; i++) {
            long t = (w * odd[i]) % MOD;
            res[i] = (even[i] + t) % MOD;
            res[i + n / 2] = (even[i] - t) % MOD;
            w = (w * root) % MOD;
        }
        return res;
    }

    private static long[] numberTheoreticTransform(long[] coef, int k, boolean inverse) {
        long[] roots = calcRoots(k, inverse);
        // reorder using bit-reverse
        long[] reordered = new long[coef.length];
        for (int i = 0; i < coef.length; i++) {
            reordered[bitReverse(i, k)] = coef[i];
        }
        return nttRecursive(reordered, k, inverse, roots);
    }

    public static void main(String[] args) {
