            if ((p & 1) == 1) res = (res * a) % MOD;
            a = (a * a) % MOD;
            p >>= 1;
        }
        return res;
    }

    private static long modInv(long a) {
        return modPow(a, MOD - 2);
    }

    // compute roots on the fly without precomputed array
    private static long[] numberTheoreticTransform(long[] coef, int k, boolean inverse) {
        // reorder
        long[] a = new long[coef.length];
        for (int i = 0; i < coef.length; i++) {
            a[bitReverse(i, k)] = coef[i];
        }
        for (int s = 0; s < k; s++) {
            int len = 1 << s;
            long wlen = modPow(ROOT, modPow(2, twoPow - k + s));
            if (inverse) wlen = modInv(wlen);
            for (int st = 0; st < a.length; st += 2 * len) {
                long w = 1;
                for (int j = st; j < st + len; j++) {
                    long t = (w * a[j + len]) % MOD;
                    long u = a[j];
                    a[j] = (u + t) % MOD;
                    a[j + len] = (u - t) % MOD;
                    w = (w * wlen) % MOD;
                }
            }
        }
        return a;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt() / 2;
        int m = sc.nextInt();
        int[] nums = new int[m];
        int max = 0;
        for (int i = 0; i < m; i++) {
            nums[i] = sc.nextInt();
            max = Math.max(max, nums[i]);
        }
        int min_size = n * max + 1;
        int k = 0;
        int size = 1;
        while (size < min_size) {
            size *= 2;
            k++;
        }
        long[] a = new long[size];
        for (int i = 0; i < nums.length; i++) {
            a[nums[i]] = 1;
        }
        a = numberTheoreticTransform(a, k, false);
        for (int i = 0; i < size; i++) {
            a[i] = modPow(a[i], n);
        }
        a = numberTheoreticTransform(a, k, true);
        long ans = 0;
        for (int i = 0; i < size; i++) {
            ans = (ans + a[i] * a[i]) % MOD;
        }
        long multiplier = modInv(size);
        System.out.println((((ans * multiplier) % MOD) * multiplier) % MOD);
    }
}

