import java.io.*;
import java.util.*;
public class CF939_D2_F {
	public static void main(String[] args)throws Throwable {
		Scanner sc = new Scanner(System.in);
		PrintWriter pw = new PrintWriter(System.out);

		int n = sc.nextInt() * 2;
		int k = sc.nextInt();
		int[] l = new int[k + 1];
		int[] r = new int[k + 1];
		SegmentTree[][] seg = new SegmentTree[2][2];
		for (int i = 0; i < k; i++) {
			l[i] = sc.nextInt();
			r[i] = sc.nextInt();
		}
		l[k] = n;
		for (int j = 0; j < 2; j++) {
			int[] a = new int[n / 2 + 2];
			Arrays.fill(a, inf);
			a[n / 2] = 0;
			seg[1][j] = new SegmentTree(a);
		}
		int p = 0;
		for (int i = k - 1; i >= 0; i--) {
			for (int j = 0; j < 2; j++) {
				int[] a = new int[n / 2 + 2];
				Arrays.fill(a, inf);
				int limit = Math.min(l[i], a.length - 1);
				for (int c = 0; c <= limit; c++) {
					int best = seg[1 - p][j].query(c + l[i + 1] - l[i], c + l[i + 1] - l[i]);
					best = Math.min(best, 1 + seg[1 - p][1 - j].query(l[i + 1] - (c + r[i] - l[i]), l[i + 1] - c));
					if (r[i] > l[i])
						best = Math.min(best, 2 + seg[1 - p][j].query(c + l[i + 1] - r[i], c + l[i + 1] - l[i] - 1));
					a[c] = best;
				}
				seg[p][j] = new SegmentTree(a);
			}
			p ^= 1;
		}
		p ^= 1;
		int ans = Math.min(seg[p][0].query(l[0], l[0]), seg[p][1].query(l[0], l[0]));
		if (ans > 2 * k)
			pw.println("Hungry");
		else {
			pw.println("Full");
			pw.println(ans);
		}
		pw.flush();
		pw.close();
	}

	static int inf = (int) 1e7;

	static class SegmentTree {
		int[] tree;
		int n;

		SegmentTree(int[] a) {
			n = a.length;
			tree = new int[4 * n];
			build(1, 0, n - 1, a);
		}

		void build(int node, int l, int r, int[] a) {
			if (l == r) {
				tree[node] = a[l];
			} else {
				int mid = (l + r) / 2;
				build(node * 2, l, mid, a);
				build(node * 2 + 1, mid + 1, r, a);
				tree[node] = Math.min(tree[node * 2], tree[node * 2 + 1]);
			}
		}

		int query(int ql, int qr) {
			if (ql >= n) return inf;
			qr = Math.min(qr, n - 1);
			return query(1, 0, n - 1, ql, qr);
		}

		int query(int node, int l, int r, int ql, int qr) {
			if (ql > r || qr < l) return inf;
			if (ql <= l && r <= qr) return tree[node];
			int mid = (l + r) / 2;
			return Math.min(query(node * 2, l, mid, ql, qr), query(node * 2 + 1, mid + 1, r, ql, qr));
		}
	}
}

