		}
		pw.flush();
		pw.close();
	}

	static int inf = (int) 1e7;

	static class SparseTable {
		int[] a;
		int[][] st;

		SparseTable(int[] a) {
			this.a = a;
			int n = a.length;
			int k = (int) (Math.log(n) / Math.log(2)) + 1;
			st = new int[n][k];
			for (int i = 0; i < n; i++)
				st[i][0] = i;
			for (int j = 1; (1 << j) <= n; j++)
				for (int i = 0; i + (1 << j) - 1 < n; i++)
					if (a[st[i][j - 1]] < a[st[i + (1 << (j - 1))][j - 1]])
						st[i][j] = st[i][j - 1];
					else
						st[i][j] = st[i + (1 << (j - 1))][j - 1];
		}

		int query(int i, int j) {
			if (i >= a.length) return inf;
			j = Math.min(j, a.length - 1);
			int k = (int) (Math.log(j - i + 1) / Math.log(2));
			return Math.min(a[st[i][k]], a[st[j - (1 << k) + 1][k]]);
		}
	}

