public class Task939F {

    private static int N, K, rotates, minRotates;
    private static int[] start, end;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        N = Integer.parseInt(st.nextToken());
        K = Integer.parseInt(st.nextToken());
        start = new int[K];
        end = new int[K];
        for (int i = 0; i < K; i++) {
            st = new StringTokenizer(br.readLine());
            start[i] = Integer.parseInt(st.nextToken());
            end[i] = Integer.parseInt(st.nextToken());
        }
        br.close();

        int[] lo = new int[2];
        int[] hi = new int[2];
        rotates = 0;
        minRotates = 0;

        solve(0, lo, hi, 0, 0, false);

        if (minRotates > 0) {
            System.out.println("Full");
            System.out.println(minRotates);
        } else {
            System.out.println("Hungry");
        }
    }

    private static void update(int val) {
        if (minRotates == 0) minRotates = val;
        else minRotates = Math.min(minRotates, val);
    }

    private static void solve(int side, int[] lo, int[] hi,
                              int offset, int idx, boolean inside) {
        if (lo[0] > N || lo[1] > N) return;
        if ((lo[0] <= N && hi[0] >= N) || (lo[1] <= N && hi[1] >= N)) {
            if ((hi[0] < N && side == 1) || (hi[1] < N && side == 0)) {
                update(rotates + 1);
            } else {
                update(rotates);
            }
            return;
        }
        if (idx == K) return;

        if (inside) {
            if (start[idx] == end[idx]) {
                solve(side, lo, hi, offset, idx + 1, false);
                rotates++;
                solve(1 - side, lo, hi, offset, idx + 1, false);
                rotates--;
            } else {
                // no rotate
                lo[side] += end[idx] - start[idx];
                hi[side] += end[idx] - start[idx];
                solve(side, lo, hi, end[idx], idx + 1, false);
                lo[side] -= end[idx] - start[idx];
                hi[side] -= end[idx] - start[idx];

                // rotate once
                hi[side] += end[idx] - start[idx];
                hi[1 - side] += end[idx] - start[idx];
                rotates++;
                solve(1 - side, lo, hi, end[idx], idx + 1, false);
                rotates--;
                hi[side] -= end[idx] - start[idx];
                hi[1 - side] -= end[idx] - start[idx];

                // rotate twice
                hi[side] += end[idx] - start[idx];
                lo[1 - side] += 1;
                hi[1 - side] += end[idx] - start[idx] - 1;
                rotates += 2;
                solve(side, lo, hi, end[idx], idx + 1, false);
                rotates -= 2;
                hi[side] -= end[idx] - start[idx];
                lo[1 - side] -= 1;
                hi[1 - side] -= end[idx] - start[idx] - 1;
            }
        } else {
            lo[side] += start[idx] - offset;
            hi[side] += start[idx] - offset;
            solve(side, lo, hi, start[idx], idx, true);
            lo[side] -= start[idx] - offset;
            hi[side] -= start[idx] - offset;
        }
    }
}

