            L[i] = fs.nextInt();
            R[i] = fs.nextInt();
        }

        int[] lo = new int[2];
        int[] hi = new int[2];
        rotates = 0;
        minRot = 0;

        dfs(0, lo, hi, 0, 0, false);

        if (minRot > 0) {
            System.out.println("Full");
            System.out.println(minRot);
        } else {
            System.out.println("Hungry");
        }
    }

    private static void save(int x) {
        if (minRot == 0) minRot = x;
        else minRot = Math.min(minRot, x);
    }

    private static void dfs(int side, int[] lo, int[] hi,
                            int off, int idx, boolean inside) {
        if (lo[0] > N || lo[1] > N) return;
        if ((lo[0] <= N && hi[0] >= N) || (lo[1] <= N && hi[1] >= N)) {
            if ((hi[0] < N && side == 1) || (hi[1] < N && side == 0)) {
                save(rotates + 1);
            } else {
                save(rotates);
            }
            return;
        }
        if (idx == K) return;

        if (inside) {
            if (L[idx] == R[idx]) {
                dfs(side, lo, hi, off, idx + 1, false);
                rotates++;
                dfs(1 - side, lo, hi, off, idx + 1, false);
                rotates--;
            } else {
                int d = R[idx] - L[idx];
                // no rotate
                lo[side] += d;
                hi[side] += d;
                dfs(side, lo, hi, R[idx], idx + 1, false);
                lo[side] -= d;
                hi[side] -= d;

                // rotate once
                hi[side] += d;
                hi[1 - side] += d;
                rotates++;
                dfs(1 - side, lo, hi, R[idx], idx + 1, false);
                rotates--;
                hi[side] -= d;
                hi[1 - side] -= d;

                // rotate twice
                hi[side] += d;
                lo[1 - side] += 1;
                hi[1 - side] += d - 1;
                rotates += 2;
                dfs(side, lo, hi, R[idx], idx + 1, false);
                rotates -= 2;
                hi[side] -= d;
                lo[1 - side] -= 1;
                hi[1 - side] -= d - 1;
            }
        } else {
            int d = L[idx] - off;
            lo[side] += d;
            hi[side] += d;
            dfs(side, lo, hi, L[idx], idx, true);
            lo[side] -= d;
            hi[side] -= d;
        }
    }

    // FastScanner with smaller buffer
    public static class FastScanner {
        protected DataInputStream dis;
        protected byte[] buf = new byte[8192];
        protected int pos, len;
        protected boolean eof;

        public FastScanner() throws IOException {
            dis = new DataInputStream(System.in);
            read();
        }

        protected void read() throws IOException {
            int n = dis.read(buf);
            if (n > 0) {
                len = n;
            } else {
                len = 0;
                eof = true;
            }
            pos = 0;
        }

        protected byte next() throws IOException {
            if (pos == len) {
                if (!eof) read();
                if (eof) return 0;
            }
            return buf[pos++];
        }

        public int nextInt() throws IOException {
            int a = 0;
            boolean neg = false;
            byte b = next();
            while (b <= ' ') b = next();
            if (b == '-') {
                neg = true;
                b = next();
            }
            while (b > ' ') {
                a = a * 10 + (b - '0');
                b = next();
            }
            return neg ? -a : a;
        }
    }
}

