        for (int i = k - 1; i >= 0; i--) {
            for (int j = 0; j <= 2 * n; j++) {
                dp[0][i][j] = j + l[i] + delt[i] <= 2 * n ? dp[0][i + 1][j + l[i] + delt[i]] : n;
                dp[1][i][j] = dp[1][i + 1][j];
                // compute min over range [j, min(j+l[i],2n)] for rmq[1]
                int min1 = Integer.MAX_VALUE;
