        for (int i = 0; i < k; i++) {
            lo = segs[i][0];
            hi = segs[i][0];
            while (i < k && segs[i][0] <= hi) hi = Math.max(hi, segs[i++][1]);
            finSeg.add(new int[]{lo, hi});
