                    for (int z = 0; z <= 1; z++) {
                        int twoSwaps = dp[z].query(j - sz, j);
                        int oneSwap = dp[(z + 1) % 2].query(j - sz, j);
                        int noSwap;
                        if (z == 1) {
                            noSwap = dp[z].getVal(j);
                        } else {
                            noSwap = dp[z].getVal(j - sz);
                        }
                        put[z] = Math.min(twoSwaps + 2, Math.min(oneSwap + 1, noSwap));
                    }
                    dp[0].assign(j, put[0]);
                    dp[1].assign(j, put[1]);
                }
            }
            int ans = Math.min(dp[0].query(N, N), dp[1].query(N, N));
            if (ans >= MAX) {
                out.println("Hungry");
            } else {
                out.println("Full");
                out.println(ans);
            }
        }

        class SegmentTree {
            int[] tree;
            int[] arr;
            int size;

            public SegmentTree(int N) {
                size = N;
                tree = new int[2 * N];
                arr = new int[N];
                Arrays.fill(arr, MAX);
                for (int i = 0; i < 2 * N; i++) {
                    tree[i] = MAX;
                }
            }

            public int query(int l, int r) {
                if (r < 0) return MAX;
                l = Math.max(0, l);
                if (l > r) return MAX;
                int res = MAX;
                l += size;
                r += size;
                while (l <= r) {
                    if ((l & 1) == 1) res = Math.min(res, tree[l++]);
                    if ((r & 1) == 0) res = Math.min(res, tree[r--]);
                    l >>= 1;
                    r >>= 1;
                }
                return res;
            }

            public void assign(int n, int val) {
                arr[n] = val;
                int idx = n + size;
                tree[idx] = val;
                idx >>= 1;
                while (idx > 0) {
                    tree[idx] = Math.min(tree[2 * idx], tree[2 * idx + 1]);
                    idx >>= 1;
                }
            }

            int getVal(int i) {
                if (i < 0) return MAX;
                return arr[i];
            }
        }
    }

