    static class TaskF {
        int MAX = (int) (1e9);

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            int k = in.nextInt();
            ArrayList<int[]> interval = new ArrayList<>();
            for (int i = 0; i < k; i++) {
                interval.add(new int[]{in.nextInt(), in.nextInt()});
            }
            interval.add(new int[]{2 * N, 2 * N});
            int cur = 0;
            SegmentTree[] dp = new SegmentTree[2];
            dp[0] = new SegmentTree(N + 1);
            dp[1] = new SegmentTree(N + 1);
            dp[0].assign(0, 0);
            for (int i = 0; i < interval.size(); i++) {
                int[] seg = interval.get(i);
                for (int j = N; j >= 0; j--) {
                    dp[0].assign(j, dp[0].getVal(j - (seg[0] - cur)));
                }
                cur = seg[1];
                int sz = seg[1] - seg[0];
                for (int j = N; j >= 0; j--) {
                    int[] put = new int[2];
                    for (int z = 0; z <= 1; z++) {
                        int twoSwaps = dp[z].query(j - sz, j);
                        int oneSwap = dp[(z + 1) % 2].query(j - sz, j);
                        int noSwap;
                        if (z == 1) {
                            noSwap = dp[z].getVal(j);
                        } else {
                            noSwap = dp[z].getVal(j - sz);
                        }
                        put[z] = Math.min(twoSwaps + 2, Math.min(oneSwap + 1, noSwap));
                    }
                    dp[0].assign(j, put[0]);
                    dp[1].assign(j, put[1]);
                }
            }
            int ans = Math.min(dp[0].query(N, N), dp[1].query(N, N));
            if (ans >= MAX) {
                out.println("Hungry");
            } else {
                out.println("Full");
                out.println(ans);
            }
        }

        class SegmentTree {
            int[] tree;
            int[] arr;
            int size;

            public SegmentTree(int N) {
                size = N;
                tree = new int[4 * N];
                arr = new int[N];
                Arrays.fill(arr, MAX);
                build(1, 0, size - 1);
            }

            private void build(int n, int tl, int tr) {
                if (tl == tr) {
                    tree[n] = arr[tl];
                } else {
                    int tm = (tl + tr) / 2;
                    build(2 * n, tl, tm);
                    build(2 * n + 1, tm + 1, tr);
                    tree[n] = Math.min(tree[2 * n], tree[2 * n + 1]);
                }
            }

            public int query(int l, int r) {
                if (r < 0) return MAX;
                return queryUtil(1, 0, size - 1, Math.max(0, l), r);
            }

            private int queryUtil(int n, int tl, int tr, int l, int r) {
                if (l > r) return MAX;
                if (tl == l && tr == r) return tree[n];
                int tm = (tl + tr) / 2;
                return Math.min(queryUtil(2 * n, tl, tm, l, Math.min(r, tm)),
                                queryUtil(2 * n + 1, tm + 1, tr, Math.max(tm + 1, l), r));
            }

            public void assign(int n, int val) {
                arr[n] = val;
                update(1, 0, size - 1, n, val);
            }

            private void update(int n, int tl, int tr, int pos, int val) {
                if (tl == tr) {
                    tree[n] = val;
                } else {
                    int tm = (tl + tr) / 2;
                    if (pos <= tm) update(2 * n, tl, tm, pos, val);
                    else update(2 * n + 1, tm + 1, tr, pos, val);
                    tree[n] = Math.min(tree[2 * n], tree[2 * n + 1]);
                }
            }

            int getVal(int i) {
                if (i < 0) return MAX;
                return arr[i];
            }
        }
    }

