            Deque<Integer> dq = new ArrayDeque<>();
            int w = ts[i][1] - ts[i][0];
            // Process dp[0] (even)
            for (int j = 0; j <= n; j++) {
                while (dq.size() > 0 && dp[0][dq.peekLast()] >= dp[0][j]) {
                    dq.pollLast();
                }
                while (dq.size() > 0 && dq.peekFirst() < j - w) {
                    dq.pollFirst();
                }
                dq.add(j);
                ndp[1][j] = Math.min(ndp[1][j], dp[0][dq.peekFirst()] + 1);
                if (j + w <= n) ndp[0][j + w] = Math.min(ndp[0][j + w], dp[0][j]);
            }
            dq.clear();
            // Process dp[1] (odd)
            for (int j = 0; j <= n; j++) {
                while (dq.size() > 0 && dp[1][dq.peekLast()] >= dp[1][j]) {
                    dq.pollLast();
