                dp[0][j] = dp[0][j - s];
            }
            for (int j = Math.min(n, s - 1); j >= 0; j--) dp[0][j] = 99999999;
        }
        int ans = Math.min(dp[0][n], dp[1][n]);
        if (ans >= 9999999) {
