    static long[] ones = {0, 1, 11, 111, 1111, 11111, 111111, 1111111, 11111111, 111111111, 1111111111, 11111111111L, 111111111111L, 1111111111111L, 11111111111111L, 111111111111111L, 1111111111111111L};
    public static long decompose(long n) {
        if (n <= 6) return n;
        long digit = getLength(n);
        long low = ones[(int) digit];
        long high;
        if (n < low) {
            high = low;
            low = ones[(int) (digit - 1)];
        } else if (n > low) {
            high = ones[(int) (digit + 1)];
        } else {
            return digit;
        }
        long lowRes = decompose(n % low) + (n / low) * getLength(low);
        long highRes = Long.MAX_VALUE;
        if (high - n < n) {
            highRes = decompose(high - n) + getLength(high);
        }
        return Math.min(lowRes, highRes);
    }
    static long getLength(long x) {
        long cnt = 0;
        for (long t = x; t > 0; t /= 10) cnt++;
        return cnt;
    }
}

