    public static long decompose(long n) {
        if (n <= 6) return n;
        long dig = (long) Math.floor(Math.log10(n)) + 1;
        long low = ones[(int) dig];
        long high;
        if (n < low) {
            high = low;
            low = ones[(int) (dig - 1)];
        } else if (n > low) {
            high = ones[(int) (dig + 1)];
        } else {
            return dig;
        }
        long left = decompose(n % low) + (n / low) * ((long) Math.floor(Math.log10(low)) + 1);
        long right = Long.MAX_VALUE;
        if (high - n < n) {
            right = decompose(high - n) + ((long) Math.floor(Math.log10(high)) + 1);
        }
        return Math.min(left, right);
    }
