public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long n = in.nextLong();
        int result = f(n);
        System.out.println(result);
        in.close();
    }

    static int f(long n) {
        if (n <= 1L) return (int) n;
        // compute pow on the fly
        long pow = 1L;
        int len = 1;
        while (pow < n) {
            pow = 10L * pow + 1L;
            len++;
        }
        // now pow is the smallest repunit >= n, len is its length
        long m1 = 0L, m2 = pow;
        int x1 = 0, x2 = len;
        long prevPow = (pow - 1L) / 10L; // pow of length len-1
        while (m1 + prevPow <= n) {
            m1 += prevPow;
            x1 += len - 1;
        }
        while (m2 - prevPow >= n) {
            m2 -= prevPow;
            x2 += len - 1;
        }
        x1 += f(n - m1);
        x2 += f(m2 - n);
        return Math.min(x1, x2);
    }
}

