public class C {

    static long[] ONES = new long[17];
    static {
        ONES[1] = 1;
        for (int i = 2; i < 17; i++) {
            ONES[i] = 10 * ONES[i - 1] + 1;
        }
    }

    // Iterative version of go using explicit stack
    long go(long x, int len) {
        x = Math.abs(x);
        Deque<Object[]> stack = new ArrayDeque<>();
        // Each frame: [x, len, state, low, high, ret1, ret2]
        // state: 0 = initial, 1 = after first child, 2 = after second child
        stack.push(new Object[]{x, len, 0, 0L, 0L, 0L, 0L});
        long result = 0;
        while (!stack.isEmpty()) {
            Object[] frame = stack.peek();
            long cx = (Long) frame[0];
            int clen = (Integer) frame[1];
            int state = (Integer) frame[2];
            if (state == 0) {
                if (cx % ONES[clen] == 0) {
                    result = cx / ONES[clen] * clen;
                    stack.pop();
                    continue;
                }
                long low = cx / ONES[clen];
                long high = low + 1;
                frame[3] = low;
                frame[4] = high;
                // Push first child
                frame[2] = 1;
                stack.push(new Object[]{cx - low * ONES[clen], clen - 1, 0, 0L, 0L, 0L, 0L});
            } else if (state == 1) {
                frame[5] = result; // ret1
                long high = (Long) frame[4];
                long cx = (Long) frame[0];
                int clen = (Integer) frame[1];
                // Push second child
                frame[2] = 2;
                stack.push(new Object[]{high * ONES[clen] - cx, clen - 1, 0, 0L, 0L, 0L, 0L});
            } else { // state == 2
                frame[6] = result; // ret2
                long low = (Long) frame[3];
                long high = (Long) frame[4];
                long ret1 = (Long) frame[5];
                long ret2 = (Long) frame[6];
                int clen = (Integer) frame[1];
                result = Math.min(low * clen + ret1, high * clen + ret2);
                stack.pop();
            }
        }
        return result;
    }

    long solve(long x) {
        return go(x, 16);
    }

    C() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        out.println(solve(Long.parseLong(br.readLine().trim())));
        out.close();
    }

    public static void main(String[] args) throws IOException {
        new C();
    }
}

import java.io.*;
import java.util.*;

public class C {

    static long[] ONES = new long[17];
    static {
        ONES[1] = 1;
        for (int i = 2; i < 17; i++) {
            ONES[i] = 10 * ONES[i - 1] + 1;
        }
    }

    // Memoization cache
    static Map<Pair, Long> memo = new HashMap<>();

    static class Pair {
        long x;
        int len;
        Pair(long x, int len) { this.x = x; this.len = len; }
        @Override
        public boolean equals(Object o) {
            if (!(o instanceof Pair)) return false;
            Pair p = (Pair) o;
            return x == p.x && len == p.len;
        }
        @Override
        public int hashCode() {
            return (int)(x ^ (x >>> 32)) * 31 + len;
        }
    }

    long go(long x, int len) {
        x = Math.abs(x);
        Pair key = new Pair(x, len);
        if (memo.containsKey(key)) return memo.get(key);
        long res;
        if (x % ONES[len] == 0) {
            res = x / ONES[len] * len;
        } else {
            long low = x / ONES[len];
            long high = low + 1;
            long ret1 = low * len + go(x - low * ONES[len], len - 1);
            long ret2 = high * len + go(high * ONES[len] - x, len - 1);
            res = Math.min(ret1, ret2);
        }
        memo.put(key, res);
        return res;
    }

    long solve(long x) {
        return go(x, 16);
    }

    C() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        out.println(solve(Long.parseLong(br.readLine().trim())));
        out.close();
    }

    public static void main(String[] args) throws IOException {
        new C();
    }
}

