class TaskC {
    public void solve(int testNumber, FastScanner in, FastPrinter out) {
        int shift = 15;
        int maxn = 60;
        int sizePlus = maxn + 1;
        int sizeMinus = maxn + 1;
        int sizeCarry = shift * 2 + 1;
        int totalSize = sizePlus * sizeMinus * sizeCarry;
        int[] dp = new int[totalSize];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[maxn * sizeMinus * sizeCarry + maxn * sizeCarry + shift] = 0;
        char[] d = ("000" + in.next()).toCharArray();
        for (int i = d.length - 1; i >= 0; i--) {
            int digit = d[i] - '0';
            for (int plus = maxn; plus >= 0; plus--) {
                for (int minus = maxn; minus >= 0; minus--) {
                    int base = plus * sizeMinus * sizeCarry + minus * sizeCarry;
                    for (int carry = 0; carry < sizeCarry; carry++) {
                        int idx = base + carry;
                        if (plus + 1 <= maxn)
                            dp[idx] = Math.min(dp[idx], dp[(plus + 1) * sizeMinus * sizeCarry + minus * sizeCarry + carry]);
                        if (minus + 1 <= maxn)
                            dp[idx] = Math.min(dp[idx], dp[plus * sizeMinus * sizeCarry + (minus + 1) * sizeCarry + carry]);
                    }
                }
            }
            int[] next = new int[totalSize];
            Arrays.fill(next, Integer.MAX_VALUE);
            for (int plus = maxn; plus >= 0; plus--) {
                for (int minus = maxn; minus >= 0; minus--) {
                    int base = plus * sizeMinus * sizeCarry + minus * sizeCarry;
                    for (int carry = 0; carry < sizeCarry; carry++) {
                        int idx = base + carry;
                        int val = dp[idx];
                        if (val == Integer.MAX_VALUE) continue;
                        int realCarry = carry - shift;
                        int curN = plus - minus + realCarry;
                        int curD = curN % 10;
                        if (curD < 0) curD += 10;
                        int newCarry = (curN - curD) / 10;
                        if (curD != digit) continue;
                        int nidx = plus * sizeMinus * sizeCarry + minus * sizeCarry + (newCarry + shift);
                        next[nidx] = Math.min(next[nidx], plus + minus + val);
                    }
                }
            }
            dp = next;
        }
        int ans = Integer.MAX_VALUE;
        for (int i = 0; i <= maxn; i++) {
            for (int j = 0; j <= maxn; j++) {
                ans = Math.min(ans, dp[i * sizeMinus * sizeCarry + j * sizeCarry + shift]);
            }
        }
        out.println(ans);
    }
}

