    public void solve(int testNumber, FastScanner in, FastPrinter out) {
        int shift = 15;
        int maxn = 60;
        int maxTotal = 2 * maxn;
        int maxDiff = maxn;
        int sizeCarry = shift * 2 + 1;
        int[][][] dp = new int[maxTotal + 1][2 * maxDiff + 1][sizeCarry];
        for (int[][] e1 : dp) {
            for (int[] e2 : e1) Arrays.fill(e2, Integer.MAX_VALUE);
        }
        dp[maxTotal][maxDiff][shift] = 0; // total=120, diff=0, carry=0
        char[] d = ("000" + in.next()).toCharArray();
        for (int i = d.length - 1; i >= 0; i--) {
            int digit = d[i] - '0';
            for (int total = maxTotal; total >= 0; total--) {
                for (int diff = -maxDiff; diff <= maxDiff; diff++) {
                    int diffIdx = diff + maxDiff;
                    for (int carry = 0; carry < sizeCarry; carry++) {
                        if (total + 1 <= maxTotal) {
                            // increase plus: total+1, diff+1
                            dp[total][diffIdx][carry] = Math.min(dp[total][diffIdx][carry], dp[total + 1][diff + 1 + maxDiff][carry]);
                            // increase minus: total+1, diff-1
                            dp[total][diffIdx][carry] = Math.min(dp[total][diffIdx][carry], dp[total + 1][diff - 1 + maxDiff][carry]);
                        }
                    }
                }
            }
            int[][][] next = new int[maxTotal + 1][2 * maxDiff + 1][sizeCarry];
            for (int[][] e1 : next) {
                for (int[] e2 : e1) Arrays.fill(e2, Integer.MAX_VALUE);
            }
            for (int total = maxTotal; total >= 0; total--) {
                for (int diff = -maxDiff; diff <= maxDiff; diff++) {
                    int diffIdx = diff + maxDiff;
                    for (int carry = 0; carry < sizeCarry; carry++) {
                        int val = dp[total][diffIdx][carry];
                        if (val == Integer.MAX_VALUE) continue;
                        int realCarry = carry - shift;
                        int curN = diff + realCarry;
                        int curD = curN % 10;
                        if (curD < 0) curD += 10;
                        int newCarry = (curN - curD) / 10;
                        if (curD != digit) continue;
                        next[total][diffIdx][newCarry + shift] = Math.min(next[total][diffIdx][newCarry + shift], total + val);
                    }
                }
            }
            dp = next;
        }
        int ans = Integer.MAX_VALUE;
        for (int total = 0; total <= maxTotal; total++) {
            for (int diff = -maxDiff; diff <= maxDiff; diff++) {
                ans = Math.min(ans, dp[total][diff + maxDiff][shift]);
            }
        }
        out.println(ans);
    }
}

