        while (a < n) {
            c++;
            diff = n - a;
            a += inc;
        }
        long res;
        if (c > 0) {
            res = Math.min(c * d + f(diff), (c + 1) * d + f(a - n));
        } else {
            res = (c + 1) * d + f(a - n);
        }
        long next = makeOnes(d + 1);
        if (next - n < n) {
            res = Math.min(res, d + 1 + f(next - n));
        }
        return res;
    }
}

