        System.out.println(calc(n));
    }

    private static int len(long x) {
        return (int) Math.log10(x) + 1;
    }

    private static long rep(int k) {
        long r = 1;
        while (--k > 0) r = r * 10 + 1;
        return r;
    }

    private static long calc(long n) {
        if (n <= 6) return n;
        int d = len(n);
        long a = rep(d);
        long s = a;
        long dif = n;
        int c = 0;
        while (a < n) {
            c++;
            dif = n - a;
            a += s;
        }
        long ans = (c > 0) ? Math.min(c * d + calc(dif), (c + 1) * d + calc(a - n)) : (c + 1) * d + calc(a - n);
        long b = rep(d + 1);
        if (b - n < n) ans = Math.min(ans, d + 1 + calc(b - n));
        return ans;
    }
}

