public class CF1187G {
    static final int INF = 0x3f3f3f3f;
    PrintWriter out;
    Scanner sc;

    class Edge {
        int u, v, rev, cap, cost;
        Edge(int u, int v, int cap, int cost) {
            this.u = u;
            this.v = v;
            this.cap = cap;
            this.cost = cost;
        }
    }

    ArrayList<Edge>[] graph;
    int n, m;
    int[] pi, dd, bb;
    boolean[] inq;
    ArrayDeque<Integer> q;

    void addEdge(int u, int v, int cap, int cost) {
        Edge a = new Edge(u, v, cap, cost);
        Edge b = new Edge(v, u, 0, -cost);
        a.rev = graph[v].size();
        b.rev = graph[u].size();
        graph[u].add(a);
        graph[v].add(b);
    }

    boolean spfa(int s, int t) {
        Arrays.fill(pi, INF);
        pi[s] = 0;
        q.clear();
        q.add(s);
        inq[s] = true;
        while (!q.isEmpty()) {
            int u = q.poll();
            inq[u] = false;
            int d = dd[u] + 1;
            for (Edge e : graph[u]) {
                if (e.cap > 0) {
                    int v = e.v;
                    int p = pi[u] + e.cost;
                    if (pi[v] > p || (pi[v] == p && dd[v] > d)) {
                        pi[v] = p;
                        dd[v] = d;
                        bb[v] = e.rev;
                        if (!inq[v]) {
                            q.add(v);
                            inq[v] = true;
                        }
                    }
                }
            }
        }
        return pi[t] != INF;
    }

    void push1(int s, int t) {
        for (int u = t; u != s; ) {
            Edge e = graph[u].get(bb[u]);
            e.cap++;
            graph[e.v].get(e.rev).cap--;
            u = e.v;
        }
    }

    int edmonds_karp(int s, int t) {
        while (spfa(s, t))
            push1(s, t);
        int flow = 0;
        for (int u = 0; u < n; u++)
            for (Edge e : graph[u])
                if (e.cost > 0)
                    flow += e.cost * e.cap;
        return flow;
    }

    void solve() {
        int N = sc.nextInt();
        int M = sc.nextInt();
        int K = sc.nextInt();
        int C = sc.nextInt();
        int D = sc.nextInt();

        int[] start = new int[K];
        for (int i = 0; i < K; i++)
            start[i] = sc.nextInt() - 1;

        ArrayList<Integer>[] adj = new ArrayList[N];
        for (int i = 0; i < N; i++)
            adj[i] = new ArrayList<>();
        for (int i = 0; i < M; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            adj[a].add(b);
            adj[b].add(a);
        }

        int T = N + K + 1;
        n = N * T + 1;
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++)
            graph[i] = new ArrayList<>();
        pi = new int[n];
        dd = new int[n];
        bb = new int[n];
        inq = new boolean[n];
        q = new ArrayDeque<>();

        for (int i = 0; i < N; i++) {
            for (int s = 0; s < T - 1; s++) {
                int u = i * T + s;
                for (int j : adj[i]) {
                    int v = j * T + s + 1;
                    for (int x = 1; x <= K; x++)
                        addEdge(u, v, 1, C + (x * 2 - 1) * D);
                }
            }
        }

        for (int i = 0; i < N; i++)
            for (int s = 0; s < T - 1; s++) {
                int u = i * T + s, v = u + 1;
                addEdge(u, v, K, i == 0 ? 0 : C);
            }

        for (int h = 0; h < K; h++)
            addEdge(n - 1, start[h] * T, 1, 0);

        out.println(edmonds_karp(n - 1, 0 * T + T - 1));
    }

    CF1187G() {
        out = new PrintWriter(System.out);
        sc = new Scanner(System.in);
    }

    public static void main(String[] args) {
        CF1187G o = new CF1187G();
        o.solve();
        o.out.flush();
    }
}

