            adj[v].add(h << 1 | 1);
        }

        void enqueue(int v) {
            if (inq[v]) return;
            if (head + cnt == nq) {
                if (cnt * 2 <= nq)
                    System.arraycopy(qq, head, qq, 0, cnt);
                else {
                    int[] tmp = new int[nq *= 2];
                    System.arraycopy(qq, head, tmp, 0, cnt);
                    qq = tmp;
                }
                head = 0;
            }
            qq[head + cnt++] = v;
            inq[v] = true;
        }

        int dequeue() {
            int u = qq[head++];
            cnt--;
            inq[u] = false;
            return u;
        }

        boolean spfa(int s, int t) {
            Arrays.fill(pi, INF);
            pi[s] = 0;
            head = cnt = 0;
            enqueue(s);
            while (cnt > 0) {
                int u = dequeue();
                int d = dd[u] + 1;
                for (int h_ : adj[u]) {
                    if (cap[h_] > 0) {
                        int h = h_ >> 1;
                        int p = pi[u] + ((h_ & 1) == 0 ? cost[h] : -cost[h]);
                        int v = u ^ uv[h];
                        if (pi[v] > p || (pi[v] == p && dd[v] > d)) {
                            pi[v] = p;
                            dd[v] = d;
                            bb[v] = h_;
                            enqueue(v);
                        }
                    }
                }
            }
            return pi[t] != INF;
        }

        void push1(int s, int t) {
            for (int u = t, h_, h; u != s; u ^= uv[h]) {
                h = (h_ = bb[u]) >> 1;
                cap[h_]--;
                cap[h_ ^ 1]++;
            }
        }

        int edmonds_karp(int s, int t) {
            while (spfa(s, t))
                push1(s, t);
            int flow = 0;
            for (int h = 0; h < m; h++)
                flow += cost[h] * cap[h << 1 | 1];
            return flow;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        int K = sc.nextInt();
        int C = sc.nextInt();
        int D = sc.nextInt();

        int[] start = new int[K];
        for (int i = 0; i < K; i++)
            start[i] = sc.nextInt() - 1;

        ArrayList<Integer>[] graph = new ArrayList[N];
        for (int i = 0; i < N; i++)
            graph[i] = new ArrayList<>();
        for (int i = 0; i < M; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            graph[a].add(b);
            graph[b].add(a);
        }

        int T = N + K + 1;
        int n = N * T + 1;
        int m = K + (M * 2 * K + N) * (T - 1);
        MinCostFlow mcf = new MinCostFlow(n, m);

        for (int i = 0; i < N; i++) {
            for (int s = 0; s < T - 1; s++) {
                int u = i * T + s;
                for (int j : graph[i]) {
                    int v = j * T + s + 1;
                    for (int x = 1; x <= K; x++)
                        mcf.link(u, v, 1, C + (x * 2 - 1) * D);
                }
            }
        }

        for (int i = 0; i < N; i++)
            for (int s = 0; s < T - 1; s++) {
                int u = i * T + s, v = u + 1;
                mcf.link(u, v, K, i == 0 ? 0 : C);
            }

        for (int h = 0; h < K; h++)
            mcf.link(n - 1, start[h] * T, 1, 0);

        System.out.println(mcf.edmonds_karp(n - 1, 0 * T + T - 1));
    }
}

import java.io.*;
import java.util.*;

public class CF1187G {
    static final int INF = 0x3f3f3f3f;
    ArrayList<Integer>[] adj;
    int n, m;
    int[] pi, dd, bb;
    int[] uu, vv, uv, cost;
    int[] cap;
    int[] qq;
    int head, cnt;
    boolean[] inq;

    void init() {
        adj = new ArrayList[n];
        for (int u = 0; u < n; u++)
            adj[u] = new ArrayList<>();
        pi = new int[n];
        dd = new int[n];
        bb = new int[n];
        qq = new int[n + 10];
        inq = new boolean[n];
        uu = new int[m];
        vv = new int[m];
        uv = new int[m];
        cost = new int[m];
        cap = new int[m * 2];
        m = 0;
    }

    void link(int u, int v, int c, int w) {
        int h = m++;
        uu[h] = u;
        vv[h] = v;
        uv[h] = u ^ v;
        cost[h] = w;
        cap[h << 1] = c;
        adj[u].add(h << 1);
        adj[v].add(h << 1 | 1);
    }

    void enqueue(int v) {
        if (inq[v]) return;
        qq[head + cnt++] = v;
        inq[v] = true;
    }

    int dequeue() {
        int u = qq[head++];
        cnt--;
        inq[u] = false;
        return u;
    }

    boolean spfa(int s, int t) {
        Arrays.fill(pi, INF);
        pi[s] = 0;
        head = cnt = 0;
        enqueue(s);
        while (cnt > 0) {
            int u = dequeue();
            int d = dd[u] + 1;
            for (int h_ : adj[u]) {
                if (cap[h_] > 0) {
                    int h = h_ >> 1;
                    int p = pi[u] + ((h_ & 1) == 0 ? cost[h] : -cost[h]);
                    int v = u ^ uv[h];
                    if (pi[v] > p || (pi[v] == p && dd[v] > d)) {
                        pi[v] = p;
                        dd[v] = d;
                        bb[v] = h_;
                        enqueue(v);
                    }
                }
            }
        }
        return pi[t] != INF;
    }

    void push1(int s, int t) {
        for (int u = t, h_, h; u != s; u ^= uv[h]) {
            h = (h_ = bb[u]) >> 1;
            cap[h_]--;
            cap[h_ ^ 1]++;
        }
    }

    int edmonds_karp(int s, int t) {
        while (spfa(s, t))
            push1(s, t);
        int flow = 0;
        for (int h = 0; h < m; h++)
            flow += cost[h] * cap[h << 1 | 1];
        return flow;
    }

    void solve() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) != null) {
            String[] parts = line.split(" ");
            int N = Integer.parseInt(parts[0]);
            int M = Integer.parseInt(parts[1]);
            int K = Integer.parseInt(parts[2]);
            int C = Integer.parseInt(parts[3]);
            int D = Integer.parseInt(parts[4]);

            int[] start = new int[K];
            parts = br.readLine().split(" ");
            for (int i = 0; i < K; i++)
                start[i] = Integer.parseInt(parts[i]) - 1;

            ArrayList<Integer>[] graph = new ArrayList[N];
            for (int i = 0; i < N; i++)
                graph[i] = new ArrayList<>();
            for (int i = 0; i < M; i++) {
                parts = br.readLine().split(" ");
                int a = Integer.parseInt(parts[0]) - 1;
                int b = Integer.parseInt(parts[1]) - 1;
                graph[a].add(b);
                graph[b].add(a);
            }

            int T = N + K + 1;
            n = N * T + 1;
            m = K + (M * 2 * K + N) * (T - 1);
            init();

            for (int i = 0; i < N; i++) {
                for (int s = 0; s < T - 1; s++) {
                    int u = i * T + s;
                    for (int j : graph[i]) {
                        int v = j * T + s + 1;
                        for (int x = 1; x <= K; x++)
                            link(u, v, 1, C + (x * 2 - 1) * D);
                    }
                }
            }

            for (int i = 0; i < N; i++)
                for (int s = 0; s < T - 1; s++) {
                    int u = i * T + s, v = u + 1;
                    link(u, v, K, i == 0 ? 0 : C);
                }

            for (int h = 0; h < K; h++)
                link(n - 1, start[h] * T, 1, 0);

            System.out.println(edmonds_karp(n - 1, 0 * T + T - 1));
        }
    }

    public static void main(String[] args) throws IOException {
        new CF1187G().solve();
    }
}

