    static class TaskE {
        class MinCostMaxFlow{
            int N, S, T, maxFlow, minCost;
            final int gmax = Integer.MAX_VALUE / 100;
            int[] to, flow, cost, rev;
            int[] head, nextEdge;
            int edgeCount;

            void addEdge(int u, int v, int f, int c){
                to[edgeCount] = v; flow[edgeCount] = f; cost[edgeCount] = c; rev[edgeCount] = edgeCount+1;
                nextEdge[edgeCount] = head[u]; head[u] = edgeCount++;
                to[edgeCount] = u; flow[edgeCount] = 0; cost[edgeCount] = -c; rev[edgeCount] = edgeCount-1;
                nextEdge[edgeCount] = head[v]; head[v] = edgeCount++;
            }

            MinCostMaxFlow(int n, int source, int sink){
                N = n; S = source; T = sink; maxFlow = 0; minCost = 0;
