            boolean dijkstra(){
                visit = new int[N];
                prv = new int[N];
                prve = new int[N];
                dist = new int[N];
                Arrays.fill(dist, gmax);
                PriorityQueue<int[]> pq = new PriorityQueue<>((a,b) -> Integer.compare(a[1], b[1]));
                pq.add(new int[]{S, 0});
                dist[S] = 0;
                while(!pq.isEmpty()){
                    int[] cur = pq.poll();
                    int u = cur[0];
                    if(cur[1] != dist[u]) continue;
                    visit[u] = 2;
                    for(int e = head[u]; e != -1; e = nextEdge[e]){
                        if(flow[e] == 0) continue;
                        int v = to[e];
                        int nd = dist[u] + cost[e] + d[u] - d[v];
                        if(nd < dist[v]){
                            if(visit[v] == 2) return false;
                            dist[v] = nd;
                            prv[v] = u;
                            prve[v] = e;
                            pq.add(new int[]{v, nd});
                            visit[v] = 1;
                        }
                    }
                }
                return visit[T] != 0;
            }

            int augment(){
                int p = T, min = gmax;
                while(p != S){
                    int e = prve[p];
                    min = Math.min(min, flow[e]);
                    p = prv[p];
                }
                p = T;
                while(p != S){
                    int e = prve[p];
                    flow[e] -= min;
                    flow[rev[e]] += min;
                    p = prv[p];
                }
                maxFlow += min;
