                al = new ArrayList[N];
                d = new int[N];
                for(int i = 0; i < N; i++){
                    al[i] = new ArrayList<>();
                }
            }

            boolean BellmanFord(boolean check){
                d[0] = 0;
                for(int i = 0; i < N - 1; i++){
                    for(int j = 0; j < N; j++){
                        for(Edge e : ja[j]){
                            if(e.flow == 0)continue;
                            d[e.u] = Math.min(d[e.u] , d[j] + e.cost);
                        }
                    }
                }
                if(check){
                    for(int j = 0; j < N; j++){
                        for(Edge e : ja[j]){
                            if(e.flow == 0)continue;
                            if(d[j] + e.cost < d[e.u]) return false;
                        }
                    }   
                }return true;
            }

            int node[]; 
            int visit[]; 
            int prv[], prve[]; 
            int dist[]; 

            boolean simple(){
                node = new int[N]; 
                visit = new int[N]; 
                prv = new int[N];
                prve = new int[N];
                dist = new int[N];   Arrays.fill(dist , gmax);

                node[0] = S; dist[0] = 0;
                int front = 1, back = 0;
                while(front != back){
                    int u = node[back++]; int distu = dist[u];
                    if(back == N)back = 0;
                    visit[u] = 2;
                    for(int i = 0; i < ja[u].length; i++){
                        Edge e = ja[u][i];
