                        int cdist = distu + e.cost;
                        if(cdist < dist[e.u]){
                            if(visit[e.u] == 0){
                                node[front] = e.u; 
                                if(++front == N)front = 0;
                            }else if(visit[e.u] == 2){
                                if(--back == -1)back += N;
                                node[back] = e.u;
                            }
