    List<Edge>[] graph;
    int n_, m_;
    int[] pi, dd, bb;
    int[] cc;
    class Edge {
        int to, rev, cap, cost;
        Edge(int t, int r, int ca, int co) { to = t; rev = r; cap = ca; cost = co; }
    }
    void init() {
        graph = new List[n_];
        for (int i = 0; i < n_; i++) graph[i] = new ArrayList<>();
        pi = new int[n_];
        dd = new int[n_];
        bb = new int[n_];
        m_ = 0;
    }
    void link(int u, int v, int cap, int cos) {
        graph[u].add(new Edge(v, graph[v].size(), cap, cos));
        graph[v].add(new Edge(u, graph[u].size() - 1, 0, -cos));
        m_++;
    }
    LinkedList<Integer> qq;
    boolean[] iq;
    void enqueue(int v) {
        if (iq[v]) return;
        iq[v] = true;
        qq.addLast(v);
    }
    int dequeue() {
        int u = qq.removeFirst();
        iq[u] = false;
        return u;
    }
    boolean spfa(int s, int t) {
        Arrays.fill(pi, INF);
        pi[s] = 0;
        qq = new LinkedList<>();
        iq = new boolean[n_];
        enqueue(s);
        while (!qq.isEmpty()) {
            int u = dequeue();
            int d = dd[u] + 1;
            for (int i = 0; i < graph[u].size(); i++) {
                Edge e = graph[u].get(i);
                if (e.cap > 0) {
                    int p = pi[u] + e.cost;
                    int v = e.to;
                    if (pi[v] > p || (pi[v] == p && dd[v] > d)) {
                        pi[v] = p;
                        dd[v] = d;
                        bb[v] = i;
                        enqueue(v);
                    }
                }
            }
        }
        return pi[t] != INF;
    }
    void push1(int s, int t) {
        for (int u = t; u != s; ) {
            Edge e = graph[u].get(bb[u]);
            e.cap++;
            graph[e.to].get(e.rev).cap--;
            u = e.to;
        }
    }
    int edmonds_karp(int s, int t) {
        while (spfa(s, t))
            push1(s, t);
        int c = 0;
        for (int u = 0; u < n_; u++)
            for (Edge e : graph[u])
                if (e.cost > 0)
                    c += e.cost * e.cap;
        return c;
    }
