        if (qt == qq.length) qt = 0;
    }
    int dequeue() {
        int u = qq[qh++];
        if (qh == qq.length) qh = 0;
        iq[u] = false;
        return u;
    }
    boolean spfa(int s, int t) {
        Arrays.fill(pi, INF);
        pi[s] = 0;
        qh = qt = 0;
        iq = new boolean[n_];
        enqueue(s);
        while (qh != qt) {
            int u = dequeue();
            int d = dd[u] + 1;
            for (int e = head[u]; e != -1; e = nxt[e]) {
                if (cap[e] > 0) {
                    int p = pi[u] + cost[e];
                    int v = to[e];
                    if (pi[v] > p || (pi[v] == p && dd[v] > d)) {
                        pi[v] = p;
                        dd[v] = d;
                        bb[v] = e;
                        enqueue(v);
                    }
                }
            }
        }
        return pi[t] != INF;
    }
    void push1(int s, int t) {
        for (int u = t; u != s; u = to[bb[u] ^ 1]) {
            cap[bb[u]]--;
            cap[bb[u] ^ 1]++;
        }
    }
    int edmonds_karp(int s, int t) {
        while (spfa(s, t))
            push1(s, t);
        int c = 0;
        for (int e = 0; e < tot; e += 2)
            c += cost[e] * cap[e ^ 1];
        return c;
    }
    void main() {
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();
        int[] ii = new int[k];
        for (int h = 0; h < k; h++)
            ii[h] = sc.nextInt() - 1;
        int[][] aa = new int[n][];
        int[] deg = new int[n];
        int[] tmp = new int[m * 2];
        int idx = 0;
        for (int h = 0; h < m; h++) {
            int i = sc.nextInt() - 1;
            int j = sc.nextInt() - 1;
            tmp[idx++] = j;
            tmp[idx++] = i;
            deg[i]++; deg[j]++;
        }
        for (int i = 0; i < n; i++) {
            aa[i] = new int[deg[i]];
            int p = 0;
            for (int h = 0; h < idx; h += 2) {
                if (tmp[h] == i) aa[i][p++] = tmp[h+1];
                else if (tmp[h+1] == i) aa[i][p++] = tmp[h];
            }
        }
        int t = n + k + 1;
        n_ = n * t + 1;
        m_ = k + (m * 2 * k + n) * (t - 1);
        init();
        for (int i = 0; i < n; i++) {
            for (int s = 0; s < t - 1; s++) {
                int u = i * t + s;
                for (int j : aa[i]) {
                    int v = j * t + s + 1;
                    for (int x = 1; x <= k; x++)
                        link(u, v, 1, c + (x * 2 - 1) * d);
                }
            }
        }
        for (int i = 0; i < n; i++)
            for (int s = 0; s < t - 1; s++) {
                int u = i * t + s, v = u + 1;
                link(u, v, k, i == 0 ? 0 : c);
            }
        for (int h = 0; h < k; h++)
            link(n_ - 1, ii[h] * t + 0, 1, 0);
        println(edmonds_karp(n_ - 1, 0 * t + t - 1));
    }
}

