    void push1(int s, int t) {
        for (int u = t, h_, h; u != s; u ^= uv[h]) {
            h = (h_ = bb[u]) >> 1;
            cc[h_]--; cc[h_ ^ 1]++;
        }
    }
    int edmonds_karp(int s, int t) {
        while (bellman_ford(s, t))
            push1(s, t);
        int c = 0;
        for (int h = 0; h < m_; h++)
            c += cost[h] * cc[h << 1 ^ 1];
