                // Bellman-Ford (SPFA) with queue
                boolean[] inQueue = new boolean[n];
                Queue<Integer> q = new LinkedList<Integer>();
                q.add(source);
                inQueue[source] = true;
                while (!q.isEmpty()) {
                    int v = q.poll();
                    inQueue[v] = false;
                    for (Edge e : nodes.get(v).edges) {
                        if (e.capacity > e.flow && dist[e.to.index] > dist[v] + e.cost) {
                            dist[e.to.index] = dist[v] + e.cost;
                            parent[e.to.index] = e;
                            if (!inQueue[e.to.index]) {
                                q.add(e.to.index);
                                inQueue[e.to.index] = true;
                            }
                        }
                    }
                }
                if (parent[sink] == null) break;
                long augFlow = Long.MAX_VALUE;
                for (int i = sink; i != source; i = parent[i].from.index)
                    augFlow = Math.min(augFlow, parent[i].capacity - parent[i].flow);
                for (int i = sink; i != source; i = parent[i].from.index) {
                    Edge e = parent[i];
                    e.addFlow(augFlow);
                    cost += augFlow * e.cost;
                }
                flow += augFlow;
            }
            minCost = cost;
            return flow;
        }
    }

