            for(int j = 0; j < K; j++) {
                solver.link(timeNodes[0][i], snk, 1, C*i-C);
            }
        }
        for(int i =0; i < M; i++) {
            int a = scanner.nextInt()-1;
            int b = scanner.nextInt()-1;
            for(int j = 1; j < amt-1; j++) {
                int prev = 0;
                for(int k = 1; k <= K; k++) {
                    solver.link(timeNodes[a][j], timeNodes[b][j + 1], 1, D*k*k- prev);
                    solver.link(timeNodes[b][j], timeNodes[a][j + 1], 1, D*k*k - prev);
                    prev = D * k * k;
                }
            }
        }
        long[] ret = solver.getMinCostMaxFlow(src, snk);
        out.println(ret[1]);
        out.flush();
    }

    public static class Node {
        private Node() { }
        List<Edge> edges = new ArrayList<Edge>();
        int index;
    }

    public static class Edge {
        boolean forward;
        Node from, to;
        long flow;
        final long capacity;
        Edge dual;
        long cost;
        protected Edge(Node s, Node d, long c, boolean f) {
            forward = f;
            from = s;
            to = d;
            capacity = c;
        }
        long remaining() { return capacity - flow; }
        void addFlow(long amount) {
            flow += amount;
            dual.flow -= amount;
        }
    }

    public static abstract class MaxFlowSolver {
        List<Node> nodes = new ArrayList<Node>();

        public void link(Node n1, Node n2, long capacity) {
            link(n1, n2, capacity, 1);
        }

        public void link(Node n1, Node n2, long capacity, long cost) {
            Edge e12 = new Edge(n1, n2, capacity, true);
            Edge e21 = new Edge(n2, n1, 0, false);
            e12.dual = e21;
            e21.dual = e12;
            n1.edges.add(e12);
            n2.edges.add(e21);
            e12.cost = cost;
            e21.cost = -cost;
        }
        void link(int n1, int n2, long capacity) {
            link(nodes.get(n1), nodes.get(n2), capacity);
        }
        protected MaxFlowSolver(int n) {
            for (int i = 0; i < n; i++) addNode();
        }
        protected MaxFlowSolver() { this(0); }

        public abstract long getMaxFlow(Node src, Node snk);
        public Node addNode() {
            Node n = new Node();
            n.index = nodes.size();
            nodes.add(n);
            return n;
        }
    }
    static abstract class MinCostMaxFlowSolver extends MaxFlowSolver {
        abstract long [] getMinCostMaxFlow(Node src, Node snk);
        MinCostMaxFlowSolver ()      { this(0); }
        MinCostMaxFlowSolver (int n) { super(n); }
    }

    static class EdmondsKarp extends MinCostMaxFlowSolver {
        EdmondsKarp ()      { this(0); }
        EdmondsKarp (int n) { super(n); }
        long minCost;

        @Override
        public long [] getMinCostMaxFlow(Node src, Node snk) {
            long maxflow = getMaxFlow(src, snk);
            return new long [] { maxflow, minCost };
        }
        static final long INF = Long.MAX_VALUE/4;

        @Override
        public long getMaxFlow(Node src, Node snk) {
            final int n = nodes.size();
            final int source = src.index;
            final int sink = snk.index;
            long flow = 0;
            long cost = 0;
            long[] potential = new long[n];
            while (true) {
                Edge[] parent = new Edge[n];
                long[] dist = new long[n];
                Arrays.fill(dist, INF);
                dist[source] = 0;
                // Use a custom binary heap instead of PriorityQueue
                BinaryHeap<Item> heap = new BinaryHeap<Item>();
                heap.add(new Item(0, source));
                while (!heap.isEmpty()) {
                    Item item = heap.poll();
                    if (item.dist != dist[item.v]) continue;
                    for (Edge e : nodes.get(item.v).edges) {
                        long temp = dist[item.v] + e.cost + potential[item.v] - potential[e.to.index];
                        if (e.capacity > e.flow && dist[e.to.index] > temp) {
                            dist[e.to.index] = temp;
                            parent[e.to.index] = e;
                            heap.add(new Item(temp, e.to.index));
                        }
                    }
                }
                if (parent[sink] == null) break;
                for (int i = 0; i < n; i++)
                    if (parent[i] != null) potential[i] += dist[i];
                long augFlow = Long.MAX_VALUE;
                for (int i = sink; i != source; i = parent[i].from.index)
                    augFlow = Math.min(augFlow, parent[i].capacity - parent[i].flow);
                for (int i = sink; i != source; i = parent[i].from.index) {
                    Edge e = parent[i];
                    e.addFlow(augFlow);
                    cost += augFlow * e.cost;
                }
                flow += augFlow;
            }
            minCost = cost;
            return flow;
        }

        static class Item implements Comparable<Item> {
            long dist;
            int v;
            public Item(long dist, int v) { this.dist = dist; this.v = v; }
            public int compareTo(Item that) { return Long.compare(this.dist, that.dist); }
        }

        // Simple binary heap implementation
        static class BinaryHeap<T extends Comparable<T>> {
            List<T> heap = new ArrayList<T>();
            void add(T e) {
                heap.add(e);
                int i = heap.size()-1;
                while (i > 0) {
                    int p = (i-1)/2;
                    if (heap.get(i).compareTo(heap.get(p)) >= 0) break;
                    Collections.swap(heap, i, p);
                    i = p;
                }
            }
            T poll() {
                if (heap.isEmpty()) return null;
                T result = heap.get(0);
                T last = heap.remove(heap.size()-1);
                if (!heap.isEmpty()) {
                    heap.set(0, last);
                    int i = 0;
                    int n = heap.size();
                    while (true) {
                        int left = 2*i+1;
                        int right = 2*i+2;
                        int smallest = i;
                        if (left < n && heap.get(left).compareTo(heap.get(smallest)) < 0) smallest = left;
                        if (right < n && heap.get(right).compareTo(heap.get(smallest)) < 0) smallest = right;
                        if (smallest == i) break;
                        Collections.swap(heap, i, smallest);
                        i = smallest;
                    }
                }
                return result;
            }
            boolean isEmpty() { return heap.isEmpty(); }
        }
    }

