                adj[u].add(new Edge(v, flow, cost, lv));
                adj[v].add(new Edge(u, 0, -cost, lu));
            }
            void toArray(){
                mat = new Edge[N][];
                for(int i = 0; i < N; i++){
                    int sz = adj[i].size();
                    mat[i] = new Edge[sz];
                    for(int j = 0; j < sz; j++){
                        mat[i][j] = adj[i].get(j);
                    }
                    adj[i].clear();
                }
            }
            MinCostMaxFlow2(int n, int source, int sink){
                N = n; S = source; T = sink; maxFlow = 0; minCost = 0;
                adj = new ArrayList[N];
                pot = new int[N];
                for(int i = 0; i < N; i++) adj[i] = new ArrayList<>();
            }
            boolean bellmanFord(boolean check){
                pot[0] = 0;
                for(int i = 0; i < N-1; i++){
                    for(int j = 0; j < N; j++){
                        for(Edge e : mat[j]){
                            if(e.flow == 0) continue;
                            pot[e.to] = Math.min(pot[e.to], pot[j] + e.cost);
                        }
                    }
                }
                if(check){
                    for(int j = 0; j < N; j++){
                        for(Edge e : mat[j]){
                            if(e.flow == 0) continue;
                            if(pot[j] + e.cost < pot[e.to]) return false;
                        }
                    }
                }
                return true;
            }
            int queue[];
            int vis[];
            int prev[], preve[];
            int dist[];
            boolean simple(){
                queue = new int[N];
                vis = new int[N];
                prev = new int[N];
                preve = new int[N];
                dist = new int[N];
                Arrays.fill(dist, INF);
                queue[0] = S; dist[0] = 0;
                int front = 1, back = 0;
                while(front != back){
                    int u = queue[back++];
                    if(back == N) back = 0;
                    vis[u] = 2;
                    for(int i = 0; i < mat[u].length; i++){
                        Edge e = mat[u][i];
                        if(e.flow == 0) continue;
                        int nd = dist[u] + e.cost;
                        if(nd < dist[e.to]){
                            if(vis[e.to] == 0){
                                queue[front] = e.to;
                                if(++front == N) front = 0;
                            } else if(vis[e.to] == 2){
                                if(--back == -1) back += N;
                                queue[back] = e.to;
                            }
                            vis[e.to] = 1;
                            preve[e.to] = i; prev[e.to] = u; dist[e.to] = nd;
                        }
                    }
                }
                return vis[T] != 0;
            }
            class Pair{
                int first, second;
                Pair(int a, int b){first = a; second = b;}
            }
            boolean dijkstra(){
                vis = new int[N];
                prev = new int[N];
                preve = new int[N];
                dist = new int[N];
                Arrays.fill(dist, INF);
                PriorityQueue<Pair> pq = new PriorityQueue<>((A,B) -> Integer.compare(A.second, B.second));
                pq.add(new Pair(S, 0)); dist[0] = 0;
                outer: while(!pq.isEmpty()){
                    Pair p = pq.poll();
                    while(dist[p.first] < p.second){
                        if(pq.isEmpty()) break outer;
                        p = pq.poll();
                    }
                    vis[p.first] = 2;
                    for(int i = 0; i < mat[p.first].length; i++){
                        Edge e = mat[p.first][i];
                        if(e.flow == 0) continue;
                        int nd = p.second + (e.cost + pot[p.first] - pot[e.to]);
                        if(nd < dist[e.to]){
                            if(vis[e.to] == 2) return false;
                            pq.add(new Pair(e.to, nd));
                            dist[e.to] = nd; prev[e.to] = p.first; preve[e.to] = i;
                            vis[e.to] = 1;
                        }
                    }
                }
                return vis[T] != 0;
            }
            int augment(){
                int p = T, min = INF;
                while(p != 0){
                    int pp = prev[p], pe = preve[p];
                    min = Math.min(min, mat[pp][pe].flow);
                    p = pp;
                }
                p = T;
                while(p != 0){
                    int pp = prev[p], pe = preve[p];
                    mat[pp][pe].flow -= min;
                    mat[p][mat[pp][pe].rev].flow += min;
                    p = pp;
                }
                maxFlow += min;
                return min;
            }
            boolean calSimple(){
                while(simple()){
                    minCost += dist[T] * augment();
                }
                return true;
            }
            void updPot(){
                for(int i = 0; i < N; i++){
                    if(vis[i] != 0){
                        pot[i] += dist[i] - dist[S];
                    }
                }
            }
            boolean calWithPotential(){
                while(dijkstra()){
                    int min = dist[T] + pot[T] - pot[S];
                    minCost += min * augment();
                    updPot();
                }
                return true;
            }
        }
