                g[u].add(new Edge(v, flow, cost, lv));
                g[v].add(new Edge(u, 0, -cost, lu));
            }
            void toArray(){
                mat = new Edge[N][];
                for(int i=0;i<N;i++){
                    int sz = g[i].size();
                    mat[i] = new Edge[sz];
                    for(int j=0;j<sz;j++) mat[i][j] = g[i].get(j);
                    g[i].clear();
                }
            }
            MCMF(int n, int s, int t){
                N=n; S=s; T=t; maxFlow=0; minCost=0;
                g = new ArrayList[N];
                pot = new int[N];
                for(int i=0;i<N;i++) g[i]=new ArrayList<>();
            }
            boolean bellmanFord(boolean check){
                pot[0]=0;
                for(int i=0;i<N-1;i++){
                    for(int j=0;j<N;j++){
                        for(Edge e: mat[j]){
                            if(e.flow==0) continue;
                            pot[e.to] = Math.min(pot[e.to], pot[j]+e.cost);
                        }
                    }
                }
                if(check){
                    for(int j=0;j<N;j++){
                        for(Edge e: mat[j]){
                            if(e.flow==0) continue;
                            if(pot[j]+e.cost < pot[e.to]) return false;
                        }
                    }
                }
                return true;
            }
            int q[];
            int vis[];
            int prev[], preve[];
            int dist[];
            boolean simple(){
                q = new int[N];
                vis = new int[N];
                prev = new int[N];
                preve = new int[N];
                dist = new int[N];
                Arrays.fill(dist, INF);
                q[0]=S; dist[0]=0;
                int front=1, back=0;
                while(front!=back){
                    int u = q[back++];
                    if(back==N) back=0;
                    vis[u]=2;
                    for(int i=0;i<mat[u].length;i++){
                        Edge e = mat[u][i];
                        if(e.flow==0) continue;
                        int nd = dist[u] + e.cost;
                        if(nd < dist[e.to]){
                            if(vis[e.to]==0){
                                q[front]=e.to;
                                if(++front==N) front=0;
                            } else if(vis[e.to]==2){
                                if(--back==-1) back+=N;
                                q[back]=e.to;
                            }
                            vis[e.to]=1;
                            preve[e.to]=i; prev[e.to]=u; dist[e.to]=nd;
                        }
                    }
                }
