                    if(vis[i]!=0){
                        pot[i] += dist[i] - dist[S];
                    }
                }
            }
            boolean calWithPotential(){
                while(dijkstra()){
                    int min = dist[T] + pot[T] - pot[S];
                    minCost += min * augment();
                    updPot();
                }
                return true;
            }
        }
