import java.util.Scanner;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    public void run() {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        System.out.println(f(n));
    }

    long f(long n) {
        int Len = (int) 4e5;
        long[] pi_upper = new long[Len];
        long[] pi_lower = new long[Len];
        for (int i = 1; i < Len; ++i) {
            pi_lower[i] = i;
            pi_upper[i] = n / i;
        }
        boolean[] isPrime = new boolean[Len];
        Arrays.fill(isPrime, true);
        isPrime[0] = false;
        isPrime[1] = false;
        int[] primeList = new int[Len];
        int primeCount = 0;
        for (int i = 2; i < Len; ++i) {
            if (isPrime[i]) {
                primeList[primeCount++] = i;
                for (int j = i * 2; j < Len; j += i) {
                    isPrime[j] = false;
                }
            }
        }
        for (int t = 0; t < primeCount; ++t) {
            int p = primeList[t];
            long p2 = (long) p * p;
            for (int i = 1; i < Len && n / i >= p2; ++i) {
                long key = (long) p * i;
                if (key < Len) {
                    pi_upper[i] -= pi_upper[(int) key] - (t + 1);
                } else {
                    pi_upper[i] -= pi_lower[(int) (n / i / p)] - (t + 1);
                }
            }
            for (int i = Len - 1; i >= p2; --i) {
                pi_lower[i] -= pi_lower[i / p] - (t + 1);
            }
        }
        long ans = 0;
        for (int idx = 0; idx < primeCount; ++idx) {
            long p = primeList[idx];
            if (p * p > n) break;
            if (p * p * p <= n && p * p * p > 0) {
                ++ans;
            }
            if (n / p > p) {
                if (p < Len)
                    ans += pi_upper[(int) p] - pi_lower[(int) p];
                else
                    ans += pi_lower[(int) (n / p)] - pi_lower[(int) p];
            }
        }
        return ans;
    }

    void tr(Object... objects) {
        System.out.println(Arrays.deepToString(objects));
    }
}

