	}

	static class PrimeCounter {
		int[] primes;
		int[] xcums;
		long[] isp;

		int cachelimit;
		LongHashCounterL picache;
		LongHashCounterL phicache;
		boolean cachePhi = false;

		int[][] cumps;
		int[] FP = { 2, 3, 5, 7, 11, 13, 17, 19 };
		int M = FP.length;

		int B = 100;

		public PrimeCounter(long n) {
			assert n >= 4;
			picache = new LongHashCounterL();
			phicache = new LongHashCounterL();

			int s = (int) Math.sqrt(n) * B;
			cachelimit = s;
			this.primes = sieveEratosthenes(s);
			xcums = new int[(s >>> 6) + 1];
			isp = new long[(s >>> 6) + 1];
			for (int p : primes)
				isp[p >>> 6] |= 1L << p;
			for (int i = 0; i < xcums.length - 1; i++)
				xcums[i + 1] = xcums[i] + Long.bitCount(isp[i]);

			cumps = new int[M][];
			boolean[] b = { true };
			int len = 1;
			for (int i = 0; i < M; i++) {
				len *= FP[i];
