            if (A > 0 && A - 1 < M) {
                return cumps[A - 1][FP[A - 1]] * (x / FP[A - 1]) + cumps[A - 1][(int) (x % FP[A - 1] + 1)];
            }
            if (A > 0 && x <= (long) primes[A - 1] * primes[A - 1]) {
                return pi(x) - A + 1;
