import java.io.*;
import java.math.BigInteger;

public class Main implements Runnable {
    public static void main(String[] args) {
        new Main().run();
    }
    BigInteger mod = BigInteger.valueOf(998244353);
    private void solve() throws Exception {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        int n = in.nextInt(), k = in.nextInt(), l = in.nextInt();
        BigInteger[] fac = new BigInteger[n + 1];
        fac[0] = BigInteger.ONE;
        for (int i = 1; i <= n; i++) {
            fac[i] = fac[i - 1].multiply(BigInteger.valueOf(i)).mod(mod);
        }
        BigInteger[][] dp = new BigInteger[2 * n + 1][2 * n + 2];
        for (int i = 0; i <= 2 * n; i++) {
            for (int j = 0; j <= 2 * n + 1; j++) {
                dp[i][j] = BigInteger.ZERO;
            }
        }
        dp[0][0] = BigInteger.ONE;
        for (int i = 1; i <= 2 * n; i++) {
            for (int j = 0; j <= i; j++) {
                if (j > 0) dp[i][j] = dp[i][j].add(dp[i - 1][j - 1]).mod(mod);
                dp[i][j] = dp[i][j].add(dp[i - 1][j + 1].multiply(BigInteger.valueOf(j + 1))).mod(mod);
            }
        }
        BigInteger ans = BigInteger.ZERO;
        for (int i = k; i <= 2 * n; i++) {
            for (int j = k; j <= n; j++) {
                ans = ans.add(dp[i][j].multiply(dp[2 * n - i][j]).mod(mod).multiply(fac[j]).mod(mod)).mod(mod);
            }
        }
        BigInteger result = BigInteger.valueOf(l).multiply(ans).mod(mod)
                .multiply(dp[2 * n][0].modPow(mod.subtract(BigInteger.valueOf(2)), mod)).mod(mod)
                .multiply(BigInteger.valueOf(2 * n + 1).modPow(mod.subtract(BigInteger.valueOf(2)), mod)).mod(mod);
        out.println(result);
        out.flush();
    }
    @Override
    public void run() {
        try {
            solve();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
    class InputReader {
        StreamTokenizer tokenizer;
        public InputReader(InputStream stream) {
            tokenizer = new StreamTokenizer(new BufferedReader(new InputStreamReader(stream)));
            tokenizer.ordinaryChars(33, 126);
            tokenizer.wordChars(33, 126);
        }
        public String next() throws IOException {
            tokenizer.nextToken();
            return tokenizer.sval;
        }
        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
        public boolean hasNext() throws IOException {
            int res = tokenizer.nextToken();
            tokenizer.pushBack();
            return res != tokenizer.TT_EOF;
        }
    }
}

