        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        int k = Integer.parseInt(parts[1]);
        int l = Integer.parseInt(parts[2]);
        final int MOD = 998244353;
        long[] fac = new long[n + 1];
        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = fac[i - 1] * i % MOD;
        }
        long[][] dp = new long[2 * n + 1][2 * n + 2];
        dp[0][0] = 1;
        for (int i = 1; i <= 2 * n; i++) {
            for (int j = 0; j <= i; j++) {
                if (j > 0) dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD;
                dp[i][j] = (dp[i][j] + dp[i - 1][j + 1] * (j + 1) % MOD) % MOD;
            }
        }
        long ans = 0;
        for (int i = k; i <= 2 * n; i++) {
            for (int j = k; j <= n; j++) {
                ans = (ans + dp[i][j] * dp[2 * n - i][j] % MOD * fac[j] % MOD) % MOD;
            }
        }
        long invDp = pow(dp[2 * n][0], MOD - 2, MOD);
        long invDen = pow(2 * n + 1, MOD - 2, MOD);
        long result = l * ans % MOD * invDp % MOD * invDen % MOD;
        System.out.println(result);
        br.close();
    }
    static long pow(long a, long b, int mod) {
        long res = 1;
        while (b > 0) {
            if ((b & 1) != 0) res = (res * a) % mod;
            a = (a * a) % mod;
            b >>= 1;
        }
        return res;
    }
}

