    void solve(FastScanner in, PrintWriter out) {
        int n = in.ni(), k = in.ni(), l = in.ni();
        int mod = 998244353;
        long[] invs = new long[2 * n + 3];
        for (int i = 1; i < invs.length; i++) {
            invs[i] = modInv(i, mod);
        }
        long[][] p = new long[2 * n + 1][n + 1];
        p[0][1] = 1;
        for (int i = 1; i < 2 * n; i++) {
            int prevMaxRunning = Math.min(2 * n - i, i);
            int maxRunning = Math.min(2 * n - i - 1, i + 1);
            for (int j = 0; j <= prevMaxRunning; j++) {
                if (p[i - 1][j] != 0) {
                    if (j > 0) {
                        p[i][j - 1] = (p[i][j - 1] + p[i - 1][j] * j % mod * invs[2 * n - i] % mod) % mod;
                    }
                    if (j < maxRunning) {
                        p[i][j + 1] = (p[i][j + 1] + p[i - 1][j] * (2 * n - i - j) % mod * invs[2 * n - i] % mod) % mod;
                    }
                }
            }
        }
        long ans = IntStream.range(0, 2 * n)
            .flatMap(i -> IntStream.rangeClosed(k, n)
                .filter(j -> p[i][j] != 0)
                .map(j -> (int)p[i][j]))
            .asLongStream()
            .reduce(0, (a, b) -> (a + b) % mod);
        ans = ans * l % mod * invs[2 * n + 1] % mod;
        out.println(ans);
    }

    private long modInv(long a, long mod) {
        long t = 0, newt = 1, r = mod, newr = a;
        while (newr != 0) {
            long q = r / newr;
            long temp = t - q * newt;
            t = newt;
            newt = temp;
            temp = r - q * newr;
            r = newr;
            newr = temp;
        }
        if (r > 1) throw new RuntimeException("Not invertible");
        if (t < 0) t += mod;
        return t;
    }

    static class FastScanner {
        private BufferedReader in;
        private StringTokenizer st;

        public FastScanner(InputStream stream) {
            in = new BufferedReader(new InputStreamReader(stream));
        }

