public class Codeforces1153F_v4 {

    public static void main(String[] args) throws IOException {
        int P = 998244353;

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int real_k = Integer.parseInt(st.nextToken());
        int l = Integer.parseInt(st.nextToken());

        int[] fact = new int[2*n+2];
        fact[0] = 1;
        for (int i = 1; i <= 2*n+1; i++) {
            fact[i] = (int)(((long)fact[i-1] * i) % P);
        }

        int[] doublefact = new int[n+1];
        doublefact[0] = 1;
        for (int i = 1; i <= n; i++) {
            doublefact[i] = (int)(((long)doublefact[i-1] * (2*i-1)) % P);
        }

        // Precompute inverses using extended Euclidean algorithm (original style)
        int[] invFact = new int[2*n+2];
        for (int i = 0; i <= 2*n+1; i++) {
            invFact[i] = inverse(fact[i], P);
        }
        int invDoublefactN = inverse(doublefact[n], P);

        int ans = 0;
        for (int r = 1; r <= 2*n+1; r++) {
            for (int k = 1; k <= n; k++) {
                if (((r%2) != (k%2)) && (r-1 >= k) && (2*n+1-r >= k)) {
                    int num = (int)(((long)fact[r-1] * fact[2*n+1-r]) % P);
                    num = (int)(((long)num * doublefact[(r-k-1)/2]) % P);
                    num = (int)(((long)num * doublefact[(2*n+1-r-k)/2]) % P);

                    int denom = (int)(((long)fact[r-k-1] * fact[2*n+1-r-k]) % P);
                    denom = (int)(((long)denom * fact[k]) % P);

                    int invDenom = (int)(((long)invFact[r-k-1] * invFact[2*n+1-r-k]) % P);
                    invDenom = (int)(((long)invDenom * invFact[k]) % P);
                    int invTotal = (int)(((long)invDenom * invDoublefactN) % P);

                    int val = (int)(((long)num * invTotal) % P);
                    if (k >= real_k) {
                        ans += val;
                        ans %= P;
                    }
                }
            }
        }

        ans = (int)(((long)ans * l) % P);
        ans = (int)(((long)ans * inverse(2*n+1, P)) % P);

        System.out.println(ans);
    }

    public static int inverse(int a, int n) {
        int m = n;
        int r1 = 1;
        int r2 = 0;
        int r3 = 0;
        int r4 = 1;
        while ((a > 0) && (n > 0)) {
            if (n >= a) {
                r3 -= r1*(n/a);
                r4 -= r2*(n/a);
                n = n%a;
            }
            else {
                int tmp = a;
                a = n;
                n = tmp;
                tmp = r1;
                r1 = r3;
                r3 = tmp;
                tmp = r2;
                r2 = r4;
                r4 = tmp;
            }
        }
        if (a == 0) {
            if (r3 >= 0)
                return (r3%m);
            else
                return (m+(r3%m));
        }
        else {
            if (r1 >= 0)
                return (r1%m);
            else
                return (m+(r1%m));
        }
    }
}

