            fact[i] = multiply(fact[i-1], i, P);
        }

        int[] doublefact = new int[n+1];
        doublefact[0] = 1;
        for (int i = 1; i <= n; i++) {
            doublefact[i] = multiply(doublefact[i-1], (2*i-1), P);
        }

        // Precompute inverses using powMod
        int[] invFact = new int[2*n+2];
        for (int i = 0; i <= 2*n+1; i++) {
            invFact[i] = powMod(fact[i], P-2, P);
        }
        int invDoublefactN = powMod(doublefact[n], P-2, P);

        // Use streams to compute the sum
        int ans = IntStream.rangeClosed(1, 2*n+1)
            .flatMap(r -> IntStream.rangeClosed(1, n)
                .filter(k -> ((r%2) != (k%2)) && (r-1 >= k) && (2*n+1-r >= k))
                .map(k -> {
                    int num = multiply(fact[r-1], fact[2*n+1-r], P);
