                    invDenom = multiply(invDenom, invFact[k], P);
                    int invTotal = multiply(invDenom, invDoublefactN, P);

                    int val = multiply(num, invTotal, P);
                    return (k >= real_k) ? val : 0;
                })
            )
            .reduce(0, (a, b) -> (a + b) % P);

        ans = multiply(ans, l, P);
