public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        int n = in.nextInt();
        int k = in.nextInt();
        int l = in.nextInt();
        int mod = 998244353;
        int maxN = 2 * n + 3;
        long[] invs = new long[maxN];
        for (int i = 1; i < maxN; i++) {
            invs[i] = modPow(i, mod - 2, mod);
        }
        long[][] p = new long[2 * n + 1][n + 1];
        p[0][1] = 1;
        long ans = 0;
        for (int i = 1; i < 2 * n; i++) {
            int prevMax = Math.min(2 * n - i, i);
            int maxRun = Math.min(2 * n - i - 1, i + 1);
            for (int j = 0; j <= prevMax; j++) {
                long val = p[i - 1][j];
                if (val != 0) {
                    if (j > 0) {
                        p[i][j - 1] = (p[i][j - 1] + val * j % mod * invs[2 * n - i] % mod) % mod;
                    }
                    if (j < maxRun) {
                        p[i][j + 1] = (p[i][j + 1] + val * (2 * n - i - j) % mod * invs[2 * n - i] % mod) % mod;
                    }
                    if (j >= k) {
                        ans = (ans + val) % mod;
                    }
                }
            }
        }
        if (k <= 1) {
            ans = (ans + p[2 * n - 1][1]) % mod;
        }
        ans = ans * l % mod * invs[2 * n + 1] % mod;
        out.println(ans);
        out.close();
    }

    static long modPow(long a, long e, long mod) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % mod;
            a = a * a % mod;
            e >>= 1;
        }
        return res;
    }
}

