            invs[1] = 1;
            IntStream.range(2, maxN).forEach(i -> invs[i] = mod - (mod / i) * invs[(int)(mod % i)] % mod);
            long[][] p = new long[2 * n + 1][n + 1];
            p[0][1] = 1;
            long[] ans = {0};
            IntStream.range(1, 2 * n).forEach(i -> {
                int prevMax = Math.min(2 * n - i, i);
                int maxRun = Math.min(2 * n - i - 1, i + 1);
                IntStream.rangeClosed(0, prevMax).forEach(j -> {
                    long val = p[i - 1][j];
                    if (val != 0) {
                        if (j > 0) {
                            p[i][j - 1] = (p[i][j - 1] + val * j % mod * invs[2 * n - i] % mod) % mod;
                        }
                        if (j < maxRun) {
                            p[i][j + 1] = (p[i][j + 1] + val * (2 * n - i - j) % mod * invs[2 * n - i] % mod) % mod;
                        }
                        if (j >= k) {
                            ans[0] = (ans[0] + val) % mod;
                        }
                    }
                });
            });
            if (k <= 1) {
                ans[0] = (ans[0] + p[2 * n - 1][1]) % mod;
            }
            ans[0] = ans[0] * l % mod * invs[2 * n + 1] % mod;
            out.println(ans[0]);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}

