            cnk[0][i] = 1;
            for (int j = 1; j <= i; j++) {
                cnk[j][i] = (cnk[j - 1][i - 1] + cnk[j][i - 1]) % mod;
            }
        }
        // Precompute factorials
        fact[0] = 1;
        for (int i = 1; i < fact.length; i++) {
            fact[i] = fact[i - 1] * i % mod;
        }
        // Precompute powers of 2
        deg2[0] = 1;
        for (int i = 1; i < deg2.length; i++) {
            deg2[i] = deg2[i - 1] * 2 % mod;
        }
        // Precompute reverse for odd indices only
        rev[1] = 1;
        for (int i = 3; i < rev.length; i += 2) {
            rev[i] = binPow(fact[i], mod - 2, mod);
        }

