                a = a * fact[s + i] % mod;
                a = a * rev[2 * (s + i) + 1] % mod;
                tmp = (tmp + sign * a) % mod;
                s++;
                sign = -sign;
            }
            long b = tmp * deg2[i] % mod;
            b = b * cnk[i][n] % mod;
            ans = (ans + b) % mod;
            i++;
        }
        ans = ans * l % mod;
        System.out.println((ans + mod) % mod);
    }

    public static long binPow(long a, long b, long mod) {
        long res = 1;
        while (b != 0) {
            if ((b & 1) == 1) res = res * a % mod;
            a = a * a % mod;
            b >>= 1;
        }
        return res;
    }
