        for (int i = 1; i <= k; i++) fact[i] = fact[i - 1] * i % mod;
        invFact[k] = qmod(fact[k], mod - 2, mod);
        for (int i = k; i >= 1; i--) invFact[i - 1] = invFact[i] * i % mod;
        // Compute Stirling numbers S(k,i) using explicit formula
        long[] S = new long[k + 1];
        for (int i = 1; i <= k; i++) {
            long sum = 0;
            for (int j = 0; j <= i; j++) {
                long term = (j % 2 == 0 ? 1 : mod - 1) * invFact[j] % mod * invFact[i - j] % mod;
                term = term * qmod(i - j, k, mod) % mod;
                sum = (sum + term) % mod;
            }
            S[i] = sum * fact[i] % mod;
        }
        long[] dp = new long[5005];
        dp[0] = 1;
        int limit = (int) Math.min(n, k);
        for (int i = 1; i <= limit; i++) {
