public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long mod = 998244353;
        long n = sc.nextLong();
        long m = sc.nextLong();
        int k = sc.nextInt();
        m = qmod(m, mod - 2, mod);
        // Precompute Stirling numbers as in original (2D array)
        long[][] S = new long[5005][5005];
        S[1][1] = 1;
        S[0][0] = 0;
        for (int i = 1; i <= 5000; i++) {
            S[i][i] = 1;
            S[i][0] = 0;
        }
        for (int i = 2; i <= 5000; i++) {
            for (int j = 1; j <= i; j++) {
                S[i][j] = (S[i - 1][j] * j % mod + S[i - 1][j - 1]) % mod;
            }
        }
        int limit = (int) Math.min(n, k);
        // Compute dp using stream
        long[] dp = new long[limit + 1];
        dp[0] = 1;
        IntStream.rangeClosed(1, limit).forEach(i -> dp[i] = dp[i - 1] * (n - i + 1) % mod);
        // Compute ans using stream
        long ans = IntStream.rangeClosed(1, limit)
            .mapToLong(i -> dp[i] * qmod(m, i, mod) % mod * S[k][i] % mod)
            .reduce(0, (a, b) -> (a + b) % mod);
        System.out.println(ans);
    }
    public static long qmod(long a, long b, long mod) {
        long ans = 1;
        while (b >= 1) {
            if ((b & 1) != 0) {
                ans = ans * a % mod;
            }
            a = a * a % mod;
            b = b >> 1;
        }
        return ans;
    }
}

