        long n = sc.nextLong();
        long m = sc.nextLong();
        int k = sc.nextInt();
        // Use BigInteger for modular inverse and exponentiation
        BigInteger bigMod = BigInteger.valueOf(mod);
        BigInteger bigM = BigInteger.valueOf(m);
        m = bigM.modPow(BigInteger.valueOf(mod - 2), bigMod).longValue();
        // Precompute Stirling numbers as in original
        long[][] S = new long[5005][5005];
        S[1][1] = 1;
        S[0][0] = 0;
        for (int i = 1; i <= 5000; i++) {
            S[i][i] = 1;
            S[i][0] = 0;
        }
        for (int i = 2; i <= 5000; i++) {
            for (int j = 1; j <= i; j++) {
                S[i][j] = (S[i - 1][j] * j % mod + S[i - 1][j - 1]) % mod;
            }
        }
        long[] dp = new long[5005];
        dp[0] = 1;
        int limit = (int) Math.min(n, k);
        for (int i = 1; i <= limit; i++) {
            dp[i] = dp[i - 1] * (n - i + 1) % mod;
        }
        long ans = 0;
        for (int i = 1; i <= limit; i++) {
            long pow = BigInteger.valueOf(m).modPow(BigInteger.valueOf(i), bigMod).longValue();
