import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long mod = 998244353;
        long n = sc.nextLong();
        long m = sc.nextLong();
        int k = sc.nextInt();
        // Compute modular inverse using extended Euclidean algorithm
        m = modInverse(m, mod);
        // Compute Stirling numbers using 1D array and update in place (row by row)
        long[] S = new long[k + 1];
        S[0] = 0;
        if (k >= 1) S[1] = 1;
        for (int i = 2; i <= k; i++) {
            for (int j = i; j >= 1; j--) {
                if (j == i) {
                    S[j] = 1;
                } else {
                    S[j] = (S[j] * j % mod + S[j - 1]) % mod;
                }
            }
        }
        // Compute dp and ans in a single loop without storing dp array
        long ans = 0;
        long dp = 1; // dp[0]
        int limit = (int) Math.min(n, k);
        for (int i = 1; i <= limit; i++) {
            dp = dp * (n - i + 1) % mod;
            long term = dp * qmod(m, i, mod) % mod * S[i] % mod;
            ans = (ans + term) % mod;
        }
        System.out.println(ans);
    }
    // Extended Euclidean algorithm for modular inverse
    public static long modInverse(long a, long mod) {
        long t = 0, newt = 1;
        long r = mod, newr = a;
        while (newr != 0) {
            long quotient = r / newr;
            long temp = t - quotient * newt;
            t = newt;
            newt = temp;
            temp = r - quotient * newr;
            r = newr;
            newr = temp;
        }
        if (r > 1) throw new ArithmeticException("Not invertible");
        if (t < 0) t += mod;
        return t;
    }
    public static long qmod(long a, long b, long mod) {
        long ans = 1;
        while (b >= 1) {
            if ((b & 1) != 0) {
                ans = ans * a % mod;
            }
            a = a * a % mod;
            b = b >> 1;
        }
        return ans;
    }
}

