public class CF1278F_1 {
    static final int MD = 998244353;

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int m = fs.nextInt();
        int k = fs.nextInt();

        int invm = inv(m);

        int[] dp = new int[k + 1];
        dp[0] = 1;

        for (int h = 0; h < k; h++)
            for (int d = k - 1; d >= 0; d--)
                if (dp[d] != 0) {
                    dp[d + 1] = (int) ((dp[d + 1] + (long) dp[d] * (n - d)) % MD);
                    dp[d] = (int) ((long) dp[d] * d % MD);
                }

        long p = 1, ans = 0;
        for (int d = 1; d <= k; d++) {
            p = p * invm % MD;
            ans = (ans + dp[d] * p) % MD;
        }

        System.out.println(ans);
    }

    static int inv(int a) {
        int r0 = a, r1 = MD, s0 = 1, s1 = 0;
        while (r1 != 0) {
            int q = r0 / r1;
            int r2 = r0 - q * r1;
            r0 = r1;
            r1 = r2;
            int s2 = s0 - q * s1;
            s0 = s1;
            s1 = s2;
        }
        return s0 < 0 ? s0 + MD : s0;
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

