        super(System.out, true);
    }

    public static void main(String[] args) {
        CF1278F_3 o = new CF1278F_3();
        o.solve();
        o.flush();
    }

    static final int MD = 998244353;
    int d_, x_, y_;

    void gcd_(int a, int b) {
        if (b == 0) {
            d_ = a;
            x_ = 1;
            y_ = 0;
        } else {
            gcd_(b, a % b);
            int t = x_ - a / b * y_;
            x_ = y_;
            y_ = t;
        }
    }

    int inv(int a) {
        gcd_(a, MD);
        return x_ < 0 ? x_ + MD : x_;
    }

    void solve() {
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int invm = inv(m);

        int[] dp = new int[k + 1];
        int[] ndp = new int[k + 1];
        dp[0] = 1;

        for (int h = 0; h < k; h++) {
            Arrays.fill(ndp, 0);
            for (int j = 0; j <= h + 1; j++) {
                long termA = (long) dp[j] * j % MD;
                long termB = (j == 0) ? 0 : (long) dp[j - 1] * (n - (j - 1));
                ndp[j] = (int) ((termA + termB) % MD);
            }
            int[] tmp = dp;
            dp = ndp;
            ndp = tmp;
        }

        long p = 1, ans = 0;
        for (int d = 1; d <= k; d++) {
            p = p * invm % MD;
            ans = (ans + dp[d] * p) % MD;
        }

