        int lim = Math.min(n, k);
        long[][] dp = new long[2][lim + 1];
        dp[0][0] = 1;
        int cur = 0;
        for (int i = 1; i <= k; i++) {
            int nxt = 1 - cur;
            for (int j = 0; j <= lim; j++) {
                long val = 0;
                if (j > 0) val = (val + dp[cur][j - 1] * (n - j + 1) % mod) % mod;
                val = (val + dp[cur][j] * j % mod) % mod;
                dp[nxt][j] = val;
            }
            cur = nxt;
        }
        long invm = modPow(m, mod - 2, mod);
        long res = 0;
        long prob = 1;
        for (int i = 0; i <= lim; i++) {
            res = (res + dp[cur][i] * prob % mod) % mod;
            prob = prob * invm % mod;
        }
        PrintWriter out = new PrintWriter(System.out, true);
        out.println(res);
        sc.close();
    }

    static long modPow(long x, long y, long mod) {
        long r = 1;
        while (y > 0) {
            if ((y & 1) == 1) r = r * x % mod;
            x = x * x % mod;
            y >>= 1;
        }
        return r;
    }
}

