        n = parseInt(line, idx);
        idx = nextSpace(line, idx) + 1;
        m = parseInt(line, idx);
        idx = nextSpace(line, idx) + 1;
        k = parseInt(line, idx);
        long mod = 998244353;
        int lim = Math.min(n, k);
        long[] dp0 = new long[lim + 1];
        long[] dp1 = new long[lim + 1];
        dp0[0] = 1;
        for (int i = 1; i <= k; i++) {
            for (int j = 0; j <= lim; j++) {
                long val = 0;
                if (j > 0) val = (val + dp0[j - 1] * (n - j + 1) % mod) % mod;
                val = (val + dp0[j] * j % mod) % mod;
                dp1[j] = val;
            }
            long[] tmp = dp0;
            dp0 = dp1;
            dp1 = tmp;
        }
        long invm = modExp(m, mod - 2, mod);
        long res = 0;
        long prob = 1;
        for (int i = 0; i <= lim; i++) {
            res = (res + dp0[i] * prob % mod) % mod;
            prob = prob * invm % mod;
        }
        PrintWriter out = new PrintWriter(System.out);
        out.println(res);
        out.close();
