        long p = modInverse(m, MOD);
        // Compute Stirling numbers using combinatorial formula
        stirling = new long[k+1][k+1];
        for(int i = 0; i <= k; i++){
            for(int j = 0; j <= i; j++){
                if(j == 0 && i == 0) stirling[i][j] = 1;
                else if(j == 0 || i == 0) stirling[i][j] = 0;
                else {
                    long sum = 0;
                    for(int t = 0; t <= j; t++){
                        long term = (comb(j, t) * power(j - t, i, MOD)) % MOD;
                        if(t % 2 == 1) term = MOD - term;
                        sum = (sum + term) % MOD;
                    }
                    stirling[i][j] = (sum * modInverse(fact(j), MOD)) % MOD;
                }
            }
        }
        long val = 1;
        long ans = 0;
        long prob = 1;
        for(int i = k; i > 0; i--){
            val = (val * (n - (k - i))) % MOD;
            prob = (prob * p) % MOD;
            ans = (ans + ((val * prob) % MOD) * stirling[k][k-i+1]) % MOD;
        }
        System.out.println(ans);
    }

    public static long fact(int n){
        long res = 1;
        for(int i=2; i<=n; i++) res = (res * i) % MOD;
        return res;
    }

    public static long comb(int n, int r){
        if(r < 0 || r > n) return 0;
        return (fact(n) * modInverse((fact(r) * fact(n-r)) % MOD, MOD)) % MOD;
    }

    public static long modInverse(long x, long p){
        return power(x, p-2, p);
    }

