        for (int i = 0; i < k; i++) {
            long[] cur = new long[k + 1];
            for (int j = 0; j < k; j++) {
                long v = prev[j];
                cur[j] = plus(cur[j], times(v, j));
                cur[j + 1] = plus(cur[j + 1], times(v, n - j));
            }
            prev = cur;
        }

        long x = inverse(m);
        long poly = 0;
        for (int i = k; i >= 1; i--) {
            poly = times(poly, x);
            poly = plus(poly, prev[i]);
        }
        long ans = times(poly, x);

        System.out.println(ans);
    }
}

