public class Main {
    static final int MOD = 998244353;
    static int add(int a, int b) {
        int c = a + b;
        if (c >= MOD) return c - MOD;
        if (c < 0) return c + MOD;
        return c;
    }
    static int mul(int a, int b) { return (int)((long)a * b % MOD); }
    static int mul(int... x) {
        return IntStream.of(x).reduce(1, (a, b) -> mul(a, b));
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out));
        String[] parts = br.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        int m = Integer.parseInt(parts[1]);
        int k = Integer.parseInt(parts[2]);
        int invm = BigInteger.valueOf(m).modInverse(BigInteger.valueOf(MOD)).intValue();

        // Precompute Stirling numbers up to k using 1D array
        int[] stirPrev = new int[k + 1];
        int[] stirCurr = new int[k + 1];
        stirPrev[0] = 1; // S(0,0)=1
        for (int i = 1; i <= k; i++) {
            stirCurr[0] = 0;
            for (int j = 1; j <= i; j++) {
                stirCurr[j] = add(mul(stirPrev[j], i - 1), stirPrev[j - 1]);
            }
            int[] temp = stirPrev;
            stirPrev = stirCurr;
            stirCurr = temp;
        }
        int[] stir = stirPrev; // S(k, j) for j=0..k

        // Compute pVal using recurrence but with streams for inner sum
        int[] pVal = new int[k + 1];
        pVal[0] = 1;
        int md = n;
        int prp = 1;
        for (int i = 1; i <= k; i++) {
            prp = mul(prp, md, invm);
            md = add(md, -1);
            final int iFinal = i;
            final int prpFinal = prp;
            int sub = IntStream.rangeClosed(1, i - 1)
                .map(j -> mul(stir[iFinal][j], ((iFinal - j) % 2 == 1) ? pVal[j] : add(0, -pVal[j])))
                .reduce(prpFinal, (a, b) -> add(a, b));
            pVal[i] = sub;
        }
        pw.println(pVal[k]);
        pw.close();
    }
}

import java.io.*;
import java.math.BigInteger;

public class Main {
    static final int MOD = 998244353;
    static int add(int a, int b) {
        int c = a + b;
        if (c >= MOD) return c - MOD;
        if (c < 0) return c + MOD;
        return c;
    }
    static int mul(int a, int b) { return (int)((long)a * b % MOD); }
    static int mul(int... x) {
        int r = 1;
        for (int y : x) r = mul(r, y);
        return r;
    }

    // Extended Euclidean algorithm for modular inverse
    static int modInv(int a, int mod) {
        int t = 0, newt = 1;
        int r = mod, newr = a;
        while (newr != 0) {
            int q = r / newr;
            int temp = t - q * newt;
            t = newt;
            newt = temp;
            temp = r - q * newr;
            r = newr;
            newr = temp;
        }
        if (r > 1) throw new ArithmeticException("Not invertible");
        if (t < 0) t += mod;
        return t;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out));
        String[] parts = br.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        int m = Integer.parseInt(parts[1]);
        int k = Integer.parseInt(parts[2]);
        int invm = modInv(m, MOD);

        // Precompute Stirling numbers using 2D array but only up to k
        int[][] stir = new int[k + 1][k + 1];
        for (int i = 0; i <= k; i++) {
            stir[i][0] = 0;
            stir[i][i] = 1;
        }
        for (int i = 2; i <= k; i++) {
            for (int j = 1; j < i; j++) {
                stir[i][j] = add(mul(stir[i - 1][j], i - 1), stir[i - 1][j - 1]);
            }
        }

        // Compute pVal using a different loop order: for each i, compute sum over j
        int[] pVal = new int[k + 1];
        pVal[0] = 1;
        int[] fall = new int[k + 1];
        fall[0] = 1;
        for (int i = 1; i <= k; i++) {
            fall[i] = mul(fall[i - 1], n - i + 1, invm);
            int sum = fall[i];
            for (int j = 1; j < i; j++) {
                int sign = ((i - j) % 2 == 1) ? 1 : -1;
                sum = add(sum, mul(stir[i][j], sign == 1 ? pVal[j] : add(0, -pVal[j])));
            }
            pVal[i] = sum;
        }
        pw.println(pVal[k]);
        pw.close();
    }
}

