        int n = dis.readInt();
        int m = dis.readInt();
        int k = dis.readInt();
        int invm = BigInteger.valueOf(m).modInverse(BigInteger.valueOf(MOD)).intValue();

        // Precompute Stirling numbers using recursion with memoization
        int[][] stir = new int[k + 1][k + 1];
        for (int i = 0; i <= k; i++) Arrays.fill(stir[i], -1);
        for (int i = 0; i <= k; i++) {
            stir[i][0] = 0;
            stir[i][i] = 1;
        }
        for (int i = 2; i <= k; i++) {
            for (int j = 1; j < i; j++) {
                if (stir[i][j] == -1) {
                    stir[i][j] = add(mul(stir[i - 1][j], i - 1), stir[i - 1][j - 1]);
                }
            }
