  static interface IntStream extends Iterable<Integer>, Comparable<IntStream> {
    public IntIterator intIterator();

    default public Iterator<Integer> iterator() {
      return new Iterator<Integer>() {
        private IntIterator it = intIterator();

        public boolean hasNext() {
          return it.isValid();
        }

        public Integer next() {
          int result = it.value();
          it.advance();
          return result;
        }
      };
    }

    default public int compareTo(IntStream c) {
      IntIterator it = intIterator();
      IntIterator jt = c.intIterator();
      while (it.isValid() && jt.isValid()) {
        int i = it.value();
        int j = jt.value();
        if (i < j) {
          return -1;
        } else if (i > j) {
          return 1;
        }
        it.advance();
        jt.advance();
      }
      if (it.isValid()) {
        return 1;
      }
      if (jt.isValid()) {
        return -1;
      }
      return 0;
    }

  }

  static class Heap implements IntQueue {
    private IntComparator comparator;
    private int size = 0;
    private int[] elements;
    private int[] at;

    public Heap(int maxElement) {
      this(10, maxElement);
    }

    public Heap(IntComparator comparator, int maxElement) {
      this(10, comparator, maxElement);
    }

    public Heap(int capacity, int maxElement) {
      this(capacity, IntComparator.DEFAULT, maxElement);
    }

    public Heap(int capacity, IntComparator comparator, int maxElement) {
      this.comparator = comparator;
      elements = new int[capacity];
      at = new int[maxElement];
      Arrays.fill(at, -1);
    }

    public boolean isEmpty() {
      return size == 0;
    }

    public void add(int element) {
      ensureCapacity(size + 1);
      elements[size] = element;
      at[element] = size;
      shiftUp(size++);
    }

    public void shiftUp(int index) {
      //		if (index < 0 || index >= size)
      //			throw new IllegalArgumentException();
      int value = elements[index];
      while (index != 0) {
        int parent = (index - 1) >>> 1;
        int parentValue = elements[parent];
        if (comparator.compare(parentValue, value) <= 0) {
          elements[index] = value;
          at[value] = index;
          return;
        }
        elements[index] = parentValue;
        at[parentValue] = index;
        index = parent;
      }
      elements[0] = value;
      at[value] = 0;
    }

    public void shiftDown(int index) {
      if (index < 0 || index >= size) {
        throw new IllegalArgumentException();
      }
      while (true) {
        int child = (index << 1) + 1;
        if (child >= size) {
          return;
        }
        if (child + 1 < size && comparator.compare(elements[child], elements[child + 1]) > 0) {
          child++;
        }
        if (comparator.compare(elements[index], elements[child]) <= 0) {
          return;
        }
        swap(index, child);
        index = child;
      }
    }

    public int getIndex(int element) {
      return at[element];
    }

    private void swap(int first, int second) {
      int temp = elements[first];
      elements[first] = elements[second];
      elements[second] = temp;
      at[elements[first]] = first;
      at[elements[second]] = second;
    }

    private void ensureCapacity(int size) {
      if (elements.length < size) {
        int[] oldElements = elements;
        elements = new int[Math.max(2 * elements.length, size)];
        System.arraycopy(oldElements, 0, elements, 0, this.size);
      }
    }

    public int poll() {
      if (isEmpty()) {
        throw new IndexOutOfBoundsException();
      }
      int result = elements[0];
      at[result] = -1;
      if (size == 1) {
        size = 0;
        return result;
      }
      elements[0] = elements[--size];
      at[elements[0]] = 0;
      shiftDown(0);
      return result;
    }


    public IntIterator intIterator() {
      return new IntIterator() {
        private int at;


        public int value() throws NoSuchElementException {
          return elements[at];
        }


        public boolean advance() throws NoSuchElementException {
          return ++at < size;
        }


        public boolean isValid() {
          return at < size;
        }


        public void remove() throws NoSuchElementException {
          throw new UnsupportedOperationException();
        }
      };
    }

  }

  static class InputReader {
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private InputReader.SpaceCharFilter filter;

    public InputReader(InputStream stream) {
      this.stream = stream;
    }

    public int read() {
      if (numChars == -1) {
        throw new InputMismatchException();
      }
      if (curChar >= numChars) {
        curChar = 0;
        try {
          numChars = stream.read(buf);
        } catch (IOException e) {
          throw new InputMismatchException();
        }
        if (numChars <= 0) {
          return -1;
        }
      }
      return buf[curChar++];
    }

    public int readInt() {
      int c = read();
      while (isSpaceChar(c)) {
        c = read();
      }
      int sgn = 1;
      if (c == '-') {
        sgn = -1;
        c = read();
      }
      int res = 0;
      do {
        if (c < '0' || c > '9') {
          throw new InputMismatchException();
        }
        res *= 10;
        res += c - '0';
        c = read();
      } while (!isSpaceChar(c));
      return res * sgn;
    }

    public String readString() {
      int c = read();
      while (isSpaceChar(c)) {
        c = read();
      }
      StringBuilder res = new StringBuilder();
      do {
        if (Character.isValidCodePoint(c)) {
          res.appendCodePoint(c);
        }
        c = read();
      } while (!isSpaceChar(c));
      return res.toString();
    }

    public boolean isSpaceChar(int c) {
      if (filter != null) {
        return filter.isSpaceChar(c);
      }
      return isWhitespace(c);
    }

    public static boolean isWhitespace(int c) {
      return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public interface SpaceCharFilter {
      public boolean isSpaceChar(int ch);

    }

