public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        TaskF solver = new TaskF();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskF {
        int n;
        char[] s;
        int[] ugliness;

        public void solve(int testNumber, Scanner in, PrintWriter out) {
            n = in.nextInt();
            s = in.next().toCharArray();
            ugliness = new int[n];
            for (int i = 0; i < n; ++i) {
                ugliness[i] = -in.nextInt();
            }

            int V = 1 + 26 + n / 2 + 1;
            MinCostFlow mcf = new MinCostFlow(V);
            for (char c = 'a'; c <= 'z'; ++c) {
                for (int i = 0; i < n / 2; ++i) {
                    int cost = 0;
                    if (c == s[i]) {
                        cost = Math.min(cost, ugliness[i]);
                    }
                    if (c == s[n - 1 - i]) {
                        cost = Math.min(cost, ugliness[n - 1 - i]);
                    }
                    mcf.addEdge(1 + (c - 'a'), 1 + 26 + i, 1, cost);
                }
            }

            int[] occurs = new int[128];
            for (int i = 0; i < n; ++i) occurs[s[i]]++;
            for (char c = 'a'; c <= 'z'; ++c) {
                mcf.addEdge(0, 1 + (c - 'a'), occurs[c], 0);
            }

            for (int i = 0; i < n / 2; ++i) {
                mcf.addEdge(1 + 26 + i, 1 + 26 + n / 2, 2, 0);
            }

            long[] flow = mcf.minCostMaxFlow(0, 1 + 26 + n / 2, n);
            out.println(-flow[0]);
        }
    }

    static class MinCostFlow {
        class Edge {
            int to, rev;
            long cap, cost;
            Edge(int to, int rev, long cap, long cost) {
                this.to = to;
                this.rev = rev;
                this.cap = cap;
                this.cost = cost;
            }
        }

        List<Edge>[] graph;
        long[] potential, dist;
        int[] prevv, preve;

        @SuppressWarnings("unchecked")
        MinCostFlow(int n) {
            graph = new List[n];
            for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
            potential = new long[n];
            dist = new long[n];
            prevv = new int[n];
            preve = new int[n];
        }

        void addEdge(int from, int to, long cap, long cost) {
            graph[from].add(new Edge(to, graph[to].size(), cap, cost));
            graph[to].add(new Edge(from, graph[from].size() - 1, 0, -cost));
        }

        long[] minCostMaxFlow(int s, int t, long maxf) {
            long flow = 0, cost = 0;
            Arrays.fill(potential, 0);
            while (flow < maxf) {
                Arrays.fill(dist, Long.MAX_VALUE);
                dist[s] = 0;
                PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[1]));
                pq.offer(new long[]{s, 0});
                while (!pq.isEmpty()) {
                    long[] cur = pq.poll();
                    int v = (int) cur[0];
                    if (dist[v] < cur[1]) continue;
                    for (int i = 0; i < graph[v].size(); i++) {
                        Edge e = graph[v].get(i);
                        if (e.cap > 0) {
                            long nd = dist[v] + e.cost + potential[v] - potential[e.to];
                            if (dist[e.to] > nd) {
                                dist[e.to] = nd;
                                prevv[e.to] = v;
                                preve[e.to] = i;
                                pq.offer(new long[]{e.to, nd});
                            }
                        }
                    }
                }
                if (dist[t] == Long.MAX_VALUE) break;
                for (int v = 0; v < graph.length; v++) {
                    if (dist[v] < Long.MAX_VALUE) potential[v] += dist[v];
                }
                long d = maxf - flow;
                for (int v = t; v != s; v = prevv[v]) {
                    d = Math.min(d, graph[prevv[v]].get(preve[v]).cap);
                }
                flow += d;
                cost += d * potential[t];
                for (int v = t; v != s; v = prevv[v]) {
                    Edge e = graph[prevv[v]].get(preve[v]);
                    e.cap -= d;
                    graph[v].get(e.rev).cap += d;
                }
            }
            return new long[]{cost, flow};
        }
    }
}

