import java.io.*;
import java.util.*;

public class CF884F extends PrintWriter {
	CF884F() { super(System.out, true); }
	Scanner sc = new Scanner(System.in);
	public static void main(String[] $) {
		CF884F o = new CF884F(); o.main(); o.flush();
	}

	static final int A = 26, INF = 0x3f3f3f3f;
	int[] oo, oh; int __ = 1;
	int link(int o, int h) {
		oo[__] = o; oh[__] = h;
		return __++;
	}
	int[] ii, jj, cc, ww, ww_; int m_;
	int[] ae, dd, kk, ff; int n_;
	int[] pq, iq; int cnt;
	void init() {
		oo = new int[1 + m_ * 2]; oh = new int[1 + m_ * 2];
		ii = new int[m_]; jj = new int[m_];
		cc = new int[m_ << 1];
		ww = new int[m_]; ww_ = new int[m_];
		ae = new int[n_];
		dd = new int[n_]; kk = new int[n_]; ff = new int[n_];
		pq = new int[1 + n_]; iq = new int[n_];
		m_ = 0;
	}
	void link_(int i, int j, int c, int w) {
		int h = m_++;
		ii[h] = i; jj[h] = j; cc[h << 1] = c; ww[h] = w;
		ae[i] = link(ae[i], h << 1);
		ae[j] = link(ae[j], h << 1 | 1);
	}
	boolean less(int u, int v) {
		return dd[u] < dd[v] || dd[u] == dd[v] && kk[u] < kk[v];
	}
	int i2(int i) {
		return (i *= 2) > cnt ? 0 : i < cnt && less(pq[i + 1], pq[i]) ? i + 1 : i;
	}
	void pq_up(int u) {
		int i, j, v;
		for (i = iq[u]; (j = i / 2) > 0 && less(u, v = pq[j]); i = j)
			pq[iq[v] = i] = v;
		pq[iq[u] = i] = u;
	}
	void pq_dn(int u) {
		int i, j, v;
		for (i = iq[u]; (j = i2(i)) > 0 && less(v = pq[j], u); i = j)
			pq[iq[v] = i] = v;
		pq[iq[u] = i] = u;
	}
	void pq_add_last(int u) {
		pq[iq[u] = ++cnt] = u;
	}
	int pq_remove_first() {
		int u = pq[1], v = pq[cnt--];
		if (v != u) {
			iq[v] = 1; pq_dn(v);
		}
		iq[u] = 0;
		return u;
	}
	boolean dijkstra(int s, int t) {
		Arrays.fill(dd, INF);
		dd[s] = 0; pq_add_last(s);
		while (cnt > 0) {
			int i = pq_remove_first();
			int k = kk[i] + 1;
			for (int o = ae[i]; o != 0; o = oo[o]) {
				int h_ = oh[o];
				if (cc[h_] > 0) {
					int h = h_ >> 1;
					int j = i ^ ii[h] ^ jj[h];
					int d = dd[i] + ((h_ & 1) == 0 ? ww_[h] : -ww_[h]);
					if (dd[j] > d || dd[j] == d && kk[j] > k) {
						if (dd[j] == INF)
							pq_add_last(j);
						dd[j] = d; kk[j] = k; ff[j] = h_;
						pq_up(j);
					}
				}
			}
		}
		return dd[t] != INF;
	}
	int trace(int s, int t) {
		while (t != s) {
			int h_ = ff[t], h = h_ >> 1;
			cc[h_]--; cc[h_ ^ 1]++;
			t ^= ii[h] ^ jj[h];
		}
		return 1;
	}
	int edmonds_karp(int s, int t) {
		for (int h = 0; h < m_; h++) {
			int i = ii[h], j = jj[h];
			dd[j] = Math.min(dd[j], dd[i] + ww[h]);
		}
		for (int h = 0; h < m_; h++) {
			int i = ii[h], j = jj[h];
			ww_[h] = ww[h] + dd[i] - dd[j];
		}
		int f = 0;
		while (dijkstra(s, t)) {
			f += trace(s, t);
			for (int h = 0; h < m_; h++) {
				int i = ii[h], j = jj[h];
				if (dd[i] != INF && dd[j] != INF) {
					// dd[j] <= dd[i] + ww_[h]
					// ww_[h] + dd[i] - dd[j] >= 0
					ww_[h] += dd[i] - dd[j];
				}
			}
		}
		int cost = 0;
		for (int h = 0; h < m_; h++)
			cost += ww[h] * cc[h << 1 | 1];
		return cost;
	}
	void main() {
		int n = sc.nextInt() / 2;
		n_ = 1 + n + A + 1;
		m_ = n + n * A + A;
		init();
		byte[] cc = sc.next().getBytes();
		int[] bb = new int[n * 2];
		for (int i = 0; i < n * 2; i++)
			bb[i] = sc.nextInt();
		for (int i = 0; i < n; i++)
			link_(0, 1 + i, 2, 0);
		for (int i = 0; i < n; i++) {
			int j = n * 2 - 1 - i;
			int ai = cc[i] - 'a';
			int aj = cc[j] - 'a';
			for (int a = 0; a < A; a++) {
				int b;
				if (a == ai && a == aj)
					b = Math.max(bb[i], bb[j]);
				else if (a == ai)
					b = bb[i];
				else if (a == aj)
					b = bb[j];
				else
					b = 0;
				link_(1 + i, 1 + n + a, 1, -b);
			}
		}
		int[] kk = new int[A];
		for (int i = 0; i < n * 2; i++) {
			int a = cc[i] - 'a';
			kk[a]++;
		}
		for (int a = 0; a < A; a++)
			link_(1 + n + a, n_ - 1, kk[a], 0);
		println(-edmonds_karp(0, n_ - 1));
	}
}

import java.io.*;
import java.util.*;

public class CF884F_Variant1 extends PrintWriter {
    static final int ALPH = 26;
    static final int INF = 0x3f3f3f3f;

    int[] next, edgeTo;
    int ptr = 1;
    int[] from, to, cap, weight, redWeight;
    int edges;
    int[] first, dist, hops, prevEdge;
    int vertices;
    int[] heap, heapPos;
    int heapSize;

    CF884F_Variant1() { super(System.out, true); }
    Scanner in = new Scanner(System.in);

    public static void main(String[] args) {
        CF884F_Variant1 solver = new CF884F_Variant1();
        solver.run();
        solver.flush();
    }

    int addToList(int head, int edge) {
        next[ptr] = head;
        edgeTo[ptr] = edge;
        return ptr++;
    }

    void init() {
        next = new int[1 + edges * 2];
        edgeTo = new int[1 + edges * 2];
        from = new int[edges];
        to = new int[edges];
        cap = new int[edges << 1];
        weight = new int[edges];
        redWeight = new int[edges];
        first = new int[vertices];
        dist = new int[vertices];
        hops = new int[vertices];
        prevEdge = new int[vertices];
        heap = new int[vertices + 1];
        heapPos = new int[vertices];
        edges = 0;
    }

    void addEdge(int u, int v, int c, int w) {
        int e = edges++;
        from[e] = u;
        to[e] = v;
        cap[e << 1] = c;
        weight[e] = w;
        first[u] = addToList(first[u], e << 1);
        first[v] = addToList(first[v], e << 1 | 1);
    }

    boolean less(int u, int v) {
        return dist[u] < dist[v] || (dist[u] == dist[v] && hops[u] < hops[v]);
    }

    int child(int i) {
        i <<= 1;
        if (i > heapSize) return 0;
        if (i < heapSize && less(heap[i + 1], heap[i])) i++;
        return i;
    }

    void heapUp(int u) {
        int i, j, v;
        for (i = heapPos[u]; (j = i >> 1) > 0 && less(u, v = heap[j]); i = j)
            heap[heapPos[v] = i] = v;
        heap[heapPos[u] = i] = u;
    }

    void heapDown(int u) {
        int i, j, v;
        for (i = heapPos[u]; (j = child(i)) > 0 && less(v = heap[j], u); i = j)
            heap[heapPos[v] = i] = v;
        heap[heapPos[u] = i] = u;
    }

    void addToHeap(int u) {
        heap[heapPos[u] = ++heapSize] = u;
    }

    int removeMin() {
        int u = heap[1], v = heap[heapSize--];
        if (v != u) {
            heapPos[v] = 1;
            heapDown(v);
        }
        heapPos[u] = 0;
        return u;
    }

    boolean dijkstra(int s, int t) {
        Arrays.fill(dist, INF);
        dist[s] = 0;
        addToHeap(s);
        while (heapSize > 0) {
            int u = removeMin();
            int nh = hops[u] + 1;
            for (int p = first[u]; p != 0; p = next[p]) {
                int arc = edgeTo[p];
                if (cap[arc] > 0) {
                    int e = arc >> 1;
                    int v = u ^ from[e] ^ to[e];
                    int nd = dist[u] + ((arc & 1) == 0 ? redWeight[e] : -redWeight[e]);
                    if (dist[v] > nd || (dist[v] == nd && hops[v] > nh)) {
                        if (dist[v] == INF) addToHeap(v);
                        dist[v] = nd;
                        hops[v] = nh;
                        prevEdge[v] = arc;
                        heapUp(v);
                    }
                }
            }
        }
        return dist[t] != INF;
    }

    int augment(int s, int t) {
        while (t != s) {
            int arc = prevEdge[t], e = arc >> 1;
            cap[arc]--;
            cap[arc ^ 1]++;
            t ^= from[e] ^ to[e];
        }
        return 1;
    }

    int minCostFlow(int s, int t) {
        for (int e = 0; e < edges; e++) {
            int u = from[e], v = to[e];
            dist[v] = Math.min(dist[v], dist[u] + weight[e]);
        }
        for (int e = 0; e < edges; e++) {
            int u = from[e], v = to[e];
            redWeight[e] = weight[e] + dist[u] - dist[v];
        }
        while (dijkstra(s, t)) {
            augment(s, t);
            for (int e = 0; e < edges; e++) {
                int u = from[e], v = to[e];
                if (dist[u] != INF && dist[v] != INF) {
                    redWeight[e] += dist[u] - dist[v];
                }
            }
        }
        int cost = 0;
        for (int e = 0; e < edges; e++)
            cost += weight[e] * cap[e << 1 | 1];
        return cost;
    }

    void run() {
        int n = in.nextInt() / 2;
        vertices = 1 + n + ALPH + 1;
        edges = n + n * ALPH + ALPH;
        init();
        byte[] s = in.next().getBytes();
        int[] b = new int[2 * n];
        for (int i = 0; i < 2 * n; i++) b[i] = in.nextInt();
        for (int i = 0; i < n; i++) addEdge(0, 1 + i, 2, 0);
        for (int i = 0; i < n; i++) {
            int j = 2 * n - 1 - i;
            int ai = s[i] - 'a';
            int aj = s[j] - 'a';
            for (int a = 0; a < ALPH; a++) {
                int val;
                if (a == ai && a == aj) val = Math.max(b[i], b[j]);
                else if (a == ai) val = b[i];
                else if (a == aj) val = b[j];
                else val = 0;
                addEdge(1 + i, 1 + n + a, 1, -val);
            }
        }
        int[] cnt = new int[ALPH];
        for (int i = 0; i < 2 * n; i++) cnt[s[i] - 'a']++;
        for (int a = 0; a < ALPH; a++) addEdge(1 + n + a, vertices - 1, cnt[a], 0);
        println(-minCostFlow(0, vertices - 1));
    }
}

import java.io.*;
