public class CF884F_Variant2 {
    static final int INF = 0x3f3f3f3f;
    static final int A = 26;

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;
        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class Edge {
        int to, rev, cap, cost;
        Edge(int to, int rev, int cap, int cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }

    static class MCMF {
        int n;
        ArrayList<Edge>[] g;
        int[] potential, dist, prevv, preve;

        @SuppressWarnings("unchecked")
        MCMF(int n) {
            this.n = n;
            g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
            potential = new int[n];
            dist = new int[n];
            prevv = new int[n];
            preve = new int[n];
        }

        void addEdge(int from, int to, int cap, int cost) {
            g[from].add(new Edge(to, g[to].size(), cap, cost));
            g[to].add(new Edge(from, g[from].size() - 1, 0, -cost));
        }

        boolean spfa(int s) {
            Arrays.fill(potential, INF);
            boolean[] inq = new boolean[n];
            ArrayDeque<Integer> q = new ArrayDeque<>();
            potential[s] = 0;
            q.add(s);
            inq[s] = true;
            while (!q.isEmpty()) {
                int v = q.poll();
                inq[v] = false;
                for (Edge e : g[v]) {
                    if (e.cap > 0 && potential[e.to] > potential[v] + e.cost) {
                        potential[e.to] = potential[v] + e.cost;
                        if (!inq[e.to]) {
                            q.add(e.to);
                            inq[e.to] = true;
                        }
                    }
                }
            }
            return true;
        }

        int minCostFlow(int s, int t) {
            spfa(s);
            int cost = 0;
            while (true) {
                Arrays.fill(dist, INF);
                dist[s] = 0;
                PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
                pq.offer(new int[]{0, s});
                while (!pq.isEmpty()) {
                    int[] cur = pq.poll();
                    int d = cur[0], v = cur[1];
                    if (dist[v] < d) continue;
                    for (int i = 0; i < g[v].size(); i++) {
                        Edge e = g[v].get(i);
                        if (e.cap <= 0) continue;
                        int nd = d + e.cost + potential[v] - potential[e.to];
                        if (dist[e.to] > nd) {
                            dist[e.to] = nd;
                            prevv[e.to] = v;
                            preve[e.to] = i;
                            pq.offer(new int[]{nd, e.to});
                        }
                    }
                }
                if (dist[t] == INF) break;
                for (int v = 0; v < n; v++) {
                    if (dist[v] < INF) potential[v] += dist[v];
                }
                int add = INF;
                for (int v = t; v != s; v = prevv[v]) {
                    add = Math.min(add, g[prevv[v]].get(preve[v]).cap);
                }
                for (int v = t; v != s; v = prevv[v]) {
                    Edge e = g[prevv[v]].get(preve[v]);
                    e.cap -= add;
                    g[v].get(e.rev).cap += add;
                }
                cost += add * (potential[t] - potential[s]);
            }
            return cost;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt() / 2;
        int V = 1 + n + A + 1;
        MCMF mcmf = new MCMF(V);
        byte[] s = fs.next().getBytes();
        int[] b = new int[2 * n];
        for (int i = 0; i < 2 * n; i++) b[i] = fs.nextInt();

        int[] cnt = new int[A];
        for (int i = 0; i < 2 * n; i++) cnt[s[i] - 'a']++;

        for (int i = 0; i < n; i++) mcmf.addEdge(0, 1 + i, 2, 0);
        for (int i = 0; i < n; i++) {
            int j = 2 * n - 1 - i;
            int ai = s[i] - 'a';
            int aj = s[j] - 'a';
            for (int a = 0; a < A; a++) {
                int val;
                if (a == ai && a == aj) val = Math.max(b[i], b[j]);
                else if (a == ai) val = b[i];
                else if (a == aj) val = b[j];
                else val = 0;
                mcmf.addEdge(1 + i, 1 + n + a, 1, -val);
            }
        }
        for (int a = 0; a < A; a++) mcmf.addEdge(1 + n + a, V - 1, cnt[a], 0);

        System.out.println(-mcmf.minCostFlow(0, V - 1));
    }
}

