public class CF884F_Variant4 {
    static final int INF = 0x3f3f3f3f;
    static final int A = 26;

    static int[][] cap, cost;
    static int V;

    static void addEdge(int u, int v, int c, int w) {
        cap[u][v] = c;
        cost[u][v] = w;
        cost[v][u] = -w;
    }

    static boolean shortest(int s, int t, int[] dist, int[] prev) {
        Arrays.fill(dist, INF);
        dist[s] = 0;
        for (int it = 0; it < V - 1; it++) {
            boolean updated = false;
            for (int u = 0; u < V; u++) {
                if (dist[u] == INF) continue;
                for (int v = 0; v < V; v++) {
                    if (cap[u][v] > 0 && dist[v] > dist[u] + cost[u][v]) {
                        dist[v] = dist[u] + cost[u][v];
                        prev[v] = u;
                        updated = true;
                    }
                }
            }
            if (!updated) break;
        }
        return dist[t] != INF;
    }

    static int minCostFlow(int s, int t) {
        int[] dist = new int[V], prev = new int[V];
        int totalCost = 0;
        while (shortest(s, t, dist, prev)) {
            int add = INF;
            for (int v = t; v != s; v = prev[v]) {
                add = Math.min(add, cap[prev[v]][v]);
            }
            for (int v = t; v != s; v = prev[v]) {
                int u = prev[v];
                cap[u][v] -= add;
                cap[v][u] += add;
            }
            totalCost += add * dist[t];
        }
        return totalCost;
    }

