        for (int i = 0; i < n; i++) {
            int j = 2 * n - 1 - i;
            int ai = s[i] - 'a';
            int aj = s[j] - 'a';
            for (int a = 0; a < A; a++) {
                int val;
                if (a == ai && a == aj) val = Math.max(b[i], b[j]);
                else if (a == ai) val = b[i];
                else if (a == aj) val = b[j];
                else val = 0;
