public class CF884F_Variant5 {
    static final int ALPH = 26;
    static final int INF = 0x3f3f3f3f;

    static int[] head, to, nxt, cap, cost, from;
    static int edgeCnt;

    static void addEdge(int u, int v, int c, int w) {
        to[edgeCnt] = v; cap[edgeCnt] = c; cost[edgeCnt] = w; from[edgeCnt] = u; nxt[edgeCnt] = head[u]; head[u] = edgeCnt++;
        to[edgeCnt] = u; cap[edgeCnt] = 0; cost[edgeCnt] = -w; from[edgeCnt] = v; nxt[edgeCnt] = head[v]; head[v] = edgeCnt++;
    }

    static void bellmanFord(int s, int[] pot) {
        Arrays.fill(pot, INF);
        pot[s] = 0;
        for (int it = 0; it < pot.length - 1; it++) {
            boolean updated = false;
            for (int e = 0; e < edgeCnt; e++) {
                if (cap[e] > 0 && pot[from[e]] != INF && pot[to[e]] > pot[from[e]] + cost[e]) {
                    pot[to[e]] = pot[from[e]] + cost[e];
                    updated = true;
                }
            }
            if (!updated) break;
        }
    }

    static boolean dijkstra(int s, int t, int[] pot, int[] dist, int[] prev, int[] preve) {
        Arrays.fill(dist, INF);
        dist[s] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        pq.offer(new int[]{0, s});
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int d = cur[0], v = cur[1];
            if (dist[v] < d) continue;
            for (int e = head[v]; e != -1; e = nxt[e]) {
                if (cap[e] <= 0) continue;
                int nd = d + cost[e] + pot[v] - pot[to[e]];
                if (dist[to[e]] > nd) {
                    dist[to[e]] = nd;
                    prev[to[e]] = v;
                    preve[to[e]] = e;
                    pq.offer(new int[]{nd, to[e]});
                }
            }
        }
        return dist[t] != INF;
    }

    static int minCostFlow(int s, int t, int n) {
        int[] pot = new int[n];
        bellmanFord(s, pot);
        int[] dist = new int[n], prev = new int[n], preve = new int[n];
        int totalCost = 0;
        while (true) {
            if (!dijkstra(s, t, pot, dist, prev, preve)) break;
            for (int i = 0; i < n; i++) {
                if (dist[i] < INF) pot[i] += dist[i];
            }
            int add = INF;
            for (int v = t; v != s; v = prev[v]) {
                add = Math.min(add, cap[preve[v]]);
            }
            for (int v = t; v != s; v = prev[v]) {
                int e = preve[v];
                cap[e] -= add;
                cap[e ^ 1] += add;
            }
            totalCost += add * (pot[t] - pot[s]);
        }
        return totalCost;
    }

    public static void main(String[] args) throws IOException {
        byte[] all = System.in.readAllBytes();
        String data = new String(all, StandardCharsets.UTF_8).trim();
        String[] tokens = data.split("\\s+");
        int idx = 0;

        int n = Integer.parseInt(tokens[idx++]) / 2;
        int V = 1 + n + ALPH + 1;
        int E = n + n * ALPH + ALPH;

        head = new int[V];
        Arrays.fill(head, -1);
        int maxArcs = 2 * E + 5;
        to = new int[maxArcs];
        nxt = new int[maxArcs];
        cap = new int[maxArcs];
        cost = new int[maxArcs];
        from = new int[maxArcs];
        edgeCnt = 0;

        byte[] s = tokens[idx++].getBytes(StandardCharsets.US_ASCII);
        int[] b = new int[2 * n];
        for (int i = 0; i < 2 * n; i++) b[i] = Integer.parseInt(tokens[idx++]);

        int[] cnt = new int[ALPH];
        for (int i = 0; i < 2 * n; i++) cnt[s[i] - 'a']++;

        for (int i = 0; i < n; i++) addEdge(0, 1 + i, 2, 0);
        for (int i = 0; i < n; i++) {
            int j = 2 * n - 1 - i;
            int ai = s[i] - 'a';
            int aj = s[j] - 'a';
            for (int a = 0; a < ALPH; a++) {
                int val;
                if (a == ai && a == aj) val = Math.max(b[i], b[j]);
                else if (a == ai) val = b[i];
                else if (a == aj) val = b[j];
                else val = 0;
                addEdge(1 + i, 1 + n + a, 1, -val);
            }
        }
        for (int a = 0; a < ALPH; a++) addEdge(1 + n + a, V - 1, cnt[a], 0);

        System.out.println(-minCostFlow(0, V - 1, V));
    }
}

