    static class Pair<U, V> implements Comparable<Pair<U, V>> {
        public final U first;
        public final V second;

        public static <U, V> Pair<U, V> makePair(U first, V second) {
            return new Pair<U, V>(first, second);
        }

        private Pair(U first, V second) {
            this.first = first;
            this.second = second;
        }


        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (o == null || getClass() != o.getClass()) {
                return false;
            }

            Pair pair = (Pair) o;

            return !(first != null ? !first.equals(pair.first) : pair.first != null) &&
                    !(second != null ? !second.equals(pair.second) : pair.second != null);
        }


        public int hashCode() {
            int result = first != null ? first.hashCode() : 0;
            result = 31 * result + (second != null ? second.hashCode() : 0);
            return result;
        }


        public String toString() {
            return "(" + first + "," + second + ")";
        }

        @SuppressWarnings({"unchecked"})
        public int compareTo(Pair<U, V> o) {
            int value = ((Comparable<U>) first).compareTo(o.first);
            if (value != 0) {
                return value;
            }
            return ((Comparable<V>) second).compareTo(o.second);
        }

    }

    static class Heap implements IntQueue {
        private IntComparator comparator;
        private int size = 0;
        private int[] elements;
        private int[] at;

        public Heap(int maxElement) {
            this(10, maxElement);
        }

        public Heap(IntComparator comparator, int maxElement) {
            this(10, comparator, maxElement);
        }

        public Heap(int capacity, int maxElement) {
            this(capacity, IntComparator.DEFAULT, maxElement);
        }

        public Heap(int capacity, IntComparator comparator, int maxElement) {
            this.comparator = comparator;
            elements = new int[capacity];
            at = new int[maxElement];
            Arrays.fill(at, -1);
        }

        public boolean isEmpty() {
            return size == 0;
        }

        public void add(int element) {
            ensureCapacity(size + 1);
            elements[size] = element;
            at[element] = size;
            shiftUp(size++);
        }

        public void shiftUp(int index) {
            //		if (index < 0 || index >= size)
            //			throw new IllegalArgumentException();
            int value = elements[index];
            while (index != 0) {
                int parent = (index - 1) >>> 1;
                int parentValue = elements[parent];
                if (comparator.compare(parentValue, value) <= 0) {
                    elements[index] = value;
                    at[value] = index;
                    return;
                }
                elements[index] = parentValue;
                at[parentValue] = index;
                index = parent;
            }
            elements[0] = value;
            at[value] = 0;
        }

        public void shiftDown(int index) {
            if (index < 0 || index >= size) {
                throw new IllegalArgumentException();
            }
            while (true) {
                int child = (index << 1) + 1;
                if (child >= size) {
                    return;
                }
                if (child + 1 < size && comparator.compare(elements[child], elements[child + 1]) > 0) {
                    child++;
                }
                if (comparator.compare(elements[index], elements[child]) <= 0) {
                    return;
                }
                swap(index, child);
                index = child;
            }
        }

        public int getIndex(int element) {
            return at[element];
        }

        private void swap(int first, int second) {
            int temp = elements[first];
            elements[first] = elements[second];
            elements[second] = temp;
            at[elements[first]] = first;
            at[elements[second]] = second;
        }

        private void ensureCapacity(int size) {
            if (elements.length < size) {
                int[] oldElements = elements;
                elements = new int[Math.max(2 * elements.length, size)];
                System.arraycopy(oldElements, 0, elements, 0, this.size);
            }
        }

        public int poll() {
            if (isEmpty()) {
                throw new IndexOutOfBoundsException();
            }
            int result = elements[0];
            at[result] = -1;
            if (size == 1) {
                size = 0;
                return result;
            }
            elements[0] = elements[--size];
            at[elements[0]] = 0;
            shiftDown(0);
            return result;
        }


        public IntIterator intIterator() {
            return new IntIterator() {
                private int at;


                public int value() throws NoSuchElementException {
                    return elements[at];
                }


                public boolean advance() throws NoSuchElementException {
                    return ++at < size;
                }


                public boolean isValid() {
                    return at < size;
                }


                public void remove() throws NoSuchElementException {
                    throw new UnsupportedOperationException();
                }
            };
        }

    }
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();
        int[] a = new int[n];
        int[] cnt = new int[26];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
            cnt[s.charAt(i) - 'a']++;
        }
        int pairCount = (n + 1) / 2;
        int V = n + 26 + 2;
        int source = V - 2;
        int sink = V - 1;
        List<Edge>[] graph = new List[V];
        for (int i = 0; i < V; i++) graph[i] = new ArrayList<>();
        // add edges from source to letter nodes
        for (int i = 0; i < 26; i++) {
            addEdge(graph, source, i + n, 0, cnt[i]);
        }
        // add edges from letter nodes to pair nodes
        for (int i = 0; i < 26; i++) {
            for (int j = 0; j < pairCount; j++) {
                int left = j;
                int right = n - 1 - j;
                long w = 0;
                if (s.charAt(left) == s.charAt(right)) {
                    if (s.charAt(left) == (char)('a' + i)) {
                        w = -Math.max(a[left], a[right]);
                    }
                } else {
                    if (s.charAt(left) == (char)('a' + i)) w -= a[left];
                    if (s.charAt(right) == (char)('a' + i)) w -= a[right];
                }
                addEdge(graph, i + n, j, w, 1);
            }
        }
        // add edges from pair nodes to sink
        for (int j = 0; j < pairCount; j++) {
            addEdge(graph, j, sink, 0, 2);
        }
        long[] res = minCostMaxFlow(graph, source, sink, Long.MAX_VALUE);
        System.out.println(-res[0]);
    }

    static class Edge {
        int to, rev;
        long cap, cost;
        Edge(int to, int rev, long cap, long cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }

    static void addEdge(List<Edge>[] graph, int from, int to, long cost, long cap) {
        graph[from].add(new Edge(to, graph[to].size(), cap, cost));
        graph[to].add(new Edge(from, graph[from].size() - 1, 0, -cost));
    }

    static long[] minCostMaxFlow(List<Edge>[] graph, int s, int t, long maxf) {
        int n = graph.length;
        long[] potential = new long[n];
        long[] dist = new long[n];
        int[] prevv = new int[n];
        int[] preve = new int[n];
        long flow = 0, cost = 0;
        while (flow < maxf) {
            Arrays.fill(dist, Long.MAX_VALUE);
            dist[s] = 0;
            PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
            pq.offer(new long[]{0, s});
            while (!pq.isEmpty()) {
                long[] cur = pq.poll();
                long d = cur[0];
                int v = (int) cur[1];
                if (dist[v] < d) continue;
                for (int i = 0; i < graph[v].size(); i++) {
                    Edge e = graph[v].get(i);
                    if (e.cap > 0) {
                        long nd = d + e.cost + potential[v] - potential[e.to];
                        if (dist[e.to] > nd) {
                            dist[e.to] = nd;
                            prevv[e.to] = v;
                            preve[e.to] = i;
                            pq.offer(new long[]{nd, e.to});
                        }
                    }
                }
            }
            if (dist[t] == Long.MAX_VALUE) break;
            for (int v = 0; v < n; v++) {
                if (dist[v] < Long.MAX_VALUE) potential[v] += dist[v];
            }
            long add = maxf - flow;
            for (int v = t; v != s; v = prevv[v]) {
                add = Math.min(add, graph[prevv[v]].get(preve[v]).cap);
            }
            flow += add;
            cost += add * potential[t];
            for (int v = t; v != s; v = prevv[v]) {
                Edge e = graph[prevv[v]].get(preve[v]);
                e.cap -= add;
                graph[v].get(e.rev).cap += add;
            }
        }
        return new long[]{cost, flow};
    }
}

