    static class Graph {
        int V;
        int[] head;
        int[] to;
        int[] next;
        long[] cap;
        long[] cost;
        int[] rev;
        int edgeCount;
        Graph(int V) {
            this.V = V;
            head = new int[V];
            Arrays.fill(head, -1);
            to = new int[2];
            next = new int[2];
            cap = new long[2];
            cost = new long[2];
            rev = new int[2];
            edgeCount = 0;
        }
        void addEdge(int from, int to, long cost, long cap, int rev) {
            ensureCapacity(edgeCount + 1);
            next[edgeCount] = head[from];
            head[from] = edgeCount;
            this.to[edgeCount] = to;
            this.cost[edgeCount] = cost;
            this.cap[edgeCount] = cap;
            this.rev[edgeCount] = rev;
