        int diff = computeDiff(wrongChars, chars1);
        System.out.println(IntStream.of(vals).sum() - diff);
    }

    private static int computeDiff(List<Char> wrongChars, List<Char> chars1) {
        if (isAntiPalindrome(chars)) return 0;
        if (wrongChars.size() == 1) {
            Char wc = wrongChars.get(0);
            for (Char c : chars1) {
                if (c.chr != wc.chr && chars[n - c.idx - 1] != wc.chr) {
                    return wc.val + c.val;
                }
            }
            return 0;
