                            && !wrongChars.contains(c) && !append.contains(c)) {
                        append.add(c);
                        break;
                    }
                }
            }
            return wrongChars.stream().mapToInt(c -> c.val).sum() + append.stream().mapToInt(c -> c.val).sum();
        }
        return 0;
    }

