public class CF884F extends PrintWriter {
	CF884F() { super(System.out, true); }
	Scanner sc = new Scanner(System.in);
	public static void main(String[] $) {
		CF884F o = new CF884F(); o.main(); o.flush();
	}

	static final int A = 26, INF = 0x3f3f3f3f;
	int[] oo, oh; int __ = 1;
	int link(int o, int h) {
		oo[__] = o; oh[__] = h;
		return __++;
	}
	int[] ii, jj, cc, cost, cost_; int m_;
	int[] ae, pi, dd, ff; int n_;
	int[] pq, iq; int cnt;
	void init() {
		oo = new int[1 + m_ * 2]; oh = new int[1 + m_ * 2];
		ii = new int[m_]; jj = new int[m_]; cc = new int[m_ << 1];
		cost = new int[m_]; cost_ = new int[m_];
		pi = new int[n_]; dd = new int[n_]; ff = new int[n_];
		ae = new int[n_];
		pq = new int[1 + n_]; iq = new int[n_];
		m_ = 0;
	}
	void link_(int i, int j, int c, int co) {
		int h = m_++;
		ii[h] = i; jj[h] = j; cc[h << 1] = c;
		cost[h] = co;
		ae[i] = link(ae[i], h << 1);
		ae[j] = link(ae[j], h << 1 | 1);
	}
	boolean less(int u, int v) {
		return pi[u] < pi[v] || pi[u] == pi[v] && dd[u] < dd[v];
	}
	int i2(int i) {
		return (i *= 2) > cnt ? 0 : i < cnt && less(pq[i + 1], pq[i]) ? i + 1 : i;
	}
	void pq_up(int u) {
		int i, j, v;
		for (i = iq[u]; (j = i / 2) > 0 && less(u, v = pq[j]); i = j)
			pq[iq[v] = i] = v;
		pq[iq[u] = i] = u;
	}
	void pq_dn(int u) {
		int i, j, v;
		for (i = iq[u]; (j = i2(i)) > 0 && less(v = pq[j], u); i = j)
			pq[iq[v] = i] = v;
		pq[iq[u] = i] = u;
	}
	void pq_add_last(int u) {
		pq[iq[u] = ++cnt] = u;
	}
	int pq_remove_first() {
		int u = pq[1], v = pq[cnt--];
		if (v != u) {
			iq[v] = 1; pq_dn(v);
		}
		iq[u] = 0;
		return u;
	}
	boolean dijkstra(int s, int t) {
		Arrays.fill(pi, INF);
		pi[s] = 0; pq_add_last(s);
		while (cnt > 0) {
			int i = pq_remove_first();
			int d = dd[i] + 1;
			for (int o = ae[i]; o != 0; o = oo[o]) {
				int h_ = oh[o];
				if (cc[h_] > 0) {
					int h = h_ >> 1;
					int j = i ^ ii[h] ^ jj[h];
					int p = pi[i] + ((h_ & 1) == 0 ? cost_[h] : -cost_[h]);
					if (pi[j] > p || pi[j] == p && dd[j] > d) {
						if (pi[j] == INF)
							pq_add_last(j);
						pi[j] = p; dd[j] = d; ff[j] = h_;
						pq_up(j);
					}
				}
			}
		}
		return pi[t] != INF;
	}
	int trace(int s, int t) {
		while (t != s) {
			int h_ = ff[t], h = h_ >> 1;
			cc[h_]--; cc[h_ ^ 1]++;
			t ^= ii[h] ^ jj[h];
		}
		return 1;
	}
	int edmonds_karp(int s, int t) {
		for (int h = 0; h < m_; h++) {
			int i = ii[h], j = jj[h];
			pi[j] = Math.min(pi[j], pi[i] + cost[h]);
		}
		for (int h = 0; h < m_; h++) {
			int i = ii[h], j = jj[h];
			cost_[h] = cost[h] + pi[i] - pi[j];
		}
		int f = 0;
		while (dijkstra(s, t)) {
			f += trace(s, t);
			for (int h = 0; h < m_; h++) {
				int i = ii[h], j = jj[h];
				if (pi[i] != INF && pi[j] != INF) {
					// pi[j] <= pi[i] + cost_[h]
					// cost_[h] + pi[i] - pi[j] >= 0
					cost_[h] += pi[i] - pi[j];
				}
			}
		}
		int ans = 0;
		for (int h = 0; h < m_; h++)
			ans += cc[h << 1 | 1] * cost[h];
		return ans;
	}
	void main() {
		int n = sc.nextInt() / 2;
		n_ = 1 + n + A + 1;
		m_ = n + n * A + A;
		init();
		byte[] cc = sc.next().getBytes();
		int[] bb = new int[n * 2];
		for (int i = 0; i < n * 2; i++)
			bb[i] = sc.nextInt();
		for (int i = 0; i < n; i++)
			link_(0, 1 + i, 2, 0);
		for (int i = 0; i < n; i++) {
			int j = n * 2 - 1 - i;
			int ai = cc[i] - 'a';
			int aj = cc[j] - 'a';
			for (int a = 0; a < A; a++) {
				int b;
				if (a == ai && a == aj)
					b = Math.max(bb[i], bb[j]);
				else if (a == ai)
					b = bb[i];
				else if (a == aj)
					b = bb[j];
				else
					b = 0;
				link_(1 + i, 1 + n + a, 1, -b);
			}
		}
		int[] kk = new int[A];
		for (int i = 0; i < n * 2; i++) {
			int a = cc[i] - 'a';
			kk[a]++;
		}
		for (int a = 0; a < A; a++)
			link_(1 + n + a, n_ - 1, kk[a], 0);
		println(-edmonds_karp(0, n_ - 1));
	}
}

import java.util.*;

public class CF884F {
    static final int A = 26, INF = 0x3f3f3f3f;

    int[] nextArc, arcEdge;
    int arcCnt = 1;

    int addArc(int head, int e) {
        nextArc[arcCnt] = head;
        arcEdge[arcCnt] = e;
        return arcCnt++;
    }

    int[] from, to, cap, orgCost, redCost;
    int edgeCnt;
    int[] head, dist, depth, prevArc;
    int nodeCnt;
    int[] heap, heapPos;
    int heapSize;

    void init(int n, int maxEdge) {
        nodeCnt = 1 + n + A + 1;
        edgeCnt = maxEdge;
        nextArc = new int[1 + edgeCnt * 2];
        arcEdge = new int[1 + edgeCnt * 2];
        from = new int[edgeCnt];
        to = new int[edgeCnt];
        cap = new int[edgeCnt << 1];
        orgCost = new int[edgeCnt];
        redCost = new int[edgeCnt];
        head = new int[nodeCnt];
        dist = new int[nodeCnt];
        depth = new int[nodeCnt];
        prevArc = new int[nodeCnt];
        heap = new int[nodeCnt + 1];
        heapPos = new int[nodeCnt];
        edgeCnt = 0;
    }

    void addEdge(int u, int v, int c, int w) {
        int h = edgeCnt++;
        from[h] = u;
        to[h] = v;
        cap[h << 1] = c;
        orgCost[h] = w;
        head[u] = addArc(head[u], h << 1);
        head[v] = addArc(head[v], h << 1 | 1);
    }

    boolean better(int u, int v) {
        return dist[u] < dist[v] || dist[u] == dist[v] && depth[u] < depth[v];
    }

    int minChild(int i) {
        return (i *= 2) > heapSize ? 0 : (i < heapSize && better(heap[i + 1], heap[i]) ? i + 1 : i);
    }

    void heapUp(int u) {
        int i = heapPos[u], j, v;
        while ((j = i / 2) > 0 && better(u, v = heap[j])) {
            heap[heapPos[v] = i] = v;
            i = j;
        }
        heap[heapPos[u] = i] = u;
    }

    void heapDown(int u) {
        int i = heapPos[u], j, v;
        while ((j = minChild(i)) > 0 && better(v = heap[j], u)) {
            heap[heapPos[v] = i] = v;
            i = j;
        }
        heap[heapPos[u] = i] = u;
    }

    void heapAdd(int u) {
        heap[heapPos[u] = ++heapSize] = u;
    }

    int heapRemove() {
        int u = heap[1], v = heap[heapSize--];
        if (v != u) {
            heapPos[v] = 1;
            heapDown(v);
        }
        heapPos[u] = 0;
        return u;
    }

    boolean dijkstra(int s, int t) {
        Arrays.fill(dist, INF);
        dist[s] = 0;
        heapAdd(s);
        while (heapSize > 0) {
            int u = heapRemove();
            int nd = depth[u] + 1;
            for (int a = head[u]; a != 0; a = nextArc[a]) {
                int eid = arcEdge[a];
                if (cap[eid] <= 0) continue;
                int h = eid >>> 1;
                int v = u ^ from[h] ^ to[h];
                int ndist = dist[u] + ((eid & 1) == 0 ? redCost[h] : -redCost[h]);
                if (ndist < dist[v] || ndist == dist[v] && depth[v] > nd) {
                    if (dist[v] == INF) heapAdd(v);
                    dist[v] = ndist;
                    depth[v] = nd;
                    prevArc[v] = eid;
                    heapUp(v);
                }
            }
        }
        return dist[t] != INF;
    }

    int augment(int s, int t) {
        while (t != s) {
            int eid = prevArc[t];
            int h = eid >>> 1;
            cap[eid]--;
            cap[eid ^ 1]++;
            t ^= from[h] ^ to[h];
        }
        return 1;
    }

    int minCostFlow(int s, int t) {
        for (int h = 0; h < edgeCnt; h++) {
            int u = from[h], v = to[h];
            dist[v] = Math.min(dist[v], dist[u] + orgCost[h]);
        }
        for (int h = 0; h < edgeCnt; h++) {
            int u = from[h], v = to[h];
            redCost[h] = orgCost[h] + dist[u] - dist[v];
        }
        int flowCost = 0;
        while (dijkstra(s, t)) {
            flowCost += augment(s, t);
            for (int h = 0; h < edgeCnt; h++) {
                int u = from[h], v = to[h];
                if (dist[u] != INF && dist[v] != INF)
                    redCost[h] += dist[u] - dist[v];
            }
        }
        int ans = 0;
        for (int h = 0; h < edgeCnt; h++)
            ans += cap[h << 1 | 1] * orgCost[h];
        return ans;
    }

    void run() {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt() / 2;
        int maxEdge = n + n * A + A;
        init(n, maxEdge);
        byte[] s = sc.next().getBytes();
        int[] b = new int[n * 2];
        for (int i = 0; i < n * 2; i++) b[i] = sc.nextInt();

        for (int i = 0; i < n; i++) addEdge(0, 1 + i, 2, 0);
        for (int i = 0; i < n; i++) {
            int j = n * 2 - 1 - i;
            int ai = s[i] - 'a';
            int aj = s[j] - 'a';
            for (int a = 0; a < A; a++) {
                int w;
                if (a == ai && a == aj) w = Math.max(b[i], b[j]);
                else if (a == ai) w = b[i];
                else if (a == aj) w = b[j];
                else w = 0;
                addEdge(1 + i, 1 + n + a, 1, -w);
            }
        }
        int[] cnt = new int[A];
        for (int i = 0; i < n * 2; i++) cnt[s[i] - 'a']++;
        for (int a = 0; a < A; a++)
            addEdge(1 + n + a, nodeCnt - 1, cnt[a], 0);

        System.out.println(-minCostFlow(0, nodeCnt - 1));
    }

    public static void main(String[] args) {
        new CF884F().run();
    }
}

