public class CF884F {
    static final int A = 26, INF = Integer.MAX_VALUE / 4;
    int n, N, S, T;
    ArrayList<ArrayList<Edge>> g;

    static class Edge {
        int to, rev, cap, cost;
        Edge(int to, int rev, int cap, int cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }

    void addEdge(int v, int to, int cap, int cost) {
        Edge a = new Edge(to, g.get(to).size(), cap, cost);
        Edge b = new Edge(v, g.get(v).size(), 0, -cost);
        g.get(v).add(a);
        g.get(to).add(b);
    }

    int minCostFlow(int s, int t) {
        int total = 0;
        while (true) {
            int[] dist = new int[N];
            int[] pv = new int[N];
            int[] pe = new int[N];
            boolean[] inq = new boolean[N];
            Arrays.fill(dist, INF);
            dist[s] = 0;

            ArrayDeque<Integer> q = new ArrayDeque<>();
            q.add(s);
            inq[s] = true;

            while (!q.isEmpty()) {
                int v = q.poll();
                inq[v] = false;
                if (dist[v] == INF) continue;
                for (int i = 0; i < g.get(v).size(); i++) {
                    Edge e = g.get(v).get(i);
                    if (e.cap > 0 && dist[e.to] > dist[v] + e.cost) {
                        dist[e.to] = dist[v] + e.cost;
                        pv[e.to] = v;
                        pe[e.to] = i;
                        if (!inq[e.to]) {
                            q.add(e.to);
                            inq[e.to] = true;
                        }
                    }
                }
            }

            if (dist[t] == INF) break;

            for (int v = t; v != s; v = pv[v]) {
                Edge e = g.get(pv[v]).get(pe[v]);
                e.cap--;
                g.get(v).get(e.rev).cap++;
            }
            total += dist[t];
        }
        return total;
    }

    void run() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt() / 2;
        N = 1 + n + A + 1;
