            int j = n * 2 - 1 - i;
            int ai = s[i] - 'a';
            int aj = s[j] - 'a';
            for (int a = 0; a < A; a++) {
                int val;
                if (a == ai && a == aj) val = Math.max(b[i], b[j]);
                else if (a == ai) val = b[i];
                else if (a == aj) val = b[j];
                else val = 0;
                addEdge(1 + i, 1 + n + a, 1, -val);
            }
        }

        int[] cnt = new int[A];
        for (int i = 0; i < n * 2; i++) cnt[s[i] - 'a']++;
        for (int a = 0; a < A; a++) addEdge(1 + n + a, T, cnt[a], 0);

        System.out.println(-minCostFlow(S, T));
    }

    public static void main(String[] args) {
        new CF884F().run();
    }
}

