        Edge a = new Edge(to, g.get(to).size(), cap, cost);
        Edge b = new Edge(v, g.get(v).size(), 0, -cost);
        g.get(v).add(a);
        g.get(to).add(b);
    }

    int minCostFlow(int s, int t) {
        pot = new int[N];
        Arrays.fill(pot, INF);
        pot[s] = 0;

        for (int it = 0; it < N - 1; it++) {
            boolean upd = false;
            for (int v = 0; v < N; v++) {
                if (pot[v] == INF) continue;
                for (Edge e : g.get(v)) {
                    if (e.cap > 0 && pot[e.to] > pot[v] + e.cost) {
                        pot[e.to] = pot[v] + e.cost;
                        upd = true;
                    }
                }
            }
            if (!upd) break;
        }

        int total = 0;
        while (true) {
            int[] dist = new int[N];
            int[] pv = new int[N];
            int[] pe = new int[N];
            Arrays.fill(dist, INF);
            dist[s] = 0;

            PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
            pq.add(new long[] {0, s});

            while (!pq.isEmpty()) {
                long[] cur = pq.poll();
                int v = (int) cur[1];
                int d = (int) cur[0];
                if (d != dist[v]) continue;
                for (int i = 0; i < g.get(v).size(); i++) {
                    Edge e = g.get(v).get(i);
                    if (e.cap <= 0) continue;
                    int nd = d + e.cost + pot[v] - pot[e.to];
                    if (dist[e.to] > nd) {
                        dist[e.to] = nd;
                        pv[e.to] = v;
                        pe[e.to] = i;
                        pq.add(new long[] {nd, e.to});
