class Graph {
    private int vNum;
    private int src;
    private int sink;
    private List<Edge>[] adj;
    private int[] p;
    private int[] d;
    private int[] pot;

    private static class Edge {
        int to, rev, cap, cost;
        Edge(int to, int rev, int cap, int cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }

    public Graph(int vNum, int src, int sink) {
        this.vNum = vNum;
        this.src = src;
        this.sink = sink;
        adj = new List[vNum];
        for (int i = 0; i < vNum; i++) adj[i] = new ArrayList<>();
        p = new int[vNum];
        d = new int[vNum];
        pot = new int[vNum];
    }

    public void addEdge(int from, int to, int capacity, int cost) {
        adj[from].add(new Edge(to, adj[to].size(), capacity, cost));
        adj[to].add(new Edge(from, adj[from].size() - 1, 0, -cost));
    }

    private boolean findCheapestPath() {
        Arrays.fill(d, Integer.MAX_VALUE);
        Arrays.fill(p, -1);
        d[src] = 0;
        PriorityQueue<Pair> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a.dist));
        pq.add(new Pair(src, 0));
        while (!pq.isEmpty()) {
            Pair cur = pq.poll();
            int u = cur.node;
            if (cur.dist != d[u]) continue;
            for (Edge e : adj[u]) {
                if (e.cap > 0) {
                    int nd = d[u] + e.cost + pot[u] - pot[e.to];
                    if (nd < d[e.to]) {
                        d[e.to] = nd;
                        p[e.to] = u;
                        pq.add(new Pair(e.to, nd));
                    }
                }
            }
        }
        for (int i = 0; i < vNum; i++) {
            if (d[i] < Integer.MAX_VALUE) pot[i] += d[i];
        }
        return p[sink] != -1;
    }

    private static class Pair {
        int node, dist;
        Pair(int node, int dist) {
            this.node = node;
            this.dist = dist;
        }
    }

    private int[] augmentPath(int from, int to, int flow) {
        int pathCost = 0;
        for (int cur = to; cur != from; cur = p[cur]) {
            int prev = p[cur];
            for (Edge e : adj[prev]) {
                if (e.to == cur && e.cap > 0) {
                    flow = Math.min(flow, e.cap);
                    break;
                }
            }
        }
        for (int cur = to; cur != from; cur = p[cur]) {
            int prev = p[cur];
            for (Edge e : adj[prev]) {
                if (e.to == cur && e.cap > 0) {
                    e.cap -= flow;
                    adj[cur].get(e.rev).cap += flow;
                    pathCost += e.cost * flow;
                    break;
                }
            }
        }
        return new int[]{flow, pathCost};
    }

    public int[] getMinCostMaxFlow() {
        int flow = 0;
        int totalCost = 0;
        while (findCheapestPath()) {
            int[] result = augmentPath(src, sink, Integer.MAX_VALUE);
            flow += result[0];
            totalCost += result[1];
        }
        return new int[]{flow, totalCost};
    }
}

