import java.util.Arrays;
import java.util.StringTokenizer;

public class G {
    static int n, m;

    public static void main(String[] args) throws IOException {
        MyScanner sc = new MyScanner();
        PrintWriter out = new PrintWriter(System.out);

        n = sc.nextInt();
        m = sc.nextInt();
        int s = sc.nextInt() - 1;
        long t = sc.nextLong();

        int[] next = new int[n];
        Arrays.fill(next, -1);

        while (t % n != 0) {
            int x = (int) (t % n);
            s = advance(s, x);
            t--;
        }

        long cant = t / n;
        int prevs = s;

        while (cant > 0 && next[s] == -1) {
            s = fullStep(s);
            next[prevs] = s;
            prevs = s;
            cant--;
        }

        if (cant > 0) {
            long cicle = 1;
            prevs = s;
            while (next[prevs] != s) {
                cicle++;
                prevs = next[prevs];
            }
            long total = cant % cicle;
            for (long i = 0; i < total; i++) {
                s = next[s];
            }
        }

        out.println(s + 1);
        out.flush();
    }

    static int advance(int s, int x) {
        if (s < m) {
            s += x;
        } else {
            s += n - x;
        }
        return s % n;
    }

    static int fullStep(int s) {
        for (int i = n - 1; i > 0; i--) {
            if (s < m) {
                s += i;
            } else {
                s += n - i;
