import java.io.PrintWriter;
import java.util.*;
import java.util.function.*;

public class G {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        final int n = sc.nextInt();
        final int m = sc.nextInt();
        int s = sc.nextInt() - 1;
        long t = sc.nextLong();

        BiFunction<Integer, Integer, Integer> step = (pos, x) -> {
            int p = pos;
            if (p < m) {
                p += x;
            } else {
                p += n - x;
            }
            return p % n;
        };

        Function<Integer, Integer> full = pos -> {
            int p = pos;
            for (int i = n - 1; i > 0; i--) {
                if (p < m) {
                    p += i;
                } else {
                    p += n - i;
                }
                if (p >= n) {
                    p -= n;
                }
            }
            return p;
        };

        int[] next = new int[n];
        Arrays.fill(next, -1);

        while (t % n != 0) {
            s = step.apply(s, (int) (t % n));
            t--;
        }

        long cant = t / n;
        int prevs = s;

        while (cant > 0 && next[s] == -1) {
            s = full.apply(s);
            next[prevs] = s;
            prevs = s;
            cant--;
        }

        if (cant > 0) {
            long cicle = 1;
            prevs = s;
            while (next[prevs] != s) {
                cicle++;
                prevs = next[prevs];
            }
            long total = cant % cicle;
            for (long i = 0; i < total; i++) {
                s = next[s];
            }
        }

        out.println(s + 1);
        out.flush();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

public class G {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        Iterator<String> tokens = br.lines()
                .flatMap(line -> Arrays.stream(line.trim().split("\\s+")))
                .filter(token -> !token.isEmpty())
                .iterator();

        PrintWriter out = new PrintWriter(System.out);

        int n = Integer.parseInt(tokens.next());
        int m = Integer.parseInt(tokens.next());
        int s = Integer.parseInt(tokens.next()) - 1;
        long t = Long.parseLong(tokens.next());

        while (t % n != 0) {
            s = advance(s, (int) (t % n), m, n);
            t--;
        }

        long cant = t / n;
        List<Integer> order = new ArrayList<>();
        Map<Integer, Integer> seen = new HashMap<>();

        while (cant > 0 && !seen.containsKey(s)) {
            seen.put(s, order.size());
            order.add(s);
            s = advanceFull(s, m, n);
            cant--;
        }

        if (cant > 0) {
            int start = seen.get(s);
            long cycleLen = order.size() - start;
            long total = cant % cycleLen;
            for (long i = 0; i < total; i++) {
                s = advanceFull(s, m, n);
            }
        }

        out.println(s + 1);
        out.flush();
    }

    static int advance(int s, int x, int m, int n) {
        if (s < m) {
            return (s + x) % n;
        }
        return (s + n - x) % n;
    }

    static int advanceFull(int s, int m, int n) {
        for (int i = n - 1; i > 0; i--) {
            s = advance(s, i, m, n);
        }
        return s;
    }
}

