public class G {
    public static void main(String[] args) throws IOException {
        FastReader in = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int m = in.nextInt();
        int s = in.nextInt() - 1;
        long t = in.nextLong();

        while (t % n != 0) {
            int x = (int) (t % n);
            s = apply(s, x, m, n);
            t--;
        }

        long cant = t / n;
        Map<Integer, Integer> next = new HashMap<>();

        while (cant > 0 && !next.containsKey(s)) {
            int before = s;
            s = applyAll(s, m, n);
            next.put(before, s);
            cant--;
        }

        if (cant > 0) {
            long cycle = 1;
            int p = next.get(s);
            while (p != s) {
                p = next.get(p);
                cycle++;
            }
            long rem = cant % cycle;
            while (rem-- > 0) {
                s = next.get(s);
            }
        }

        out.println(s + 1);
        out.flush();
    }

    static int apply(int s, int x, int m, int n) {
        if (s < m) {
            return (s + x) % n;
        }
        return (s + n - x) % n;
    }

    static int applyAll(int s, int m, int n) {
        for (int i = n - 1; i >= 1; i--) {
            if (s < m) {
                s = (s + i) % n;
            } else {
                s = (s + n - i) % n;
            }
        }
        return s;
    }

