            term = term * invFact[n + m] % MOD;
            phaseSize += term;
            if (phaseSize >= MOD) phaseSize -= MOD;
        }

        long answer = 0;
        for (int k = 1; k <= n; k++) {
            long numPhases = (long) (m + k) % MOD * smallInv(k) % MOD;
            long term = ncr(n, k) * numPhases % MOD * phaseSize % MOD;
            if ((k & 1) == 1) answer = (answer + term) % MOD;
            else answer = (answer - term + MOD) % MOD;
        }

        PrintWriter out = new PrintWriter(System.out);
        out.println(answer);
        out.close();
    }

    static void precompute(int max) {
