    static class ModArith {
        final long MOD = 998244353L;
        int[] fact = new int[8];
        int[] invFact = new int[8];
        int factSize = 1;
        int invFactSize = 1;

        ModArith() {
            fact[0] = 1;
            invFact[0] = 1;
        }

        long fact(int n) {
            if (n < 0) throw new AssertionError();
            if (factSize <= n) {
                int old = factSize;
                while (fact.length <= n) fact = Arrays.copyOf(fact, fact.length << 1);
                for (int i = old; i <= n; i++) {
                    fact[i] = (int) (fact[i - 1] * (long) i % MOD);
                }
                factSize = n + 1;
            }
            return fact[n];
        }

        long fInv(int n) {
            if (n < 0) throw new AssertionError();
            if (invFactSize <= n) {
                int lastKnown = invFactSize - 1;
                while (invFact.length <= n) invFact = Arrays.copyOf(invFact, invFact.length << 1);
                long cur = inv(fact(n));
                invFact[n] = (int) cur;
                for (int i = n - 1; i > lastKnown; i--) {
                    cur = cur * (i + 1) % MOD;
