public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        int max = n + m;
        long[] inv = new long[max + 1];
        if (max >= 1) {
            inv[1] = 1;
        }
        for (int i = 2; i <= max; i++) {
            inv[i] = MOD - (MOD / i) * inv[(int) (MOD % i)] % MOD;
        }

        long phase = 1;
        long p = 1;
        for (int i = 0; p != 0; i++) {
            p = p * (n - i) % MOD * inv[n + m - i] % MOD;
            phase += p;
            if (phase >= MOD) phase -= MOD;
        }

        long[] fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        long[] invFact = new long[n + 1];
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n; i >= 1; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        long answer = 0;
        for (int k = 1; k <= n; k++) {
            long numPhases = ((long) m + k) % MOD * inv[k] % MOD;
            long e = numPhases * phase % MOD;
            long combination = fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
            long term = combination * e % MOD;

            if ((k & 1) == 1) {
                answer += term;
                if (answer >= MOD) answer -= MOD;
            } else {
                answer -= term;
                if (answer < 0) answer += MOD;
            }
        }

        out.println(answer);
        out.close();
    }

    static long modPow(long base, long exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = result * base % MOD;
            }
            base = base * base % MOD;
            exp >>= 1;
        }
        return result;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        long phase = (n + m + 1L) % MOD * inverse(m + 1L) % MOD;

        long combination = 1;
        long answer = 0;

        for (int k = 1; k <= n; k++) {
            long invK = inverse(k);
            combination = combination * (n - k + 1) % MOD * invK % MOD;
            long e = ((long) m + k) % MOD * invK % MOD * phase % MOD;
            long term = combination * e % MOD;

            if ((k & 1) == 1) {
                answer += term;
                if (answer >= MOD) answer -= MOD;
            } else {
                answer -= term;
                if (answer < 0) answer += MOD;
            }
        }

        out.println(answer);
        out.close();
    }

    static long inverse(long value) {
        long g = MOD;
        long x = 0;
        long y = 1;
        for (long r = value; r != 0; ) {
            long q = g / r;
            g %= r;

            long tmp = g;
            g = r;
            r = tmp;

            x -= q * y;

            tmp = x;
            x = y;
            y = tmp;
        }
        x %= MOD;
        if (x < 0) x += MOD;
        return x;
    }
}

