    static class Solver {
        void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            Modular mod = new Modular();
            mod.ensureInvFact(n + m);

            long phaseSize = 1;
            long p = 1;
            for (int i = 0; p != 0; i++) {
                p = mod.mult(p, n - i, mod.smallInv(n + m - i));
                phaseSize = mod.add(phaseSize, p);
            }

            long answer = 0;
            for (int k = 1; k <= n; k++) {
                long term = mod.mult(mod.ncr(n, k), m + k, mod.smallInv(k), phaseSize);
                if ((k & 1) == 1) {
                    answer = mod.add(answer, term);
                } else {
                    answer = mod.subtract(answer, term);
                }
            }
            out.println(answer);
        }
    }

    static class Modular {
        final long MOD = 998244353L;
        List<Integer> factorial = new ArrayList<>(Arrays.asList(1));
        List<Integer> invFactorial = new ArrayList<>(Arrays.asList(1));

        void ensureInvFact(int n) {
            fInv(n);
        }

        long fact(int n) {
            while (factorial.size() <= n) {
                int current = factorial.size();
                factorial.add((int) mult(factorial.get(current - 1), current));
            }
            return factorial.get(n);
        }

        long fInv(int n) {
            int last = invFactorial.size() - 1;
            if (last < n) {
                int len = n - last;
                long[] temp = new long[len];
                temp[0] = inv(fact(n));
                for (int i = 1; i < len; i++) {
                    temp[i] = mult(temp[i - 1], n - i + 1);
                }
                for (int i = len - 1; i >= 0; i--) {
                    invFactorial.add((int) temp[i]);
                }
            }
            return invFactorial.get(n);
        }

        long ncr(int n, int r) {
            if (r < 0 || n < r) return 0;
            return mult(fact(n), fInv(r), fInv(n - r));
        }

        long smallInv(int n) {
            return mult(fInv(n), fact(n - 1));
        }

        long add(long a, long b) {
            long v = a + b;
            return v < MOD ? v : v - MOD;
        }

        long subtract(long a, long b) {
            long v = a - b;
            return v < 0 ? v + MOD : v;
        }

        long mult(long... values) {
            long r = 1;
            for (long value : values) {
                r = (r * value) % MOD;
            }
            return r;
        }

        long inv(long value) {
            long g = MOD, x = 0, y = 1;
            for (long r = value; r != 0; ) {
                long q = g / r;
                g %= r;
                long temp = g;
                g = r;
                r = temp;
                x -= q * y;
                temp = x;
                x = y;
                y = temp;
            }
            if (g != 1) throw new AssertionError();
            if (y != MOD && y != -MOD) throw new AssertionError();
            long v = x % MOD;
            if (v < 0) v += MOD;
            return v;
        }
    }

    static class InputReader {
        public final BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
