    static void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        int N = n + m;
        precompute(N);

        long phaseSize = Stream.iterate(new long[]{1, 0}, state -> {
            long p = state[0];
            long i = state[1];
            long nextP = (i < n) ? p * (n - i) % MOD * smallInverse((int) (N - i)) % MOD : 0;
            return new long[]{nextP, i + 1};
        }).limit((long) n + 1).mapToLong(state -> state[0]).reduce(0L, Main::add);

        long answer = LongStream.rangeClosed(1, n)
                .mapToLong(k -> {
                    long sign = ((k & 1) == 1) ? 1 : MOD - 1;
                    return mul(sign, ncr(n, (int) k), m + k, smallInverse((int) k), phaseSize);
                })
                .reduce(0L, Main::add);

        out.println(answer);
    }

    static void precompute(int N) {
        fact = new long[N + 1];
        invFact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[N] = modPow(fact[N], MOD - 2);
        for (int i = N; i >= 1; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }
    }

    static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }

    static long smallInverse(int x) {
