	private PrintWriter out;

	void solve() {
		int a = ni(), b = ni(), l = ni(), r = ni();
		String fin = new String();
		for (int i = 0; i < a; i++)
			fin = fin + (char) ('a' + i);
		for (int i = 0; i < b; i++)
			fin = fin + (char) ('a' + a - 1);
		int x = l % (a + b);
		if (x == 0)
			x = a + b;
		fin = fin.substring(x - 1);
		HashSet<Character> set = new HashSet<Character>();
		for (int i = fin.length() - 1; i >= 0 && i >= fin.length() - a; i--)
			set.add(fin.charAt(i));
		int op = a;
		for (int i = 0; i < 26 && op > 0; i++) {
			if (set.contains((char) ('a' + i)))
				continue;
			fin = fin + (char) ('a' + i);
			op--;
		}
		char ch = fin.charAt(fin.length() - 1);
		for (int i = 0; i < b; i++)
			fin = fin + ch;
		set.clear();
		for (int i = fin.length() - 1; i >= 0 && i >= fin.length() - a; i--)
			set.add(fin.charAt(i));
		op = a;
		for (int i = 0; i < 26 && op > 0; i++) {
			if (set.contains((char) ('a' + i)))
				continue;
			fin = fin + (char) ('a' + i);
			op--;
		}
		ch = fin.charAt(fin.length() - 1);
		for (int i = 0; i < b; i++)
			fin = fin + ch;
		set.clear();
		for (int i = 0; i <= r - l && i < fin.length(); i++)
			set.add(fin.charAt(i));
		out.println(set.size());
	}

	void soln() {
		is = System.in;
		out = new PrintWriter(System.out);
		long s = System.currentTimeMillis();
		solve();
		out.flush();
		tr(System.currentTimeMillis() - s + "ms");
	}

	public static void main(String[] args) throws Exception {
		new CODEFORCES().soln();
	}

	// To Get Input
	// Some Buffer Methods
	private byte[] inbuf = new byte[1024];
	public int lenbuf = 0, ptrbuf = 0;

	private int readByte() {
		if (lenbuf == -1)
			throw new InputMismatchException();
		if (ptrbuf >= lenbuf) {
			ptrbuf = 0;
			try {
				lenbuf = is.read(inbuf);
			} catch (IOException e) {
				throw new InputMismatchException();
			}
			if (lenbuf <= 0)
				return -1;
		}
		return inbuf[ptrbuf++];
	}

	private boolean isSpaceChar(int c) {
		return !(c >= 33 && c <= 126);
	}

	private int skip() {
		int b;
		while ((b = readByte()) != -1 && isSpaceChar(b))
			;
		return b;
	}

	private double nd() {
		return Double.parseDouble(ns());
	}

	private char nc() {
		return (char) skip();
	}

	private String ns() {
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while (!(isSpaceChar(b))) { // when nextLine, (isSpaceChar(b) && b != '
									// ')
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private char[] ns(int n) {
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while (p < n && !(isSpaceChar(b))) {
			buf[p++] = (char) b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private char[][] nm(int n, int m) {
		char[][] map = new char[n][];
		for (int i = 0; i < n; i++)
			map[i] = ns(m);
		return map;
	}

	private int[] na(int n) {
		int[] a = new int[n];
		for (int i = 0; i < n; i++)
			a[i] = ni();
		return a;
	}

	private int ni() {
		int num = 0, b;
		boolean minus = false;
		while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
			;
		if (b == '-') {
			minus = true;
			b = readByte();
		}

		while (true) {
			if (b >= '0' && b <= '9') {
				num = num * 10 + (b - '0');
			} else {
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private long nl() {
		long num = 0;
