        while (c != -1 && !(c == ' ' || c == '\n' || c == '\t' || c == '\r' || c == '\f')) {
            int digit = c - '0';
            if (digit < 0 || digit > 9) throw new NumberFormatException();
            value = value * 10 + digit;
            c = in.read();
        }
        return sign * value;
    }
}

