        int A = sc.nextInt();
        int B = sc.nextInt();
        int L = sc.nextInt();
        int R = sc.nextInt();
        System.out.println(solve(A, B, L, R));
    }

    static int solve(int a, int b, int l, int r) {
        if ((r - l + 1) > 2 * (a + b)) {
            return a <= b ? a + 1 : 2 * a - b;
        }

        int period = a + b;
        int[] seq = new int[3 * period + 1];
        int last = 0;

        for (int i = 1; i <= a; i++) {
            seq[i] = i;
            last = i;
        }

        for (int i = a + 1; i <= period; i++) {
            seq[i] = last;
        }

        for (int i = period + 1; i <= period + a; i++) {
            int x = 1;
            while (present(seq, x, b + 1, i - 1)) {
                x++;
            }
            seq[i] = x;
            last = x;
        }

        for (int i = period + a + 1; i <= period + period; i++) {
            seq[i] = last;
        }

        for (int i = 2 * period + 1; i <= 3 * period; i++) {
            seq[i] = seq[i - period];
        }

        boolean[] seen = new boolean[25];
        int start = l % period;
        if (start == 0) {
            start += period;
        }
        int end = r - l + start;
        if (end < start) {
            end += period;
        }

        for (int i = start; i <= end; i++) {
            seen[seq[i]] = true;
        }

        int ans = 0;
        for (int i = 1; i <= 24; i++) {
            if (seen[i]) {
                ans++;
            }
        }
        return ans;
    }

    static boolean present(int[] arr, int value, int from, int to) {
        for (int i = from; i <= to; i++) {
            if (arr[i] == value) {
                return true;
            }
        }
        return false;
    }
}

