        int r = in.nextInt();
        System.out.println(fun(a, b, l, r));
    }

    static int fun(int a, int b, int l, int r) {
        if ((r - l + 1) > 2 * (a + b)) {
            if (a <= b) {
                return a + 1;
            }
            return 2 * a - b;
        }

        int n = a + b;
        int[] seq = new int[3 * n + 1];
        int last = 0;

        for (int i = 1; i <= a; i++) {
            seq[i] = i;
            last = i;
        }

        for (int i = a + 1; i <= n; i++) {
            seq[i] = last;
        }

        for (int i = n + 1; i <= n + a; i++) {
            int x = 1;
            while (contains(seq, x, b + 1, i - 1)) {
                x++;
            }
            seq[i] = x;
            last = x;
        }

        for (int i = n + a + 1; i <= 2 * n; i++) {
            seq[i] = last;
        }

        for (int i = 2 * n + 1; i <= 3 * n; i++) {
            seq[i] = seq[i - n];
        }

        int[] seen = new int[25];
        int start = l % n;
        if (start == 0) {
            start += n;
        }
        int end = r - l + start;
        if (end < start) {
            end += n;
        }

        for (int i = start; i <= end; i++) {
            seen[seq[i]] = 1;
        }

        return IntStream.range(1, 25).map(i -> seen[i]).sum();
    }

    static boolean contains(int[] arr, int v, int l, int r) {
        for (int i = l; i <= r; i++) {
            if (arr[i] == v) {
                return true;
            }
        }
        return false;
    }
}

