        int l = Integer.parseInt(st.nextToken()) - 1;
        int r = Integer.parseInt(st.nextToken()) - 1;
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(solve(a, b, l, r));
        pw.flush();
    }

    private static int solve(int a, int b, int l, int r) {
        int min = 26;
        for (char p = 'a'; p <= 'z'; p++) {
            int qStart = 'a' + a;
            for (char q = (char) qStart; q <= 'z'; q++) {
                StringBuilder rep = buildRepetition(a, b, p, q);
                min = Math.min(min, countLetters(rep, l, r));
            }
        }
        return min;
    }

    private static StringBuilder buildRepetition(int a, int b, char p, char q) {
        StringBuilder rep = new StringBuilder();
        for (int i = 0; i < a; i++) {
            rep.append((char) ('a' + i));
        }
        for (int i = 0; i < b; i++) {
            rep.append(p);
        }
        outer:
        for (int i = 0; i < a; i++) {
            boolean[] seen = new boolean[26];
            for (int j = b; j < a + b + i; j++) {
                seen[rep.charAt(j) - 'a'] = true;
            }
            for (int c = 0; c < 26; c++) {
                if (!seen[c]) {
                    rep.append((char) ('a' + c));
                    continue outer;
                }
            }
        }
        for (int i = 0; i < b; i++) {
            rep.append(q);
        }
        return rep;
    }

    private static int countLetters(StringBuilder rep, int l, int r) {
        boolean[] flag = new boolean[26];
        if (r - l + 1 >= 100_000) {
            for (int i = 0; i < rep.length(); i++) {
                flag[rep.charAt(i) - 'a'] = true;
            }
        } else {
            for (int i = l; i <= r; i++) {
                flag[rep.charAt(i % rep.length()) - 'a'] = true;
            }
        }
        int ans = 0;
        for (int i = 0; i < 26; i++) {
            if (flag[i]) ans++;
        }
        return ans;
    }
}

import java.util.BitSet;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int l = sc.nextInt() - 1;
        int r = sc.nextInt() - 1;

        int min = 26;
        for (int p = 'a'; p <= 'z'; p++) {
            for (int q = (char) ('a' + a); q <= 'z'; q++) {
                StringBuilder rep = new StringBuilder();
                for (int i = 0; i < a; i++) rep.append((char) ('a' + i));
                for (int i = 0; i < b; i++) rep.append((char) p);

                for (int i = 0; i < a; i++) {
                    BitSet seen = new BitSet(26);
                    for (int j = b; j < a + b + i; j++) {
                        int idx = rep.charAt(j) - 'a';
                        if (idx < 0 || idx >= 26) throw new ArrayIndexOutOfBoundsException(idx);
                        seen.set(idx);
                    }
                    int missing = seen.nextClearBit(0);
                    if (missing <= 25) {
                        rep.append((char) ('a' + missing));
                    }
                }

                for (int i = 0; i < b; i++) rep.append((char) q);

                BitSet flag = new BitSet(26);
                if (r - l + 1 >= 100_000) {
                    for (int i = 0; i < rep.length(); i++) {
                        int idx = rep.charAt(i) - 'a';
                        if (idx < 0 || idx >= 26) throw new ArrayIndexOutOfBoundsException(idx);
                        flag.set(idx);
                    }
                } else {
                    for (int i = l; i <= r; i++) {
                        int idx = rep.charAt(i % rep.length()) - 'a';
                        if (idx < 0 || idx >= 26) throw new ArrayIndexOutOfBoundsException(idx);
                        flag.set(idx);
                    }
                }
                min = Math.min(min, flag.cardinality());
            }
        }
        System.out.println(min);
    }
}

