            last = i;
        }

        for (int i = a + 1; i <= p; i++) {
            seq[i] = last;
        }

        for (int i = p + 1; i <= p + a; i++) {
            int candidate = 1;
            while (contains(seq, candidate, b + 1, i - 1)) {
                candidate++;
            }
            seq[i] = candidate;
            last = candidate;
        }

        for (int i = p + a + 1; i <= 2 * p; i++) {
            seq[i] = last;
        }

        for (int i = 2 * p + 1; i <= 3 * p; i++) {
