        }

        boolean[] used = new boolean[25];
        int start = l % p;
        if (start == 0) start = p;
        int end = r - l + start;
        if (end < start) end += p;

        for (int i = start; i <= end; i++) {
            used[seq[i]] = true;
        }

        int ans = 0;
        for (int i = 1; i <= 24; i++) {
            if (used[i]) ans++;
        }

        return ans;
    }

    static boolean contains(int[] arr, int value, int from, int to) {
