        if (start == 0) start = p;
        int end = r - l + start;
        if (end < start) end += p;

        for (int i = start; i <= end; i++) {
            seen[s[i]] = true;
        }

        int res = 0;
        for (int i = 1; i <= 24; i++) {
            if (seen[i]) res++;
        }

        return res;
    }

    static boolean exists(int[] arr, int value, int from, int to) {
