        }

        for (int i = a + 1; i <= p; i++) {
            seq.set(i, cur);
        }

        for (int i = p + 1; i <= p + a; i++) {
            int candidate = 1;
            while (contains(seq, candidate, b + 1, i - 1)) {
                candidate++;
            }
            seq.set(i, candidate);
            cur = candidate;
        }

        for (int i = p + a + 1; i <= 2 * p; i++) {
            seq.set(i, cur);
        }

        for (int i = 2 * p + 1; i <= 3 * p; i++) {
            seq.set(i, seq.get(i - p));
        }

        boolean[] used = new boolean[25];
        int start = l % p;
        if (start == 0) start = p;
        int end = r - l + start;
        if (end < start) end += p;

        for (int i = start; i <= end; i++) {
            used[seq.get(i)] = true;
        }

        return IntStream.rangeClosed(1, 24).map(i -> used[i] ? 1 : 0).sum();
    }

    static boolean contains(List<Integer> seq, int value, int from, int to) {
        for (int i = from; i <= to; i++) {
            if (seq.get(i) == value) return true;
        }
        return false;
    }
}
